#
# 注意：引擎只读 L1/M1（都是字符串），一个字都不碰这几格，本仓的取值层也与它们无关。
FORMULA_CELLS = ['C7', 'C8', 'C9', 'I1']

# 空表口径（2026-10-10 定）：**下载行为一定发生**，某份表真没下到时
# scripts/build_report.py 会直接报「缺少 X 的下载结果」、整份报告不出 —— 流程根本
# 走不到取值层。所以取值层见到的表一定在，「0 行」是正常数据：
#   · 计数格（D6:D9 / D10 / D11 / D12 / D15 / D17 / G5 / G6 / H6 / I6 / G8 / G9）写 **0**
#   · 名次格（14 格告警定性 C133:I134 + 21 格事件定性 C135:I137）全写**空串**
#   · G7 也写空串，但它不是名次格 —— 是"没有可平均的样本"（0 分钟是一个真实可能的均值）；
