#   · EXPECTED_WRITE_CELLS   —— 计划层会落值的格子（written / applied / writes）
#   · EXPECTED_FILE_CHANGES  —— 落盘后相对**模板**真的变了的格子（写空串到本来就空的
#                               C133:I137 在计划层算落值，在文件上却不算变化）
EXPECTED_PARAM_CELLS = ['J1', 'L1', 'M1']
EXPECTED_FILE_CHANGES = ['D10', 'D11', 'D12', 'D15', 'D16', 'D17', 'D6', 'D7', 'D8', 'D9',
                         'G10', 'G16', 'G17', 'G18',
                         'G5', 'G6', 'G8', 'G9', 'H6', 'I6', 'J1', 'L1', 'M1']

