#
# 逐格点名，而不是只数个数 —— 数个数的话，一格偷偷吞掉缺数、另一格被顺手填了 0，
# 总数照样对得上。请点「哪些格进了 errors」的地方一律用这一组。
EXPECTED_ALARM_CELLS = [
    'C133', 'D133', 'E133', 'F133', 'G133', 'H133', 'I133',
    'C134', 'D134', 'E134', 'F134', 'G134', 'H134', 'I134',
]

# 要读告警表的另外 4 格：G5「威胁告警总」（只读告警表）与 G6/H6/I6「核心系统威胁告警数量」
# （读资产表「所属业务」-> IP，再按告警表「主机IP」圈定；系统名与 D3/D4/D5 同取
# --business-systems）。
#
# 与 ALARM_ADDRS（那 14 格）分开列，是因为错的来源不同：14 格认的是「告警定性」这一列，
# 这 4 格认的是「GPT研判结论」（G6/H6/I6 还要「主机IP」）+ 资产表 + CLI 槽位。
# 但「本段没接告警表 / 告警表缺研判列」这件事对两组往往是同一个后果，
# 所以凡是要清点「哪些格子因为这份输入而报了错」的地方，一律用 EXPECTED_ALARM_GROUP。
