# ---------------------------------------------------------------------------
# 事件表四个时长列（表格预处理第 4 步）的 fixture
# ---------------------------------------------------------------------------
#
# 列序照**真实导出**（outputs 产物里 创建时间=G / 检出时间=T / 闭环时间=W /
# 遏制时间=AA / 研判时间=AB），列名逐字取自那份产物 —— 编一个别的名字就等于
# 把这条验收建立在一个假前提上。
#
# 九行数据把这一步的每条边界都铺满（行号 = fixture 下标 + 1）：
#   · 两个时间都在 -> 算出来（分钟数，2 位小数）
#   · 半角 `-` / 全角 `－` / 空串 -> 这一对留空、**同一行别的对照算**
#   · 解析不出来的值（`N/A` / `待补`）-> 留空，但算「解析失败」而不是「空值」
#   · 负差值（闭环 / 遏制早于起点）-> **不合法、那一格留空**（用户口径 2026-10-12），
#     另计数报到日志里（整列一半是负数 = 多半取错了列）
#   · 秒缺失的 `2026-07-22 10:09` 形态 -> 收
#   · **datetime 格**（不是文本）-> 收。真实产物里两种形态并存，而且**构建那一刻**格子
#     里是第三种形态：裸序列号 + 日期格式（build_report.py 的 rebuild_sheet 按
#     to_serial_number 的口径写序列号），读回来才变成 datetime —— 三种都得认，
#     只认字符串的话真实流水线上这四列会整片空
#
# 四列取值（H/I/J/K）**刻意互不相等**，看一眼就能认出哪一列串到了别的列上：
#   遏制 = 遏制时间 - 研判时间 / 识别 = 创建 - 检出 / 处置 = 闭环 - 创建 / 响应 = 研判 - 检出
