def write_sheet(path, aoa):
    wb = Workbook()
    ws = wb.active
    for row in aoa:
        ws.append(row)
    wb.save(path)
    return str(path)


def make_fixtures(directory):
    """表头必须用**真实列名**：资产表要有「IP地址」「互联网暴露」，事件表要有「影响资产」，
    否则表格预处理会按「平台改列名」直接抛错 —— 那是刻意的失败口径，不是 bug。

    五份表一份都不能少：build_report.py 的 TABLE_SHEET_NAMES 把「缺哪份下载结果」
    当硬错误（宁可不出报告，也不出一份缺 sheet 的报告）。这里的内容只够把各 sheet
    填出来，与取值层无关 —— 取值层那份 fixture 是 make_core_system_tables。
    """
    directory.mkdir(parents=True, exist_ok=True)
    return {
        # 资产表与事件表用 ASSET_EXPOSURE_TABLE / EVENT_EXPOSURE_TABLE —— 【3.5】那一段
        # 要拿同一份数据另起一份拷贝去跑预处理（预处理是原地改写，不能动公共这份）
        'asset': {'filePath': write_sheet(directory / 'asset.xlsx', ASSET_EXPOSURE_TABLE)},
        'alarm': {'filePath': write_sheet(directory / 'alarm.xlsx', [
            ['表头A', '表头B'], ['y', 2],
        ])},
        'event': {'filePath': write_sheet(directory / 'event.xlsx', EVENT_EXPOSURE_TABLE)},
        'vuln': {'filePath': write_sheet(directory / 'vuln.xlsx', [
            ['风险资产', '威胁标签', '漏洞名称'],
            ['10.0.0.1', '高可利用', 'v1'],
        ])},
        'weakpwd': {'filePath': write_sheet(directory / 'weakpwd.xlsx', [
            ['风险资产', '弱点类型'],
            ['10.0.0.1', 'ssh弱口令'],
        ])},
    }


def make_alarm_table(directory):
    """告警定性统计（C133:I134）专用 fixture，见 ALARM_TABLE 的说明。

    与 make_fixtures 里那份 'alarm' 是两件事：那份（表头是「表头A/表头B」）只用来把
    报告的 sheet 填出来，压根不进取值层；这份表头是真的「告警定性」，
    用来验「有告警行时那 14 格真的落值」（没接告警表时那 14 格是空表、写空串）。
    """
    directory.mkdir(parents=True, exist_ok=True)
    return write_sheet(directory / 'alarm-qualified.xlsx', ALARM_TABLE)


def make_event_table(directory):
    """事件定性统计（C135:I137）专用 fixture，见 EVENT_TABLE_ROWS 的说明。

    与 make_fixtures 里那份 'event'（表头是「影响资产/事件名称」）不是一回事：
    那份只用来把报告的 sheet 填出来，压根不进取值层；这份表头是真的「GPT定性标签」，
    用来验「有事件表时那 21 格真的落值」（没接事件表时那份是空表、21 格写空串）。
    """
    directory.mkdir(parents=True, exist_ok=True)
    return write_sheet(directory / 'event-qualified.xlsx', EVENT_TABLE_ROWS)


def make_threat_alarm_tables(directory):
    """威胁告警数量（G5 + G6/H6/I6）专用 fixture，两张表：

    告警表见 VERDICT_TABLE 的说明（表头是真的「GPT研判结论」「主机IP」）；
    资产表沿用核心业务系统那份 CORE_ASSET_TABLE —— 同一批业务系统、同一批 IP，
    这样「同一台机器在两个系统的 IP 集合里」这条边界在两段验收里是同一个事实。
    """
    directory.mkdir(parents=True, exist_ok=True)
    return {
        'alarm': write_sheet(directory / 'verdict-alarm.xlsx', VERDICT_TABLE),
        'asset': write_sheet(directory / 'verdict-asset.xlsx', CORE_ASSET_TABLE),
    }


def make_core_system_tables(directory):
    """核心业务系统（D3/D4/D5 + D7/D8/D9）与 D11 专用 fixture，四份表的说明见各自的常量定义。

    与 make_fixtures 里那份 'asset' 是两件事：那份（表头只有「IP地址/互联网暴露」）
    只用来把报告的 sheet 填出来，压根不进取值层；这份带「所属业务」与
    「重要级别」，用来验「有业务归属时风险总数真的算得出来、有重要级别时 D11 真的算得出来」。
    两半都得有 —— 各自都对、接起来不匹配，正是这次"没落盘"的病根。
    """
    directory.mkdir(parents=True, exist_ok=True)
    return {
        'asset': write_sheet(directory / 'core-asset.xlsx', CORE_ASSET_TABLE),
        'vuln': write_sheet(directory / 'core-vuln.xlsx', CORE_VULN_TABLE),
        'weakpwd': write_sheet(directory / 'core-weakpwd.xlsx', CORE_WEAKPWD_TABLE),
        'event': write_sheet(directory / 'core-event.xlsx', CORE_EVENT_TABLE),
    }


# ---------------------------------------------------------------------------
# 【1】登记表全量：写了该写的，也没写不该写的
# ---------------------------------------------------------------------------

def check_plan_registry(checker, bridge):
    """这一条要同时证明三件事：写了该写的 59 格、**没写**不该写的 366 格、
    以及**没传 --business-systems** 时只剩 D3/D4/D5 这三格记 errors
    （真异常 —— 它们写的是**系统名本身**，没有名字就没有可写的）。

    这一段一份总表都不带，所以它就是「空表口径」的落点：计数格
    （D6:D9 与 G6/H6/I6/G10 —— 没传系统就是 0；D10/D11/D12/D15/D17/G5/G8/G9/G17/G18
    —— 表是空的）写 0，名次格（14 格告警定性 + 21 格事件定性）与 G7（威胁平均遏制时间）
    全写空串 —— 都算落值、都**不**进 errors。G9 是均值格却写 0（不是空串）：它的口径是
    "没有就写0"，见上面 EXPECTED_RESPONSE_CELLS 的说明。

    （428 = 59 落值 + 366 unresolved + 3 缺系统名；三个数都随每次转正而变，
     见 EXPECTED_* 常量。D6:D9 与 G6/H6/I6/G10 从前落在这里的"缺系统槽位"那一堆里，
     按用户口径 2026-10-12 改成写 0 —— 只有 D3/D4/D5 留在 errors 里。）

    没写不该写的那些才是这条验收真正防的东西 —— 口径未定的格子被"顺手填个 0"是最隐蔽的错。
    """
    checker.section('1】428 格登记表 + ctx（只比计划，不落盘）')
    plan = call_bridge(bridge, 'plan', 'registry')

    checker.check(len(plan['unresolved']) == EXPECTED_UNRESOLVED,
                  'unresolved 不写入', len(plan['unresolved']), EXPECTED_UNRESOLVED)
    checker.check(len(plan['written']) == EXPECTED_WRITTEN,
                  'written 落值', len(plan['written']), EXPECTED_WRITTEN)
    checker.check(len(plan['writes']) == EXPECTED_WRITTEN,
                  'writes 计划条数', len(plan['writes']), EXPECTED_WRITTEN)
    checker.check(sorted(e['addr'] for e in plan['errors']) == sorted(EXPECTED_NO_SYSTEM_ERRORS),
                  f"errors 只剩「没传系统名」的 {len(EXPECTED_NO_SYSTEM_ERRORS)} 格"
                  "（D3/D4/D5 —— 它们写的是系统名本身，不是算出来的数）",
                  ' '.join(sorted(e['addr'] for e in plan['errors'])),
                  ' '.join(sorted(EXPECTED_NO_SYSTEM_ERRORS)))
    checker.check(not set(EXPECTED_NO_SYSTEM_ERRORS) & set(plan['written']),
                  '没传系统名的那三格一个都没写',
                  '是' if not set(EXPECTED_NO_SYSTEM_ERRORS) & set(plan['written']) else '否')
    checker.check(sorted(plan['written']) == sorted(EXPECTED_WRITE_CELLS),
                  '落值的地址（空表 -> 计数格 0 / 名次格空串，都算落值）',
                  ' '.join(plan['written']), ' '.join(EXPECTED_WRITE_CELLS))
    checker.check(not set(EXPECTED_PARAM_CELLS) & set(plan['unresolved']),
                  'J1/L1/M1 不在 unresolved 里',
                  '是' if not set(EXPECTED_PARAM_CELLS) & set(plan['unresolved']) else '否')

    # 落的值也要对：客户名照抄，报告期是 YYYY/MM/DD **斜杠**（与 PPT 封面的横杠刻意不同）
    values = {w['addr']: w['value'] for w in plan['writes']}
    checker.check(values.get('J1') == '一致验收客户', 'J1 客户名称',
                  json.dumps(values.get('J1'), ensure_ascii=False), '"一致验收客户"')
    checker.check(values.get('L1') == '2026/05/12', 'L1 周期起始日',
                  json.dumps(values.get('L1'), ensure_ascii=False), '"2026/05/12"（斜杠）')
    checker.check(values.get('M1') == '2026/05/13', 'M1 周期结束日',
                  json.dumps(values.get('M1'), ensure_ascii=False), '"2026/05/13"（斜杠）')

    # 空表 -> 计数格写 0（不是空串、不是不写值）
    empty_count_cells = ['D10', 'D11', 'D12', 'D15', 'D16', 'D17', 'G5', 'G8', 'G9']
    zeroed = {addr: values.get(addr) for addr in empty_count_cells}
    checker.check(all(v == 0 for v in zeroed.values()),
                  '空表 -> 计数格（D10/D11/D12/D15/D17/G5/G8/G9）都写 0（是结论，不是缺数）',
                  json.dumps(zeroed, ensure_ascii=False),
                  json.dumps({a: 0 for a in empty_count_cells}, ensure_ascii=False))

    # 空表 -> 名次格写空串（14 格告警定性 + 21 格事件定性）；G7 也写空串，但它进这一组
    # 是因为**没有可平均的样本**（不是"名次不存在"）—— 两种来源同一个落法，同一口径：
    # 这不是计数格，0 分钟是一个真实可能的均值，混不得。
    blank_rank_cells = EXPECTED_ALARM_CELLS + EXPECTED_EVENT_CELLS + EXPECTED_CONTAINED_CELLS
    blanked = {addr: values.get(addr) for addr in blank_rank_cells}
    checker.check(all(v == '' for v in blanked.values()),
                  '空表 -> 名次格（14 格告警定性 + 21 格事件定性）与 G7 都写空串',
                  '是' if all(v == '' for v in blanked.values()) else json.dumps(
                      {a: v for a, v in blanked.items() if v != ''}, ensure_ascii=False))
    return plan


# ---------------------------------------------------------------------------
# 【2】各写模式的语义
# ---------------------------------------------------------------------------

def check_modes(checker, bridge, template):
    checker.section('2】各 mode 语义（JS 出计划 -> Python 落笔 -> 读回来看）')

    plan = call_bridge(bridge, 'plan', 'modes')
    wb = load_workbook(template, data_only=False)
    apply_statistics_writes(wb, plan['writes'])
    ws = wb[TEMPLATE_SHEET]

    def at(addr):
        cell = ws[addr]
        if cell.value is None:
            return None
        text = json.dumps(cell.value, ensure_ascii=False)
        if cell.number_format and cell.number_format != 'General':
            text += f' [z={cell.number_format}]'
        return text

    checker.check(at('D24') == '42', 'D24 取值', at('D24'), '"42"')
    checker.check(at('D12') == '7', 'D12 取值', at('D12'), '"7"')
    checker.check(at('G110') == '7', 'G110 alias（与 D12 同值）', at('G110'), '"7"')
    checker.check(at('D34') == '0.8125 [z=0.00%]', 'D34 percent（值 + 百分号格式）',
                  at('D34'), '"0.8125 [z=0.00%]"')
    checker.check(at('D30') == '"手写"', 'D30 literal', at('D30'), '"手写"')
    # blank 要真把模板原值清掉，而不是"没写进去"—— 所以挑的是模板里有旧值的格子
    checker.check(at('D25') in (None, '""'), 'D25 blank（清掉模板原值）', at('D25'), '(空)')

    # 缺数路径：抛错和返回 undefined 都必须**一个字都不写**，且进 errors（R10/H6 禁止填 0）
    errors = {e['addr']: e['message'] for e in plan['errors']}
    checker.check(at('G99') == at('G101'), 'G99/G101 缺数都没写',
                  f'G99={at("G99")} G101={at("G101")}')
    checker.check(set(errors) == {'G99', 'G101'}, 'errors 覆盖缺数的两格',
                  ' '.join(sorted(errors)), 'G101 G99')
    # unresolved 的格子必须**保持模板原样**：既不写值也不清空（H7）。所以拿模板的真实
    # 旧值当基准比 —— 断言"它是空的"是错的，模板里本来有值的话那反而是被清掉了。
    template_value = load_workbook(template, data_only=False)[TEMPLATE_SHEET]['I124'].value
    checker.check(ws['I124'].value == template_value, 'I124 unresolved（保持模板原样，不写入）',
                  json.dumps(ws['I124'].value, ensure_ascii=False),
                  json.dumps(template_value, ensure_ascii=False))
    checker.check(plan['written'] and 'I124' not in plan['written'],
                  'I124 不在写入计划里', '是' if 'I124' not in plan['written'] else '否')
    checker.check('D25' not in errors, 'blank 不算 error', '是' if 'D25' not in errors else '否')
    checker.note('errors 明细', json.dumps(plan['errors'], ensure_ascii=False))


# ---------------------------------------------------------------------------
# 【3】/【4】端到端
# ---------------------------------------------------------------------------

def check_end_to_end(checker, label, template, report, built, beautify):
    """计划层落 EXPECTED_WRITTEN 格（空表口径：计数格 0 / 名次格空串），但**文件上只有 EXPECTED_FILE_CHANGES 格真变了**。

    计划层 vs 文件层的差别就在名次格：往本来就空的 C133:I137 写空串是"落值"，
    在文件上却不是"变化"。所以这里两个期望分开：
      · written / applied == EXPECTED_WRITE_CELLS
      · 相对模板变化的非公式格 == EXPECTED_FILE_CHANGES

    这里同时查**接线**本身：除了这些格，接上 ctx 不能动任何一格 —— 尤其是公式格，
    取值层不许碰它们（碰了就是把模板的活公式改成死值）。
    """
    title = '4】生产路径（buildReport + ctx + 默认美化）' if beautify \
        else '3】端到端（buildReport + ctx，落盘后再读回来，不美化）'
    checker.section(title)

    stats = built['statistics']
    checker.check(stats['connected'] is True, 'statistics.connected', stats['connected'], True)
    checker.check(len(stats['written']) == EXPECTED_WRITTEN,
                  'statistics.written', len(stats['written']), EXPECTED_WRITTEN)
    checker.check(len(stats['unresolved']) == EXPECTED_UNRESOLVED,
                  'statistics.unresolved', len(stats['unresolved']), EXPECTED_UNRESOLVED)
    checker.check(sorted(e['addr'] for e in stats['errors']) == sorted(EXPECTED_NO_SYSTEM_ERRORS),
                  f"statistics.errors 只剩「没传系统名」的 {len(EXPECTED_NO_SYSTEM_ERRORS)} 格"
                  "（D3/D4/D5）",
                  ' '.join(sorted(e['addr'] for e in stats['errors'])),
                  ' '.join(sorted(EXPECTED_NO_SYSTEM_ERRORS)))
    # 计划写了几格就得落几格，差一格都说明 Python 侧悄悄丢了
    checker.check(len(stats['applied']) == EXPECTED_WRITTEN,
                  'statistics.applied（实际落笔）', len(stats['applied']), EXPECTED_WRITTEN)

    after = value_map(report, TEMPLATE_SHEET)
    changes = changed_addrs(value_map(template, TEMPLATE_SHEET), after)
    value_changes = [a for a in changes if a not in FORMULA_CELLS]
    formula_changes = [a for a in changes if a in FORMULA_CELLS]

    checker.check(value_changes == EXPECTED_FILE_CHANGES,
                  '相对模板有变化的非公式格（写空串到本来就空的格子不算变化）',
                  ' '.join(value_changes) or '（无）', ' '.join(EXPECTED_FILE_CHANGES))
    checker.note('落盘后的值', ' '.join(f'{a}={render(after.get(a))}' for a in EXPECTED_FILE_CHANGES))
    checker.check(formula_changes == FORMULA_CELLS, '公式格缓存值丢失（已知差异，见头注第 4 条）',
                  ' '.join(formula_changes) or '（无）')

    # 公式本身必须还在（R2 模板冻结：不许把活公式改成死值）
    wb = load_workbook(report, data_only=False)
    ws = wb[TEMPLATE_SHEET]
    formulas = {a: ws[a].value for a in FORMULA_CELLS}
    checker.check(all(isinstance(v, str) and v.startswith('=') for v in formulas.values()),
                  '公式格仍是公式', json.dumps(formulas, ensure_ascii=False))

    checker.note('非数据统计 sheet', ' '.join(f"{s['name']}({s['rowCount']}行)" for s in built['sheets']))
    if beautify:
        checker.check(built['beautify']['ok'] is True, '美化已执行', built['beautify']['ok'], True)
        checker.note('美化主题', built['beautify'].get('theme'))
    else:
        checker.check(built['beautify']['ok'] is False, '本段不套美化', built['beautify']['ok'], False)
    return after


def check_preprocess(checker, bridge, workdir, fixtures):
    """表格预处理的事件表那一步：下载之后、解析之前追加「内网外网资产」列。

    本段按**生产顺序**造表（用户口径 2026-10-12「取值层必须在预处理之后」）：

        写 fixture -> preprocess（原地改写事件表）-> build（搬表 + 落值）

    所以 fixture 用的是**自己的一份拷贝** —— 预处理原地改写下载件，不能拿公共 fixtures
    开刀（那几份后面还有别的段在用，改过一次之后事件表就带着那几列了，
    后面验到的就不是"从零追加"）。

    断言分两半：
      · 汇总层：映射了几个 IP、新列落在哪一列、取值分布（这些数来自预处理自己）；
      · 文件层：搬进报告 sheet 的那一列逐格对不对、原有列一列没动、范围还是 A1:C5。
    文件层这一半才是关键 —— 内存里对不算数，而且它顺带证明「搬表读的是预处理之后的文件」
    （搬表读盘，不是把 preprocess 的结果拼上去）。
    """
    checker.section('3.5】表格预处理（事件表追加列，跑在解析之前）')

    directory = workdir / 'preprocess'
    directory.mkdir(parents=True, exist_ok=True)
    asset_path = write_sheet(directory / 'asset.xlsx', ASSET_EXPOSURE_TABLE)
    event_path = write_sheet(directory / 'event.xlsx', EVENT_EXPOSURE_TABLE)

    early = run_preprocess(bridge, asset_path, event_path)

    tables = dict(fixtures)
    tables['asset'] = {'filePath': asset_path}
    tables['event'] = {'filePath': event_path}
    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-preprocess.xlsx'),
        'tables': tables,
        'preprocess': early,
        'beautify': False,
    })))

    pre = built['preprocess']
    checker.check(pre['ran'] is True, 'preprocess.ran', pre['ran'], True)
    checker.check(pre['asset']['mapped'] == 2, '资产表映射 IP 数', pre['asset']['mapped'], 2)
    checker.check(pre['asset']['headerRow'] == 1, '资产表表头行', pre['asset']['headerRow'], 1)
    checker.check(pre['event']['addedColumn'] == 'C', '事件表新增列', pre['event']['addedColumn'], 'C')
    checker.check(pre['event']['header'] == '内网外网资产', '新列列名',
                  pre['event']['header'], '内网外网资产')
    checker.note('取值分布', json.dumps(pre['event']['tallies'], ensure_ascii=False))

    ws = load_workbook(built['filePath'], data_only=False)[EVENT_SHEET]
    for addr, expected in EVENT_EXPECTED.items():
        actual = ws[addr].value
        checker.check(actual == expected, f'{addr} 新列取值', json.dumps(actual, ensure_ascii=False),
                      json.dumps(expected, ensure_ascii=False))

    # 原有列一列都不能动：PPT 引擎和人工核对都按原列位置读
    checker.check(ws['A1'].value == '影响资产' and ws['B1'].value == '事件名称',
                  '原有列原样', f'A1={ws["A1"].value} B1={ws["B1"].value}')
    checker.check(ws.calculate_dimension() == 'A1:C5', '事件表范围',
                  ws.calculate_dimension(), 'A1:C5')

    # 第 4 步（四个时长列）的**缺时间源列**不抛错，但要记 status + 缺哪几列。
    # 上面那条 'A1:C5' 的范围断言顺带钉住了「这次四列一列都没加」—— 有行数据、
    # 却少了列时，若不看这条断言，「少四列」与「算了但每行都缺时间」在报告上一样。
    checker.check(pre['duration']['status'] == 'no_column',
                  '事件表凑不齐时间列 -> 不抛错，只记 status（见【3.7】那一节）',
                  pre['duration']['status'], 'no_column')
    # 缺列名的顺序 = DURATION_COLUMNS 里那几对的先后（遏制 / 识别 / 处置 / 响应），去重后报出来
    checker.check(pre['duration']['missing'] == ['事件遏制时间', '专家研判时间',
                                                 '事件创建时间', '组件检出时间', '事件闭环时间'],
                  '缺的列名逐个报出来（不是只说"缺列"）',
                  json.dumps(pre['duration']['missing'], ensure_ascii=False))
    checker.check(pre['duration']['addedColumns'] == [], '缺列时四列一列都不加',
                  json.dumps(pre['duration']['addedColumns']), '[]')


# ---------------------------------------------------------------------------
# 【3.6】告警表「主机IP」原样入表（曾经在这一步剥括号，2026-10-12 删除）
# ---------------------------------------------------------------------------

def check_alarm_ip_passthrough(checker, bridge, workdir, fixtures):
    """告警表搬进报告时，所有列**逐格原样** —— 包括带括号后缀的「主机IP」。

    这里原本验的是「合并报告时剥掉『主机IP』行尾的括号说明」；2026-10-12 用户决定删掉
    那一步（剥不剥对取值毫无影响 —— 取值层的 normalizeIp 自己会剥，却让同一个值在仓库里
    有两个形态），于是这条验收**反了过来**：现在钉住的是「报告 sheet 上这一列与平台导出
    逐字相同」，谁以后再往合并阶段加一道清洗，这里立刻报出来。

    为什么值得单独占一节：这一步从前是唯一一个**在合并阶段改表内容**的动作，
    而报告里那些 sheet 是直接搬下载件来的 —— 一旦有人再插一道改值的逻辑，
    「报告上的表 = 平台导出的表」这条前提就没了，人工核对会照着报告去质疑取值层。
    落盘之后读回来逐格比（内存里对不算数），8 行 fixture 把全角 / 半角括号、
    尾随空格、无后缀、整格括号、空格子都铺到了。
    """
    checker.section('3.6】告警表「主机IP」原样入表（不再剥括号后缀）')

    directory = workdir / 'host-ip'
    directory.mkdir(parents=True, exist_ok=True)
    alarm_path = write_sheet(directory / 'alarm-host-ip.xlsx', ALARM_IP_TABLE)

    tables = dict(fixtures)
    tables['alarm'] = {'filePath': alarm_path}
    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-host-ip.xlsx'),
        'tables': tables,
        'beautify': False,
    })))

    ws = load_workbook(built['filePath'], data_only=False)[ALARM_SHEET]
    for addr, expected in ALARM_IP_EXPECTED.items():
        actual = ws[addr].value
        if expected == '':
            # 空串进 openpyxl 可能被写成 None，两种都算「留空」
            ok = actual in (None, '')
        else:
            ok = actual == expected
        checker.check(ok, f'{addr} 「主机IP」原样（带括号后缀）',
                      json.dumps(actual, ensure_ascii=False),
                      json.dumps(expected, ensure_ascii=False))

    for addr, expected in ALARM_IP_BUSINESS_EXPECTED.items():
        actual = ws[addr].value
        ok = actual in (None, '') if expected == '' else actual == expected
        checker.check(ok, f'{addr} 「主机IP业务」原样（旁边那列）',
                      json.dumps(actual, ensure_ascii=False),
                      json.dumps(expected, ensure_ascii=False))

    # 行数与表头都不许动：搬表只搬，不收拾
    checker.check(ws.calculate_dimension() == 'A1:C9', '告警表范围',
                  ws.calculate_dimension(), 'A1:C9')
    checker.check([ws.cell(row=1, column=c).value for c in (1, 2, 3)]
                  == ['告警定性', '主机IP', '主机IP业务'],
                  '表头原样', json.dumps([ws.cell(row=1, column=c).value for c in (1, 2, 3)],
                                       ensure_ascii=False))


# ---------------------------------------------------------------------------
# 【3.7】事件表三个时长列
# ---------------------------------------------------------------------------

def make_duration_event_table(directory):
    """三个时长列（表格预处理第 4 步）专用 fixture，见 DURATION_EVENT_TABLE 的说明。"""
    directory.mkdir(parents=True, exist_ok=True)
    return write_sheet(directory / 'event-duration.xlsx', DURATION_EVENT_TABLE)


def check_duration_columns(checker, bridge, workdir, fixtures):
    """事件表末尾追加「遏制时长 / 识别时长 / 处置时长 / 响应时长」（预处理第 4 步）。

    本段按**生产顺序**造表：先 `preprocess`（原地改写事件表 fixture）→ 再 `build`。
    这是 2026-10-12 的新契约 —— 那几列必须在解析之前落到下载件上，取值层（G7）才读得到；
    引擎里那次预处理只剩告警表剥括号一步（steps=('alarm',)），**不再追加这几列**。

    这条要同时盯住四件事：

      · **算得对**：四对减法逐格比（负差值按用户口径 2026-10-12 判为**不合法、那一格留空**
        —— 既不是写负数、也不是按 0 截断）；单位是分钟、2 位小数。
      · **跳得准**：某一对的时间是空 / `-` / 全角 `－` 时那格留空，但**同一行别的对照算**
        （用户口径：有 `-` 的就不算，直接跳过）。解析不出来的值（`N/A` / `待补`）
        同样留空，但走的是另一条计数（unparsedSkipped），两者必须分得开 ——
        混成一个数就分不出「这行没数据」与「平台换了时间格式」。
        负差值留空走**第三条**计数（negative，Fixture 上那四格）。三条计数互不串味，
        是这一段的重点：留空的样子一样，成因三种，混了就复盘不出来。同一个坏格被两对
        用到时（「组件检出时间」是识别与响应的共同减数），样例只报一遍。
      · **列落对地方**：四列落在第 2 步那列「内网外网资产」**右边**，
        五个源列与第 2 步那列逐格原样（PPT 引擎与人工核对都按原列位置读）。
      · **构建期那种形态也认**：fixture 里那几格在写盘、再读回来之后是 datetime 或
        裸序列号（build_report.py 的 to_serial_number 那条路），只认文本的话这四列会整片空。

    与【6】一样，落盘之后要读回来逐格比 —— 内存里对不算数。
    """
    checker.section('3.7】事件表四个时长列（下载之后、解析之前那一步的第 4 步）')

    directory = workdir / 'duration'
    directory.mkdir(parents=True, exist_ok=True)

    event_path = make_duration_event_table(directory)
    early = run_preprocess(bridge, fixtures['asset']['filePath'], event_path)

    tables = dict(fixtures)
    tables['event'] = {'filePath': event_path}
    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-duration.xlsx'),
        'tables': tables,
        'preprocess': early,
        'beautify': False,
    })))

    pre = built['preprocess']['duration']
    checker.check(pre['status'] == 'ok', 'status', pre['status'], 'ok')
    checker.check(pre['headerRow'] == 1, '表头行', pre['headerRow'], 1)
    checker.check(pre['dataRows'] == len(DURATION_EVENT_TABLE) - 1, '数据行数',
                  pre['dataRows'], len(DURATION_EVENT_TABLE) - 1)
    checker.check(pre['addedColumns'] == ['H', 'I', 'J', 'K'],
                  '四列落在「内网外网资产」(G) 右边', json.dumps(pre['addedColumns']),
                  '["H","I","J","K"]')
    checker.check(pre['sourceColumns'] == {
        '事件创建时间': 'B', '组件检出时间': 'C', '事件闭环时间': 'D',
        '事件遏制时间': 'E', '专家研判时间': 'F',
    }, '五个源列按精确列名命中', json.dumps(pre['sourceColumns'], ensure_ascii=False))

    checker.check(pre['filled'] == {'遏制时长': 5, '识别时长': 6, '处置时长': 5, '响应时长': 4},
                  '算出来的行数（负差值那四格不算 —— 它们按不合法留空）',
                  json.dumps(pre['filled'], ensure_ascii=False),
                  '{"遏制时长":5,"识别时长":6,"处置时长":5,"响应时长":4}')
    checker.check(pre['blankSkipped'] == {'遏制时长': 3, '识别时长': 1, '处置时长': 2, '响应时长': 3},
                  '空 / `-` 跳过（逐列独立，不整行连坐）',
                  json.dumps(pre['blankSkipped'], ensure_ascii=False),
                  '{"遏制时长":3,"识别时长":1,"处置时长":2,"响应时长":3}')
    checker.check(pre['unparsedSkipped'] == {'遏制时长': 0, '识别时长': 1, '处置时长': 1, '响应时长': 1},
                  '解析不出来跳过（与「空值」分开计）',
                  json.dumps(pre['unparsedSkipped'], ensure_ascii=False),
                  '{"遏制时长":0,"识别时长":1,"处置时长":1,"响应时长":1}')
    checker.check(pre['negative'] == {'遏制时长': 1, '识别时长': 1, '处置时长': 1, '响应时长': 1},
                  '负差值行数（不合法 -> 那一格留空，另计数报到日志里）',
                  json.dumps(pre['negative'], ensure_ascii=False),
                  '{"遏制时长":1,"识别时长":1,"处置时长":1,"响应时长":1}')
    checker.check(len(pre['unparsedSamples']) == 2,
                  '解析失败样例条数（同一个坏格被两对用到也只报一遍）',
                  len(pre['unparsedSamples']), 2)
    checker.note('样例', json.dumps(pre['unparsedSamples'], ensure_ascii=False))

    ws = load_workbook(built['filePath'], data_only=False)[EVENT_SHEET]
    for addr, expected in DURATION_EXPECTED.items():
        actual = ws[addr].value
        if expected == '':
            # 空串进 openpyxl 可能被写成 None，两种都算「留空」
            ok = actual in (None, '')
        else:
            ok = actual == expected
        checker.check(ok, f'{addr} 时长', json.dumps(actual, ensure_ascii=False),
                      json.dumps(expected, ensure_ascii=False))

    for addr, expected in DURATION_SOURCE_EXPECTED.items():
        actual = ws[addr].value
        ok = actual in (None, '') if expected is None else actual == expected
        checker.check(ok, f'{addr} 源列原样', json.dumps(actual, ensure_ascii=False),
                      json.dumps(expected, ensure_ascii=False))

    # 表头行与新增列数：A..K 十一列，只多四列，别的都不动
    checker.check(ws.calculate_dimension() == 'A1:K10', '事件表范围',
                  ws.calculate_dimension(), 'A1:K10')


# ---------------------------------------------------------------------------
# 【5】/【6】告警定性统计：读取层 + 落盘
# ---------------------------------------------------------------------------

def check_alarm_reader(checker, workdir):
    """断言读取层（scripts/parse_table_rows.py）的行对象契约。

    契约写在那个脚本的头注里，四条规矩没有一条是"顺手写的"：规矩 2/3 正是
    stats/metrics/alarm.js 里 hasOwnProperty 防线赖以成立的前提 —— 读取层要是把
    「列不存在」和「列存在但整列为空」混为一谈，取值层就再也分不出
    「平台改了列名」和「这段时间没有告警」，而后者本该是安静留空。
    """
    checker.section('5】总表读取层（parse_table_rows.py 的行对象契约）')
    directory = workdir / 'reader'
    directory.mkdir(parents=True, exist_ok=True)

    def parse(aoa, name, columns=None, sheet=None):
        payload = {'path': write_sheet(directory / name, aoa), 'columns': columns}
        if sheet is not None:
            payload['sheet'] = sheet
        return parse_table_rows(payload)

    # —— 规矩 1/2：键是表头文字；每行带全键；白名单外的列不进行对象
    parsed = parse(ALARM_TABLE, 'qualified.xlsx', columns=[ALARM_QUALIFICATION])
    checker.check(parsed['rowCount'] == len(ALARM_TABLE) - 1,
                  '数据行数（表头行不算）', parsed['rowCount'], len(ALARM_TABLE) - 1)
    checker.check(all(list(row.keys()) == [ALARM_QUALIFICATION] for row in parsed['rows']),
                  '每行的键就是请求的列（白名单外的列一列都不带）',
                  json.dumps(parsed['rows'][0], ensure_ascii=False))
    checker.check([row[ALARM_QUALIFICATION] for row in parsed['rows']]
                  == [row[0] for row in ALARM_TABLE[1:]],
                  '定性列逐行取值',
                  ' '.join(row[ALARM_QUALIFICATION] or '(空)' for row in parsed['rows']))
    checker.check(parsed['header'] == [ALARM_QUALIFICATION, '主机IP'],
                  'header 回报的是整表表头（诊断用，不受白名单影响）',
                  json.dumps(parsed['header'], ensure_ascii=False))
    checker.check(parsed['missingColumns'] == [] and parsed['unnamedColumns'] == 0,
                  '没有缺列 / 没有无名列',
                  f"missing={parsed['missingColumns']} unnamed={parsed['unnamedColumns']}")

    # —— 规矩 2/3 的分界：列存在但整列为空（每行都带这个键、值是空串）
    parsed = parse([['告警定性', '主机IP'], ['', '10.0.0.1'], ['', '10.0.0.2']],
                   'blank-col.xlsx', columns=[ALARM_QUALIFICATION])
    checker.check(all(ALARM_QUALIFICATION in row and row[ALARM_QUALIFICATION] == ''
                      for row in parsed['rows']),
                  '列存在但整列为空 -> 每行仍带这个键、值为空串（≠ 列不存在）',
                  json.dumps(parsed['rows'], ensure_ascii=False))

    # —— 规矩 3：表头里没有这一列 -> 一行都不带这个键，并回报 missingColumns
    parsed = parse([['主机IP'], ['10.0.0.1']], 'no-col.xlsx', columns=[ALARM_QUALIFICATION])
    checker.check(parsed['rows'] == [{}],
                  '表头没有这一列 -> 一行都不带这个键（hasOwnProperty 防线的信号）',
                  json.dumps(parsed['rows'], ensure_ascii=False))
    checker.check(parsed['missingColumns'] == [ALARM_QUALIFICATION],
                  'missingColumns 回报缺的列',
                  json.dumps(parsed['missingColumns'], ensure_ascii=False))

    # —— 空表（只有表头）不是错误：rows 为空，但列在表头里，所以不算缺列
    parsed = parse([[ALARM_QUALIFICATION, '主机IP']], 'empty.xlsx', columns=[ALARM_QUALIFICATION])
    checker.check(parsed['rowCount'] == 0 and parsed['rows'] == []
                  and parsed['missingColumns'] == [],
                  '空表 -> rows 为空且不报错（列本身在表头里）',
                  f"rows={len(parsed['rows'])} missing={parsed['missingColumns']}")

    # —— 规矩 4：表头重名抛错（宁可炸，也不静默丢一列）
    duplicated = None
    try:
        parse([[ALARM_QUALIFICATION, ALARM_QUALIFICATION], ['a', 'b']],
              'dup.xlsx', columns=[ALARM_QUALIFICATION])
    except ValueError as error:
        duplicated = str(error)
    checker.check(duplicated is not None and '重名' in duplicated,
                  '表头重名 -> 抛错', duplicated or '没抛（错！）')

    # —— 整行无值的行丢掉：与合并引擎 collect_source_rows 同口径，
    #    否则取值层数出的行数与交付物里肉眼看到的行数对不上
    parsed = parse([['告警定性'], ['未知威胁'], [None], ['病毒']],
                   'ragged.xlsx', columns=[ALARM_QUALIFICATION])
    checker.check([row[ALARM_QUALIFICATION] for row in parsed['rows']] == ['未知威胁', '病毒'],
                  '整行无值的行被丢掉', json.dumps(parsed['rows'], ensure_ascii=False))

    # —— 时间列给的是 epoch **秒**（R11），不是 Excel 序列号（那是"天"）
    moment = datetime.datetime(2026, 5, 12, 10, 9, 39)
    parsed = parse([['时间', '告警定性'], [moment, '未知威胁']], 'time.xlsx', columns=['时间'])
    expected_seconds = int(moment.replace(tzinfo=datetime.timezone.utc).timestamp())
    checker.check(parsed['rows'][0]['时间'] == expected_seconds,
                  '时间列是 epoch 秒（R11）', parsed['rows'][0]['时间'], expected_seconds)


def check_alarm_end_to_end(checker, bridge, workdir, fixtures, alarm_path):
    """告警表接进 ctx 之后，那 14 格必须**真的落盘**，且不惊动别的格子。

    这条是本次改动的正题：在此之前生产路径压根没把总表喂进 ctx（mssw_downloader.js
    的 createContext 只给了客户名和报告期），14 格全留空，报告里一个值都没有。
    所以这里不只看计划，还要把落盘的文件读回来逐格比 —— 内存里对不算数。

    另外两条边界（缺列 / 空表）走的是 plan 而不是 build：它们与落盘无关 ——
    缺列断的是"必须一个值都不写、且全进错误列表"，空表断的是"14 格写空串、一个错都不记"。
    """
    checker.section('6】告警定性统计端到端（C133:I134 真的落进报告）')

    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-alarm.xlsx'),
        'tables': fixtures,
        'alarmPath': alarm_path,
        'beautify': False,
    })))

    stats = built['statistics']
    # 本段只接告警表，其余四份总表都是空的 -> 那些格子写 0 / 空串（都算落值）；
    # --business-systems 也没传 -> D6:D9 与 G6/H6/I6/G10 同样写 0
    # （用户口径 2026-10-12：「一个系统都没传」那几格写 0，不再记错误）。
    # 唯一落不了值的只有五格：G5 报「找不到列」（这份 fixture 的告警表只有「告警定性」
    # 与「主机IP」两列，**没有**「GPT研判结论」），D3/D4/D5 报「没有第 N 个系统」
    # （那三格写的是系统名本身，没有名字就没有可写的东西）。
    expected_written = sorted(a for a in EXPECTED_WRITE_CELLS if a != 'G5')
    expected_errors = sorted(EXPECTED_NO_SYSTEM_ERRORS + ['G5'])
    checker.check(stats['connected'] is True, 'statistics.connected', stats['connected'], True)
    checker.check(sorted(stats['written']) == expected_written,
                  '落值的地址 = 3 个报告参数格 + 14 格告警统计 + 空表兜住的 21 格事件定性'
                  ' / D10/D12/D15/D17 / D11 / D16 / G8 / G9 写 0 / G7 写空串'
                  ' / D6:D9 与 G6/H6/I6/G10 写 0（没传系统名）—— G5 报缺列',
                  ' '.join(sorted(stats['written'])), ' '.join(expected_written))
    checker.check(sorted(e['addr'] for e in stats['errors']) == expected_errors,
                  'errors = G5（告警表缺「GPT研判结论」列）+ D3/D4/D5（没传系统名、写的是名字不是数）',
                  ' '.join(sorted(e['addr'] for e in stats['errors'])),
                  ' '.join(expected_errors))
    checker.check(len(stats['unresolved']) == EXPECTED_UNRESOLVED,
                  'statistics.unresolved', len(stats['unresolved']), EXPECTED_UNRESOLVED)
    checker.check(len(stats['applied']) == len(expected_written),
                  'statistics.applied（实际落笔，Python 侧没丢格）',
                  len(stats['applied']), len(expected_written))

    ws = load_workbook(built['filePath'], data_only=False)[TEMPLATE_SHEET]
    for rank, (label, count) in enumerate(zip(ALARM_LABELS, ALARM_COUNTS)):
        column = chr(ord('C') + rank)
        label_addr = f'{column}{ALARM_LABEL_ROW}'
        share_addr = f'{column}{ALARM_SHARE_ROW}'

        actual_label = ws[label_addr].value or ''
        checker.check(actual_label == label, f'{label_addr} 定性名称',
                      json.dumps(actual_label, ensure_ascii=False),
                      json.dumps(label, ensure_ascii=False))

        # 分母是**全部定性的出现总次数**（ALARM_TOTAL=7），不是前几名之和。
        # fixture 里那行空定性不进分母 —— 若误按 8 算，C134 会变成 0.375 而不是 3/7。
        share = ws[share_addr].value
        if count:
            expected_share = count / ALARM_TOTAL
            ok = isinstance(share, (int, float)) and abs(share - expected_share) < 1e-12
            shown, want = json.dumps(share), json.dumps(expected_share)
        else:
            ok, shown, want = share in (None, ''), json.dumps(share, ensure_ascii=False), '(空)'
        checker.check(ok, f'{share_addr} 占比', shown, want)
        checker.check(ws[share_addr].number_format == '0.00%',
                      f'{share_addr} 百分号格式', ws[share_addr].number_format, '0.00%')

    # 边界一：表头里没有「告警定性」（平台改了列名）-> 14 格全进错误列表、一个都不写
    # （这段的 ctx 不带 --business-systems，所以核心业务系统那 7 格也必然在 errors 里）
    edges = workdir / 'alarm-edges'
    edges.mkdir(parents=True, exist_ok=True)
    missing_path = write_sheet(edges / 'renamed.xlsx',
                               [['主机IP', '告警名称'], ['10.0.0.1', '未知威胁']])
    plan = call_bridge(bridge, 'plan', 'alarm', _b64(json.dumps({'path': missing_path})))
    alarm_errors = {e['addr']: e['message'] for e in plan['errors'] if e['addr'] in ALARM_ADDRS}
    checker.check(sorted(alarm_errors) == sorted(ALARM_ADDRS),
                  '列名被改 -> 14 格全进错误列表',
                  ' '.join(sorted(alarm_errors)))
    checker.check(not set(ALARM_ADDRS) & set(plan['written']),
                  '列名被改 -> 一个值都不写',
                  '是' if not set(ALARM_ADDRS) & set(plan['written']) else '否')
    checker.check(all('找不到' in m for m in alarm_errors.values()),
                  '错误信息点明是「找不到列」而不是「没有数据」',
                  json.dumps(alarm_errors.get('C133'), ensure_ascii=False))

    # 边界二：空表（列在、一行都没有）-> 14 格全写**空串**（名次槽位本来就该是空的）、
    # 一个错误都不记（R10 不适用：0 行是正常数据，不是缺数）
    empty_path = write_sheet(edges / 'empty-table.xlsx',
                             [[ALARM_QUALIFICATION, '主机IP']])
    plan = call_bridge(bridge, 'plan', 'alarm', _b64(json.dumps({'path': empty_path})))
    values = {w['addr']: w['value'] for w in plan['writes']}
    alarm_errors = {e['addr']: e['message'] for e in plan['errors'] if e['addr'] in ALARM_ADDRS}
    checker.check(not alarm_errors,
                  '空表 -> 14 格一个错误都不记（0 行是正常数据）',
                  ' '.join(sorted(alarm_errors)) or '（无）')
    checker.check(all(values.get(addr) == '' for addr in ALARM_ADDRS),
                  '空表 -> 14 格全写空串（名次槽位本来就是空的）',
                  '是' if all(values.get(a) == '' for a in ALARM_ADDRS) else json.dumps(
                      {a: values.get(a) for a in ALARM_ADDRS if values.get(a) != ''},
                      ensure_ascii=False))
    checker.check(plan['parsed']['rowCount'] == 0, '空表行数为 0', plan['parsed']['rowCount'], 0)


# ---------------------------------------------------------------------------
# 【11】威胁告警数量：G5 + G6/H6/I6
# ---------------------------------------------------------------------------

def check_threat_alarms(checker, bridge, workdir, fixtures, alarm_path, asset_path):
    """G5「威胁告警总」与 G6/H6/I6「核心系统威胁告警数量」读的是**同一份告警表的同一列**：

      · G5 = 「GPT研判结论」精确等于「真实攻击未成功」的**行数**（整张表，不去重）
      · G6/H6/I6 = 同一批行里，「主机IP」落在**第 1/2/3 个核心业务系统的 IP 集合**里的行数
        （系统名与 D3/D4/D5 同取 --business-systems，IP 集合来自资产表「所属业务」）

    所以两个方向都要钉：**同一张表的两种圈法**（整表 / 按 IP），以及**格子之间不许串**——
    G5 刻意不等于任何一格、三个系统的数也刻意互不相等，把其中一格误实现成另一格的别名
    或"整表数"都会在这里红。

    边界分几类，各自钉一条口径：
      · 表头缺「GPT研判结论」-> 4 格全缺数（列名对不上不许数出 0）
      · 告警表为空（0 行）-> 4 格都写 0（0 是结论，不是缺数；与那 14 格同一口径）
      · 表头缺「主机IP」-> **只有 G6/H6/I6** 缺数，G5 照算（它不按 IP 圈定）
      · 少传系统 -> 对应槽位缺数，别的槽位照算
      · 资产表缺席 -> 那三格的 IP 集合是空集 -> **三格都写 0**，G5 照算
        —— 这条是「G5 只认告警表、那三格另认资产表」的分界；
        资产表**在但缺「所属业务」列**才是缺数（列名对不上，不等于"没有资产"）
    """
    checker.section('11】G5 威胁告警总 + G6/H6/I6 核心系统威胁告警数量'
                    '（同一列、两种圈法，与 D3/D4/D5 同一批系统名）')

    edges = workdir / 'verdict-edges'
    edges.mkdir(parents=True, exist_ok=True)

    def plan(alarm, asset=asset_path, business_systems=CORE_SYSTEMS):
        request = {'alarmPath': alarm, 'businessSystems': business_systems}
        if asset:
            request['assetPath'] = asset
        return call_bridge(bridge, 'plan', 'verdict', _b64(json.dumps(request)))

    def writes_of(result, cells=EXPECTED_VERDICT_CELLS):
        """只取这 4 格 —— 计划里永远还有 3 个报告参数格与别段落的格子。"""
        return {w['addr']: w['value'] for w in result['writes'] if w['addr'] in cells}

    def errors_of(result, cells=EXPECTED_VERDICT_CELLS):
        return {e['addr']: e['message'] for e in result['errors'] if e['addr'] in cells}

    def expected():
        return dict(zip(EXPECTED_VERDICT_CELLS, [VERDICT_TOTAL] + VERDICT_SYSTEM_COUNTS))

    # —— 正题一：计划里四格各是自己的数（G5 整表 10、三个系统 3 / 4 / 2）
    result = plan(alarm_path)
    checker.check(writes_of(result) == expected(),
                  'G5 = 整表命中行数；G6/H6/I6 = 各自系统 IP 集合里的命中行数'
                  '（同一行落在两台机器/两个系统上时各算一次）',
                  json.dumps(writes_of(result), ensure_ascii=False),
                  json.dumps(expected(), ensure_ascii=False))
    checker.check(errors_of(result) == {}, '4 格都不缺数',
                  json.dumps(errors_of(result), ensure_ascii=False), '（无）')
    # 列白名单与 fixture 表头对得上（读到的行里三列都在），且 14 格也在同一份计划里
    checker.check(result['parsed']['alarm']['missingColumns'] == []
                  and result['parsed']['alarm']['rowCount'] == len(VERDICT_TABLE) - 1,
                  '告警表按 ALARM_TABLE_COLUMNS 读全（列都在、行数对得上）',
                  json.dumps(result['parsed']['alarm'], ensure_ascii=False))
    checker.check(not set(ALARM_ADDRS) & set(EXPECTED_VERDICT_CELLS),
                  '4 格与告警定性那 14 格没有重叠', '是')

    # —— 正题二：落盘后读回来（内存里对不算数）
    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-verdict.xlsx'),
        'tables': fixtures,
        'alarmPath': alarm_path,
        'statsPaths': {'asset': asset_path},
        'businessSystems': CORE_SYSTEMS,
        'beautify': False,
    })))
    stats = built['statistics']
    # 本段接的是告警表 + 资产表 + --business-systems，所以落值的格子是**全集**：
    #   · 告警表：14 格告警定性 + G5/G6/H6/I6
    #   · 资产表 + CLI：D3/D4/D5 系统名照写，D6/D7/D8/D9 与 D11 也照写 —— 漏洞 / 弱密码 /
    #     事件三份表这次是**空表**（0 行），那些段落按 0 计（0 是结论，不是缺数，见【7】的口径）
    #   · G10 同理：资产表在（IP 集合算得出来）、事件表是空表 -> 写 0，不报错
    # 漏洞表是空表 -> D10/D12/D15/D17 都写 0；事件表是空表 -> 事件定性 21 格全写空串。
    # 所以这一份走完，**一个错误都不该有**。
    expected_written = sorted_union(EXPECTED_WRITE_CELLS, EXPECTED_CORE_SYSTEM_CELLS,
                                    EXPECTED_CORE_SYSTEM_EVENT_CELLS)
    expected_errors = []
    checker.check(sorted(stats['written']) == expected_written,
                  '落值的地址 = 3 个报告参数格 + 14 格告警定性 + G5/G6/H6/I6 + 核心系统 7 格 + D11'
                  '（其余三份表是空表，按 0 / 空串落值，不进 errors）',
                  ' '.join(sorted(stats['written'])), ' '.join(expected_written))
    checker.check(sorted(e['addr'] for e in stats['errors']) == expected_errors,
                  'errors 为空（本段没有缺列、没有缺槽位）',
                  ' '.join(sorted(e['addr'] for e in stats['errors'])) or '（无）',
                  ' '.join(expected_errors) or '（无）')
    checker.check(len(stats['applied']) == len(expected_written),
                  'statistics.applied（实际落笔，Python 侧没丢格）',
                  len(stats['applied']), len(expected_written))
    checker.check(len(stats['unresolved']) == EXPECTED_UNRESOLVED,
                  'statistics.unresolved', len(stats['unresolved']), EXPECTED_UNRESOLVED)

    ws = load_workbook(built['filePath'], data_only=False)[TEMPLATE_SHEET]
    for addr, value in expected().items():
        actual = ws[addr].value
        checker.check(actual == value, f'{addr} 落盘', repr(actual), value)
    checker.note('四个数', f"G5(整表)={VERDICT_TOTAL} "
                 f"G6({CORE_SYSTEMS[0]})={VERDICT_SYSTEM_COUNTS[0]} "
                 f"H6({CORE_SYSTEMS[1]})={VERDICT_SYSTEM_COUNTS[1]} "
                 f"I6({CORE_SYSTEMS[2]})={VERDICT_SYSTEM_COUNTS[2]}"
                 '（刻意互不相等：相等的话把某一格写成"整表数"或另一格的别名照样能过）')

    # —— 边界一：表头里没有「GPT研判结论」（平台改了列名）-> 4 格全进错误列表、一个都不写
    renamed = write_sheet(edges / 'renamed.xlsx', [
        ['告警定性', '研判结论', '主机IP'],
        ['未知威胁', '真实攻击未成功', '10.0.0.1'],
    ])
    result = plan(renamed)
    checker.check(not writes_of(result), '缺「GPT研判结论」列 -> 4 格一个值都不写',
                  json.dumps(writes_of(result), ensure_ascii=False), '（无）')
    errors = errors_of(result)
    checker.check(sorted(errors) == sorted(EXPECTED_VERDICT_CELLS),
                  '缺「GPT研判结论」列 -> 4 格全进错误列表', ' '.join(sorted(errors)))
    checker.check(all('找不到「GPT研判结论」' in m for m in errors.values()),
                  '错误信息点明是缺「GPT研判结论」列（不是「没有数据」）',
                  json.dumps(errors.get('G5'), ensure_ascii=False))

    # —— 边界二：告警表为空（只有表头）-> 4 格都写 0、一个错误都不记
    #    （0 是结论，不是缺数；与那 14 格同一口径。表"没下到"时 scripts/build_report.py
    #     早拦下了，走不到这里 —— 这里见到的"没有行"只可能是这段时间真没有）
    empty = write_sheet(edges / 'empty-table.xlsx',
                        [['告警定性', 'GPT研判结论', '主机IP']])
    result = plan(empty)
    checker.check(writes_of(result) == {'G5': 0, 'G6': 0, 'H6': 0, 'I6': 0},
                  '空表（0 行）-> G5/G6/H6/I6 都写 0（是结论，不是缺数）',
                  json.dumps(writes_of(result), ensure_ascii=False),
                  json.dumps({'G5': 0, 'G6': 0, 'H6': 0, 'I6': 0}, ensure_ascii=False))
    checker.check(errors_of(result) == {}, '空表 -> 4 格都不报错',
                  json.dumps(errors_of(result), ensure_ascii=False), '（无）')

    # —— 边界三：表头缺「主机IP」-> **只有 G6/H6/I6** 缺数，G5 照算。
    #    这条钉的是「G5 不按 IP 圈定」：它连这一列都不该去要。
    no_ip = write_sheet(edges / 'no-host-ip.xlsx', VERDICT_TABLE_NO_HOST_IP)
    result = plan(no_ip)
    checker.check(writes_of(result) == {'G5': VERDICT_TOTAL},
                  '缺「主机IP」列 -> G5 照算（整表命中行数），G6/H6/I6 不写值',
                  json.dumps(writes_of(result), ensure_ascii=False),
                  json.dumps({'G5': VERDICT_TOTAL}, ensure_ascii=False))
    errors = errors_of(result)
    checker.check(sorted(errors) == ['G6', 'H6', 'I6'],
                  '缺「主机IP」列 -> 缺数的是 G6/H6/I6', ' '.join(sorted(errors)))
    checker.check(all('找不到「主机IP」' in m for m in errors.values()),
                  '错误信息点明是缺「主机IP」列',
                  json.dumps(errors.get('G6'), ensure_ascii=False))

    # —— 边界四：少传系统（只传 2 个）-> 第 3 个槽位没有系统：I6 写 0、**不记错误**，
    #    前两个照算，G5 与系统数无关（用户口径 2026-10-12：--business-systems 是可选参数，
    #    槽位空着这个数就是 0）。
    result = plan(alarm_path, business_systems=CORE_SYSTEMS[:2])
    checker.check(writes_of(result) == {'G5': VERDICT_TOTAL, 'G6': VERDICT_SYSTEM_COUNTS[0],
                                        'H6': VERDICT_SYSTEM_COUNTS[1], 'I6': 0},
                  '只传 2 个系统 -> G5 与 G6/H6 照算，I6 写 0',
                  json.dumps(writes_of(result), ensure_ascii=False),
                  json.dumps({'G5': VERDICT_TOTAL, 'G6': VERDICT_SYSTEM_COUNTS[0],
                              'H6': VERDICT_SYSTEM_COUNTS[1], 'I6': 0}, ensure_ascii=False))
    errors = errors_of(result)
    checker.check(errors == {}, '只传 2 个系统 -> 一格都不报错（缺的槽位按 0，不是缺数）',
                  json.dumps(errors, ensure_ascii=False), '（无）')

    # —— 边界五：**资产表**缺席（= 空表）-> 「业务归属 -> IP」得到空集，于是 G6/H6/I6
    #    都数出 0（该系统名下确实一台资产都没有），G5 照算。
    #    与边界三互为镜像：两把钥匙各管各的格子，一张表出问题不连坐另一套口径。
    #    （注意与边界六的区别：表**在**、但那列读不出来才是缺数 —— 那说明平台动了表头，
    #     按 0 算就等于拿一份没读到的数据当没有。）
    result = plan(alarm_path, asset=None)
    checker.check(writes_of(result) == {'G5': VERDICT_TOTAL, 'G6': 0, 'H6': 0, 'I6': 0},
                  '资产表缺席（= 空表）-> G5 照算（它只认告警表），G6/H6/I6 都写 0',
                  json.dumps(writes_of(result), ensure_ascii=False),
                  json.dumps({'G5': VERDICT_TOTAL, 'G6': 0, 'H6': 0, 'I6': 0},
                             ensure_ascii=False))
    checker.check(errors_of(result) == {},
                  '资产表缺席 -> 4 格都不报错（IP 集合是空集，不是缺数）',
                  json.dumps(errors_of(result), ensure_ascii=False), '（无）')

    # —— 边界六：资产表里缺「所属业务」列 -> 同样是 G6/H6/I6 缺数（列名对不上），G5 照算
    renamed_asset = write_sheet(edges / 'asset-renamed.xlsx', [
        ['IP地址', '业务归属', '资产名称'],
        ['10.0.0.1', 'OA系统', 'a'],
    ])
    result = plan(alarm_path, asset=renamed_asset)
    checker.check(writes_of(result) == {'G5': VERDICT_TOTAL},
                  '资产表缺「所属业务」列 -> G5 照算，G6/H6/I6 不写值',
                  json.dumps(writes_of(result), ensure_ascii=False),
                  json.dumps({'G5': VERDICT_TOTAL}, ensure_ascii=False))
    errors = errors_of(result)
    checker.check(sorted(errors) == ['G6', 'H6', 'I6'],
                  '资产表缺「所属业务」列 -> 缺数的是 G6/H6/I6', ' '.join(sorted(errors)))
    checker.check(all('找不到「所属业务」' in m for m in errors.values()),
                  '错误信息点明是缺「所属业务」列',
                  json.dumps(errors.get('G6'), ensure_ascii=False))


# ---------------------------------------------------------------------------
# 【7】核心业务系统：四份总表 + --business-systems
# ---------------------------------------------------------------------------
def check_core_system(checker, bridge, workdir, fixtures, template):
    """D3/D4/D5 是 CLI 传进来的名字，D7/D8/D9 是「资产表业务归属 -> IP ->
    漏洞 / 弱密码 / 事件」三段相加，D6 是那三格的合计。

    三段相加这件事**只有整条链一起跑才验得出**：读取层各自读对、取值层各自算对、
    接起来少加一段，报告上照样是个看着合理的数。所以这里既看计划，也把落盘的文件
    读回来逐格比（内存里对不算数）。D6 同理 —— 三个数都对、合计少加一个，
    也没人看得出来，所以每一处都单独断一次它等于那三格之和。
    """
    checker.section('7】核心业务系统端到端（D3/D4/D5 系统名 + D6 安全风险总数 + D7/D8/D9 风险总数）')

    paths = make_core_system_tables(workdir / 'core-systems')
    edges = workdir / 'core-edges'
    edges.mkdir(parents=True, exist_ok=True)

    def plan(business_systems, table_paths=None):
        return call_bridge(bridge, 'plan', 'core', _b64(json.dumps({
            'paths': paths if table_paths is None else table_paths,
            'businessSystems': business_systems,
        })))

    def writes_of(result, cells):
        """只取关心的格子 —— 计划里永远还有 3 个报告参数格（J1/L1/M1，值来自 CLI，
        与总表无关），逐条比全集会把它们算成"多写的格子"。"""
        return {w['addr']: w['value'] for w in result['writes'] if w['addr'] in cells}

    def errors_of(result, cells):
        """同上：本段不接告警表，那 14 格必然也在 errors 里，只挑关心的格子看。"""
        return {e['addr']: e['message'] for e in result['errors'] if e['addr'] in cells}

    # —— 正题：三个系统都传了、四份总表都在
    result = plan(CORE_SYSTEMS)
    values = writes_of(result, CORE_SYSTEM_CELLS)
    checker.check(sorted(values) == sorted(CORE_SYSTEM_CELLS),
                  '落值的地址就这 7 格', ' '.join(sorted(values)), ' '.join(CORE_SYSTEM_CELLS))
    checker.check(errors_of(result, CORE_SYSTEM_CELLS) == {},
                  '核心业务系统 7 格没有缺数',
                  json.dumps(errors_of(result, CORE_SYSTEM_CELLS), ensure_ascii=False))
    # 事件定性那 21 格在这段是**应该**报错的（plan core 给的事件表没有「GPT定性标签」列），
    # G7 同理（同一份表也缺「GPT研判结论」与两个时间列），G9 也同理（缺「推送状态」与
    # 预处理追加的「响应时长」列 —— 这一段的事件表没跑过预处理），
    # 所以要比的不是"errors 为空"，而是"报了错的格子只有这些已知没接输入的那些"。
    # 告警表这段压根没接 -> 是**空表**，14 格告警定性写空串、G5/G6/H6/I6 都写 0，
    # 四块都不该报错。
    stray = sorted(set(e['addr'] for e in result['errors'])
                   - set(EXPECTED_EVENT_CELLS) - set(EXPECTED_CONTAINED_CELLS)
                   - set(EXPECTED_RESPONSE_CELLS))
    checker.check(stray == [],
                  '除事件定性 21 格（那份 fixture 缺「GPT定性标签」列）与 G7'
                  '（缺「GPT研判结论」列）、G9（缺「推送状态」列）外没有别的格子报错',
                  ' '.join(stray) or '（无）')
    checker.check(sorted(result['parsed']) == ['asset', 'event', 'vuln', 'weakpwd'],
                  '四份总表都读到了', ' '.join(sorted(result['parsed'])),
                  'asset event vuln weakpwd')

    for rank, name in enumerate(CORE_SYSTEMS):
        addr = f'D{3 + rank}'
        checker.check(values.get(addr) == name, f'{addr} 系统名（原样照抄 CLI 入参）',
                      json.dumps(values.get(addr), ensure_ascii=False),
                      json.dumps(name, ensure_ascii=False))
    for rank, (parts, total) in enumerate(zip(CORE_SYSTEM_BREAKDOWN, CORE_SYSTEM_RISK_TOTALS)):
        addr = f'D{7 + rank}'
        checker.check(values.get(addr) == total,
                      f'{addr} {CORE_SYSTEMS[rank]} 风险总数（漏洞 {parts[0]} + 弱密码 {parts[1]}'
                      f' + 事件 {parts[2]}）',
                      repr(values.get(addr)), total)
    checker.note('三个系统的总数', f'OA={CORE_SYSTEM_RISK_TOTALS[0]} '
                 f'财务={CORE_SYSTEM_RISK_TOTALS[1]} 运维={CORE_SYSTEM_RISK_TOTALS[2]}'
                 '（刻意互不相等：相等的话把两个系统的 IP 集合换个个儿也照样过）')
    grand_total = sum(CORE_SYSTEM_RISK_TOTALS)
    checker.check(values.get('D6') == grand_total,
                  'D6 安全风险总数 = D7 + D8 + D9',
                  repr(values.get('D6')), grand_total)
    # 同一段里顺带钉一下 D10 / D12 / D15：它们读的是同一份漏洞表，
    # 但口径是**全表**，与 --business-systems 传了三个系统这件事无关；
    # 三格期望值刻意不同（3 / 2 / 4）—— 一个数行数、一个去重后数台、一个按处置状态数行。
    vuln_cells = writes_of(result, EXPECTED_VULN_CELLS)
    checker.check(vuln_cells == {'D10': VULN_HIGH_EXPLOITABLE_COUNT,
                                 'D12': VULN_HOT_ASSET_COUNT,
                                 'D15': VULN_SETTLED_COUNT},
                  'D10 行数 / D12 资产台数 / D15 处置完成行数（全表口径，同一份漏洞表）',
                  json.dumps(vuln_cells, ensure_ascii=False),
                  json.dumps({'D10': VULN_HIGH_EXPLOITABLE_COUNT,
                              'D12': VULN_HOT_ASSET_COUNT,
                              'D15': VULN_SETTLED_COUNT}, ensure_ascii=False))
    # D17 是 D12 的 alias（投喂口径「值 = D12」），所以它**必须**跟 D12 一模一样。
    # 单列一条、不并进上面那个 dict，是为了让「D17 自己重算了一遍」这种写法在这里露馅：
    # 那种写法今天恰好也能得出同一个数，但它是两份算法，D12 一改就会对不上。
    # 别名格一个字都不读总表，所以它出现在这里只有一个原因 —— D12 算出来了。
    alias_cells = writes_of(result, EXPECTED_ALIAS_CELLS)
    checker.check(alias_cells == {'D17': VULN_HOT_ASSET_COUNT},
                  'D17 受影响的最新漏洞数（alias D12，同值、不重算）',
                  json.dumps(alias_cells, ensure_ascii=False),
                  json.dumps({'D17': VULN_HOT_ASSET_COUNT}, ensure_ascii=False))
    # D11 也是同一段里顺带钉：它读资产表（重要级别）、弱密码表、事件表三份，口径是
    # **核心资产**而不是某个核心业务系统 —— 传进来的三个系统名与本格一个字节都无关。
    d11 = writes_of(result, EXPECTED_WEAKPWD_CELLS)
    checker.check(d11 == {'D11': ADMIN_WEAKPWD_TOTAL},
                  f'D11 管理员弱口令数量（核心资产：弱密码 {ADMIN_WEAKPWD_BREAKDOWN[0]}'
                  f' + 事件 {ADMIN_WEAKPWD_BREAKDOWN[1]}，与 --business-systems 无关）',
                  json.dumps(d11, ensure_ascii=False),
                  json.dumps({'D11': ADMIN_WEAKPWD_TOTAL}, ensure_ascii=False))
    # G8 也在这段里顺带钉：它读的同样是这份事件表（「处置状态」那一列），口径是**整张表**，
    # 与 --business-systems、与 D7:D9 的 IP 圈定都无关。这一段带的事件表有这一列，
    # 所以它不报错；它的值刻意与同段别的数都不同（见 CORE_EVENT_DISPOSED_COUNT）。
    g8 = writes_of(result, EXPECTED_EVENT_DISPOSITION_CELLS)
    checker.check(g8 == {'G8': CORE_EVENT_DISPOSED_COUNT},
                  f'G8 处置安全事件总数（「处置状态」命中 {CORE_EVENT_DISPOSED_COUNT} 行，'
                  f'与 --business-systems 无关）',
                  json.dumps(g8, ensure_ascii=False),
                  json.dumps({'G8': CORE_EVENT_DISPOSED_COUNT}, ensure_ascii=False))
    # G10 也在这一段里顺带钉：同一份资产表（「所属业务」-> IP）+ 同一份事件表
    # （「影响资产」精确命中），只是圈法不同（全部系统**并成一个集合**、**不看分类**）。
    # 期望值见 CORE_EVENT_UNION_COUNT 的说明；完整边界（并集、精确查找、缺列、空表、
    # 少传系统）在【15】。
    # ⚠️ 这个数（5）与同段 D8（财务系统风险总数 5）**数值巧合相同** —— 那是"漏洞 + 弱密码 +
    # 事件三段相加"的另一条路，与本格不是一回事；本段的"不一样"由 G8(7) / D11(6) / D10(3)
    # 与【15】那份专属 fixture（同表上"按分类筛"只能数出 2）钉住。
    g10 = writes_of(result, EXPECTED_CORE_SYSTEM_EVENT_CELLS)
    checker.check(g10 == {'G10': CORE_EVENT_UNION_COUNT},
                  f'G10 核心系统事件数量（三个系统的 IP 并集上数事件行，命中 {CORE_EVENT_UNION_COUNT} 行）',
                  json.dumps(g10, ensure_ascii=False),
                  json.dumps({'G10': CORE_EVENT_UNION_COUNT}, ensure_ascii=False))

    # —— 端到端：落盘后读回来（内存里对不算数）
    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-core.xlsx'),
        'tables': fixtures,
        'statsPaths': paths,
        'businessSystems': CORE_SYSTEMS,
        'beautify': False,
    })))

    stats = built['statistics']
    expected_written = sorted((set(EXPECTED_WRITE_CELLS) | set(EXPECTED_CORE_SYSTEM_CELLS)
                               | set(EXPECTED_CORE_SYSTEM_EVENT_CELLS))
                              - set(EXPECTED_EVENT_CELLS)
                              - set(EXPECTED_CONTAINED_CELLS)
                              - set(EXPECTED_RESPONSE_CELLS))
    checker.check(sorted(stats['written']) == expected_written,
                  '落值的地址 = 3 个报告参数格 + 7 格核心业务系统 + G10 + D10 / D12 / D15 / D17 + D11'
                  ' + 14 格告警定性（空表 -> 空串）+ G5/G6/H6/I6（空表 -> 0）（本段带四份总表）',
                  ' '.join(sorted(stats['written'])), ' '.join(expected_written))
    # 本段不接告警表（= 空表）已按 0 / 空串落值，报错的只有事件表 fixture 对不上的那三处：
    # 事件定性那 21 格（列不是「GPT定性标签」）、G7（没有「GPT研判结论」列）、
    # G9（没有「推送状态」列）
    written_elsewhere = sorted(set(e['addr'] for e in stats['errors'])
                               - set(EXPECTED_EVENT_CELLS) - set(EXPECTED_CONTAINED_CELLS)
                               - set(EXPECTED_RESPONSE_CELLS))
    checker.check(written_elsewhere == [],
                  'errors 只剩事件定性 21 格 + G7 + G9（本段的事件表 fixture 缺「GPT定性标签」'
                  '「GPT研判结论」「推送状态」列）',
                  ' '.join(written_elsewhere) or '（无）')
    checker.check(len(stats['applied']) == len(expected_written),
                  'statistics.applied（实际落笔，Python 侧没丢格）',
                  len(stats['applied']), len(expected_written))

    ws = load_workbook(built['filePath'], data_only=False)[TEMPLATE_SHEET]
    for rank, name in enumerate(CORE_SYSTEMS):
        actual = ws[f'D{3 + rank}'].value
        checker.check(actual == name, f'D{3 + rank} 系统名（落盘）',
                      json.dumps(actual, ensure_ascii=False), json.dumps(name, ensure_ascii=False))
    for rank, total in enumerate(CORE_SYSTEM_RISK_TOTALS):
        actual = ws[f'D{7 + rank}'].value
        checker.check(actual == total, f'D{7 + rank} 风险总数（落盘）', repr(actual), total)
    actual = ws['D6'].value
    checker.check(actual == grand_total, 'D6 安全风险总数（落盘 = 三格之和）',
                  repr(actual), grand_total)
    # D10 / D12 / D15 同一份漏洞表、另一套口径：全表数（与 IP 无关），所以它们与 D7/D8/D9 的
    # 「漏洞风险」那一段**不是**同一个数 —— 那一段按 IP 圈定，落盘的数也没理由相等。
    # 三格彼此也不相等（行数 3 / 台数 2 / 处置完成行数 4），把其中一格写成另一格的别名
    # 会在这里露馅。
    actual = ws['D10'].value
    checker.check(actual == VULN_HIGH_EXPLOITABLE_COUNT,
                  'D10 高危可利用漏洞数（落盘，全表数）', repr(actual), VULN_HIGH_EXPLOITABLE_COUNT)
    actual = ws['D12'].value
    checker.check(actual == VULN_HOT_ASSET_COUNT,
                  'D12 最新漏洞影响资产数（落盘，按「风险资产」去重）',
                  repr(actual), VULN_HOT_ASSET_COUNT)
    actual = ws['D15'].value
    checker.check(actual == VULN_SETTLED_COUNT,
                  'D15 已修复漏洞数（落盘，精确等于「处置完成」的行数）',
                  repr(actual), VULN_SETTLED_COUNT)
    # D17 与 D12 同值（alias），落盘后也得**真的在文件里**——内存里对不算数。
    actual = ws['D17'].value
    checker.check(actual == VULN_HOT_ASSET_COUNT,
                  'D17 受影响的最新漏洞数（落盘 = D12）', repr(actual), VULN_HOT_ASSET_COUNT)
    # D11 同一段落盘：核心资产那两段之和。它与上面任何一个数都不相等 ——
    # 相等的话「D11 其实是把某个系统的风险数抄过来了」在报告上看不出来。
    actual = ws['D11'].value
    checker.check(actual == ADMIN_WEAKPWD_TOTAL,
                  f'D11 管理员弱口令数量（落盘 = 弱密码 {ADMIN_WEAKPWD_BREAKDOWN[0]}'
                  f' + 事件 {ADMIN_WEAKPWD_BREAKDOWN[1]}）',
                  repr(actual), ADMIN_WEAKPWD_TOTAL)
    # G8 落盘：事件表「处置状态」那一列的行数。它读同一份事件表，但与 D11 那两段
    # （按核心资产 IP 圈定）不是一回事 —— 一个不圈、一个圈，所以两个数也不同
    # （7 vs 6），把 G8 误实现成"事件表里所有行"或某个 alias 都会在这里露馅。
    actual = ws['G8'].value
    checker.check(actual == CORE_EVENT_DISPOSED_COUNT,
                  'G8 处置安全事件总数（落盘，整张事件表按「处置状态」数行）',
                  repr(actual), CORE_EVENT_DISPOSED_COUNT)
    # D16 落盘：跨两份表的两段之和。同一份事件表上它与 G8 读同一列、数法不同
    # （G8 认三个状态、不管分类；D16 只认「处置完成」且二级分类要含「弱口令」），
    # 所以两个数不同（7 vs 3）；把 D16 误写成 disposedEventCount 或 D11 的镜像
    # 都会在这里露馅。完整边界在【13】。
    actual = ws['D16'].value
    checker.check(actual == CORE_DISPOSED_WEAKPWD_TOTAL,
                  f'D16 已处置弱口令数量（落盘 = 弱密码 {CORE_DISPOSED_WEAKPWD_BREAKDOWN[0]}'
                  f' + 事件 {CORE_DISPOSED_WEAKPWD_BREAKDOWN[1]}）',
                  repr(actual), CORE_DISPOSED_WEAKPWD_TOTAL)
    # G10 落盘：同一份资产表 + 同一份事件表，但圈法与 D7:D9 的事件那一段、与 G8/D11 都不同
    # （并集、不看分类/状态）。它与上面这几个数里唯一同值的是 D8（5，纯巧合，见上）。
    actual = ws['G10'].value
    checker.check(actual == CORE_EVENT_UNION_COUNT,
                  'G10 核心系统事件数量（落盘，三个系统的 IP 并集上按「影响资产」数行）',
                  repr(actual), CORE_EVENT_UNION_COUNT)

    # —— 边界一：只传 2 个系统 -> 第 3 个槽位没有系统。D5（写系统名）不写值 + 记错误，
    #    D9（第 3 个系统的风险总数）**写 0**（用户口径 2026-10-12：--business-systems 是可选参数，
    #    槽位空着就是没有这个系统，这个数就是 0 —— 与"该有却读不出"是两回事）。
    result = plan(CORE_SYSTEMS[:2])
    values = writes_of(result, CORE_SYSTEM_CELLS)
    checker.check(sorted(values) == ['D3', 'D4', 'D6', 'D7', 'D8', 'D9'],
                  '只传 2 个 -> 落值的地址（D9 写 0；D5 不写）',
                  ' '.join(sorted(values)), 'D3 D4 D6 D7 D8 D9')
    checker.check(values.get('D7') == CORE_SYSTEM_RISK_TOTALS[0]
                  and values.get('D8') == CORE_SYSTEM_RISK_TOTALS[1],
                  '只传 2 个 -> 前两个系统的风险总数照算',
                  f"D7={values.get('D7')} D8={values.get('D8')}",
                  f'D7={CORE_SYSTEM_RISK_TOTALS[0]} D8={CORE_SYSTEM_RISK_TOTALS[1]}')
    checker.check(values.get('D9') == 0,
                  '只传 2 个 -> D9 写 0（第 3 个系统没传，不是"算不出数"）',
                  repr(values.get('D9')), 0)
    # D6 = D7 + D8 + D9 三格之和：第 3 个槽位写 0，所以就等于前两个数之和
    # （用户投喂：「D6 = D7 + D8 + D9 的值」—— 空槽位按 0 加，不整格作废）。
    two_total = CORE_SYSTEM_RISK_TOTALS[0] + CORE_SYSTEM_RISK_TOTALS[1]
    checker.check(values.get('D6') == two_total,
                  '只传 2 个 -> D6 是这两个系统之和（缺的槽位按 0 加）',
                  repr(values.get('D6')), two_total)
    errors = errors_of(result, CORE_SYSTEM_CELLS)
    checker.check(sorted(errors) == ['D5'],
                  '只传 2 个 -> 进错误列表的只有 D5（它写的是系统名本身，没名字就写不出来）',
                  ' '.join(sorted(errors)), 'D5')
    checker.check(all('只给了 2 个系统' in m for m in errors.values()),
                  '错误信息点明是「这个槽位没传系统」而不是「算不出数」',
                  json.dumps(errors.get('D5'), ensure_ascii=False))

    # —— 边界一之二：只传 1 个系统 -> 空的是第 2、3 两个槽位，**两个都写 0**
    #    （不是只有最后那个槽位写 0；"每个空槽位各按 0 算"这条要逐槽位钉住）
    result = plan(CORE_SYSTEMS[:1])
    values = writes_of(result, CORE_SYSTEM_CELLS)
    checker.check(values.get('D7') == CORE_SYSTEM_RISK_TOTALS[0]
                  and values.get('D8') == 0 and values.get('D9') == 0,
                  '只传 1 个 -> 第 2、3 个槽位都写 0（D7 照算）',
                  f"D7={values.get('D7')} D8={values.get('D8')} D9={values.get('D9')}",
                  f'D7={CORE_SYSTEM_RISK_TOTALS[0]} D8=0 D9=0')
    checker.check(values.get('D6') == CORE_SYSTEM_RISK_TOTALS[0],
                  '只传 1 个 -> D6 = D7（另两个槽位按 0 加）',
                  repr(values.get('D6')), CORE_SYSTEM_RISK_TOTALS[0])
    checker.check(sorted(errors_of(result, CORE_SYSTEM_CELLS)) == ['D4', 'D5'],
                  '只传 1 个 -> 进错误列表的是 D4/D5 这两格系统名格，D8/D9 不报错',
                  ' '.join(sorted(errors_of(result, CORE_SYSTEM_CELLS))), 'D4 D5')

    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-core-two.xlsx'),
        'tables': fixtures,
        'statsPaths': paths,
        'businessSystems': CORE_SYSTEMS[:2],
        'beautify': False,
    })))
    ws = load_workbook(built['filePath'], data_only=False)[TEMPLATE_SHEET]
    template_ws = load_workbook(template, data_only=False)[TEMPLATE_SHEET]
    for addr in ('D5',):
        checker.check(ws[addr].value == template_ws[addr].value,
                      f'{addr} 保持模板原样（第 3 个系统没传）',
                      json.dumps(ws[addr].value, ensure_ascii=False),
                      json.dumps(template_ws[addr].value, ensure_ascii=False))
    # D9 与 D5 同槽位，落法却相反：D9 这次**真落了 0**（写的是数，不是名字）
    checker.check(ws['D9'].value == 0,
                  'D9 落盘 = 0（同一个空槽位：名字格留空、数字格写 0）',
                  repr(ws['D9'].value), 0)

    # —— 边界二：资产表「所属业务」整列一个字都没有 -> 三格风险总数**归零**，不是缺数。
    #    真实数据里这一列大面积为空（见 stats/metrics/asset.js 头注）：这一列空着只说明
    #    「这些机器不属于任何核心系统」，三个系统名下都没有资产，数出来就是 0。
    #    当成缺数的话，一份本来算得出来的报告会整片留空 —— 报 0 与不写值是两回事，
    #    前者是结论，后者是「没算出来」（R10/H6 禁的是后者被写成 0）。
    blank_asset = write_sheet(edges / 'asset-blank-business.xlsx', [
        ['IP地址', '互联网暴露', '所属业务', '重要级别', '资产名称'],
        ['10.0.0.1', '暴露', '', '', 'a'],
        ['10.0.0.2', '未暴露', '', '', 'b'],
    ])
    result = plan(CORE_SYSTEMS, dict(paths, asset=blank_asset))
    errors = errors_of(result, CORE_SYSTEM_CELLS)
    checker.check(not errors,
                  '所属业务整列为空 -> 7 格都不报错（空列是数据，不是缺数）',
                  json.dumps(errors, ensure_ascii=False), '（无）')
    checker.check(writes_of(result, CORE_SYSTEM_CELLS) == {
                      'D3': CORE_SYSTEMS[0], 'D4': CORE_SYSTEMS[1], 'D5': CORE_SYSTEMS[2],
                      'D6': 0, 'D7': 0, 'D8': 0, 'D9': 0},
                  '所属业务整列为空 -> 3 格风险总数与 D6 合计都是 0（不是缺数），系统名照写',
                  json.dumps(writes_of(result, CORE_SYSTEM_CELLS), ensure_ascii=False),
                  json.dumps({'D3': CORE_SYSTEMS[0], 'D4': CORE_SYSTEMS[1],
                              'D5': CORE_SYSTEMS[2], 'D6': 0, 'D7': 0, 'D8': 0, 'D9': 0},
                             ensure_ascii=False))
    # D11 走的是同一张资产表的**另一列**：重要级别整列为空 = 一台核心资产都没有 = 0，
    # 同样不是缺数。这不是顺带一提 —— 它钉的是「D11 的范围来自这一列，不是来自业务归属」。
    checker.check(writes_of(result, EXPECTED_WEAKPWD_CELLS) == {'D11': 0},
                  '重要级别整列为空 -> D11 是 0 且不报错（核心资产一台都没有）',
                  json.dumps(writes_of(result, EXPECTED_WEAKPWD_CELLS), ensure_ascii=False),
                  json.dumps({'D11': 0}, ensure_ascii=False))

    # —— 边界二之二：资产表里**根本没有**「所属业务」这一列 -> 这才是缺数。
    #    与上一条的分界就是 CELL_REGISTRY.md §7 C5：列在、值为空 = 数据本身为空（0）；
    #    列不在 = 列名对不上（平台动了表头），没人能证明这列是空的，所以不许数出 0。
    renamed_asset = write_sheet(edges / 'asset-renamed-business.xlsx', [
        ['IP地址', '互联网暴露', '业务归属', '重要级别', '资产名称'],
        ['10.0.0.1', '暴露', 'OA系统1', '核心', 'a'],
    ])
    result = plan(CORE_SYSTEMS, dict(paths, asset=renamed_asset))
    errors = errors_of(result, CORE_SYSTEM_CELLS)
    checker.check(sorted(errors) == ['D6', 'D7', 'D8', 'D9'],
                  '资产表缺「所属业务」列 -> 4 格风险总数（含 D6 合计）缺数',
                  ' '.join(sorted(errors)), 'D6 D7 D8 D9')
    checker.check(all('找不到' in m for m in errors.values()),
                  '错误信息点明是「找不到列」而不是「没有数据」',
                  json.dumps(errors.get('D7'), ensure_ascii=False))
    # 同一张资产表少了「所属业务」这一列，D11 要的「重要级别」还在 —— 它就照常算，
    # 一格都不缺。这条是「两把钥匙互不牵连」的证据：一张表出问题不该连坐另一套口径。
    checker.check(writes_of(result, EXPECTED_WEAKPWD_CELLS) == {'D11': 1},
                  '资产表少了「所属业务」列 -> D11 照算（它只看「重要级别」），不跟着缺数',
                  json.dumps(writes_of(result, EXPECTED_WEAKPWD_CELLS), ensure_ascii=False),
                  json.dumps({'D11': 1}, ensure_ascii=False))

    # —— 边界三：漏洞表被改了列名（平台动了表头）-> 缺数，且错误信息点明是缺列
    renamed_vuln = write_sheet(edges / 'vuln-renamed.xlsx', [
        ['风险资产', '风险标签'],
        ['10.0.0.1', '高可利用'],
    ])
    result = plan(CORE_SYSTEMS, dict(paths, vuln=renamed_vuln))
    errors = errors_of(result, CORE_SYSTEM_CELLS)
    checker.check(sorted(errors) == ['D6', 'D7', 'D8', 'D9'],
                  '漏洞表缺「威胁标签」-> 4 格风险总数（含 D6 合计）缺数',
                  ' '.join(sorted(errors)), 'D6 D7 D8 D9')
    checker.check(all('找不到' in m for m in errors.values()),
                  '错误信息点明是「找不到列」而不是「没有数据」',
                  json.dumps(errors.get('D7'), ensure_ascii=False))

    # —— 边界四：某一份**总表**没读到 —— 按新口径它就是一份**空表**（下载一定发生，
    #    真没下到时 scripts/build_report.py 早就拦下整份报告了，压根走不到取值层）。
    #    所以那一段就是 0，三个数照落 —— 不是整格作废（用户口径 2026-10-10）。
    #    这条口径下**报告上完全看不出**少算了一段 —— 这正是它危险的地方 ——
    #    所以取值层之外还有一道声：mssw_downloader.js 拼 ctx 时会把「哪几份表是空的」写进运行日志。
    #    这里钉的是取值层的三个数。
    #    CORE_SYSTEM_BREAKDOWN 的 (漏洞, 弱密码, 事件) 顺序就是这里的 index。
    for missing, index, label in [('vuln', 0, '漏洞表'),
                                  ('weakpwd', 1, '弱密码表'),
                                  ('event', 2, '事件表')]:
        result = plan(CORE_SYSTEMS, {k: v for k, v in paths.items() if k != missing})
        expected = {f'D{7 + rank}': sum(parts) - parts[index]
                    for rank, parts in enumerate(CORE_SYSTEM_BREAKDOWN)}
        # D6 是那三格之和，少了一段就跟着少那一段 —— 不是整格作废（同用户口径）。
        expected['D6'] = sum(expected.values())
        values = writes_of(result, CORE_RISK_TOTAL_CELLS)
        checker.check(values == expected,
                      f'{label}为空（0 行）-> 那一段就是 0、其余段照算（D6 合计跟着少那一段）',
                      json.dumps(values, ensure_ascii=False), json.dumps(expected, ensure_ascii=False))
        checker.check(not errors_of(result, CORE_SYSTEM_CELLS),
                      f'{label}为空 -> 7 格都不报错（空表按 0，不是缺数）',
                      json.dumps(errors_of(result, CORE_SYSTEM_CELLS), ensure_ascii=False), '（无）')
        if missing == 'vuln':
            # 漏洞表为空（0 行）时 D10 / D12 / D15 都写 0 —— 那是「这段时间一条漏洞都没有」。
            # 与 D7:D9 那一段是同一个事实，只是落法一个是「加 0」、一个是「写 0」。
            vuln_values = writes_of(result, EXPECTED_VULN_GROUP)
            checker.check(vuln_values == {'D10': 0, 'D12': 0, 'D15': 0, 'D17': 0},
                          '漏洞表为空（0 行）-> D10 / D12 / D15 / D17 都写 0（是结论，不是缺数）',
                          json.dumps(vuln_values, ensure_ascii=False),
                          json.dumps({'D10': 0, 'D12': 0, 'D15': 0, 'D17': 0}, ensure_ascii=False))
            checker.check(not errors_of(result, EXPECTED_VULN_GROUP),
                          '漏洞表为空 -> D10 / D12 / D15 / D17 都不报错',
                          json.dumps(errors_of(result, EXPECTED_VULN_GROUP), ensure_ascii=False),
                          '（无）')
        # D11 的两段就是「弱密码表」与「事件表」这两份 —— 缺哪份就少哪一段，其余照算；
        # 缺漏洞表与它无关（D11 不读漏洞表），所以它照样是 6。
        expected_d11 = ADMIN_WEAKPWD_TOTAL - (
            ADMIN_WEAKPWD_BREAKDOWN[0] if missing == 'weakpwd'
            else ADMIN_WEAKPWD_BREAKDOWN[1] if missing == 'event' else 0)
        checker.check(writes_of(result, EXPECTED_WEAKPWD_CELLS) == {'D11': expected_d11},
                      f'{label}为空 -> D11 里对应的那一段就是 0、其余照算',
                      json.dumps(writes_of(result, EXPECTED_WEAKPWD_CELLS), ensure_ascii=False),
                      json.dumps({'D11': expected_d11}, ensure_ascii=False))

    # —— 边界四之二：**资产表**为空 —— 三份风险表的一段仍是 0，但「业务归属 -> IP」得到的
    #    是**空集**，于是三个系统名下都没有资产，D6:D9 全是 0；D11 的「重要级别 -> 核心资产」
    #    同样是空集，也是 0。都是「算出来的 0」，不是缺数（用户口径 2026-10-10）。
    #    这与「资产表缺某一列」是两回事：那种时候没有列可读，才算取不到数（见边界二之二）。
    result = plan(CORE_SYSTEMS, {k: v for k, v in paths.items() if k != 'asset'})
    risk_values = writes_of(result, CORE_RISK_TOTAL_CELLS)
    checker.check(risk_values == {addr: 0 for addr in CORE_RISK_TOTAL_CELLS},
                  '资产表为空（0 行）-> D6:D9 都写 0（业务归属 -> 空集）',
                  json.dumps(risk_values, ensure_ascii=False),
                  json.dumps({addr: 0 for addr in CORE_RISK_TOTAL_CELLS}, ensure_ascii=False))
    checker.check(not errors_of(result, CORE_SYSTEM_CELLS),
                  '资产表为空 -> 7 格都不报错（空表按 0，不是缺数）',
                  json.dumps(errors_of(result, CORE_SYSTEM_CELLS), ensure_ascii=False), '（无）')
    checker.check(writes_of(result, EXPECTED_WEAKPWD_CELLS) == {'D11': 0},
                  '资产表为空 -> D11 也写 0（重要级别 -> 空集）',
                  json.dumps(writes_of(result, EXPECTED_WEAKPWD_CELLS), ensure_ascii=False),
                  json.dumps({'D11': 0}, ensure_ascii=False))
    checker.check(not errors_of(result, EXPECTED_WEAKPWD_CELLS),
                  '资产表为空 -> D11 也不报错（同一条口径）',
                  json.dumps(errors_of(result, EXPECTED_WEAKPWD_CELLS), ensure_ascii=False), '（无）')

    # —— 边界五：传了 4 个系统 -> 7 格全不写、全记错。
    #    模板里只有 3 个槽位（PPT 侧 core_system_1/2/3），**静默丢掉第 4 个**会让报告
    #    与用户传的东西对不上，所以宁可一格都不写。生产路径上 mssw_downloader.js 还会
    #    更早一步用 badRequest 拦掉，压根走不到写报告这步。
    result = plan(CORE_SYSTEMS + ['测试系统'])
    checker.check(not set(CORE_SYSTEM_CELLS) & set(result['written']),
                  '传 4 个系统 -> 这 7 格一个值都不写',
                  '是' if not set(CORE_SYSTEM_CELLS) & set(result['written']) else '否')
    errors = errors_of(result, CORE_SYSTEM_CELLS)
    checker.check(sorted(errors) == sorted(CORE_SYSTEM_CELLS),
                  '传 4 个系统 -> 7 格全进错误列表', ' '.join(sorted(errors)))
    checker.check(all('最多 3 个' in m for m in errors.values()),
                  '错误信息点明是「最多 3 个」',
                  json.dumps(errors.get('D7'), ensure_ascii=False))
    # 多出来的那个系统不许被安顿到别处去：除了这 7 格、G6/H6/I6（它们也要系统名，
    # 同样撞「最多 3 个」）、G10（同上：它也读 --business-systems 的全部槽位）
    # 与事件表 fixture 对不上的那几处（事件定性 21 格、G7、G9），不该有别的格子报错
    stray = sorted(set(e['addr'] for e in result['errors'])
                   - set(CORE_SYSTEM_CELLS) - {'G6', 'H6', 'I6'} - set(EXPECTED_EVENT_CELLS)
                   - set(EXPECTED_CONTAINED_CELLS) - set(EXPECTED_CORE_SYSTEM_EVENT_CELLS)
                   - set(EXPECTED_RESPONSE_CELLS))
    checker.check(stray == [], '传 4 个系统 -> 没有别的格子被牵连', ' '.join(stray) or '（无）')


# ---------------------------------------------------------------------------
# 【8】事件定性统计：C135:I137 落盘
# ---------------------------------------------------------------------------

def check_event_end_to_end(checker, bridge, workdir, fixtures, event_path):
    """事件表接进 ctx 之后，事件定性那 21 格必须**真的落盘**，且不惊动别的格子。

    与【6】（告警定性）同一套路 —— 同一套排行算法（stats/metrics/ranking.js），
    只有数据源（ctx.eventRows）与列名（「GPT定性标签」）不同。三段：
    135 行名称 / 136 行数量 / 137 行占比，各 7 个槽位。

    这里比【6】多一条最要紧的断言：**占位符 `-` 与空白都不算一种定性、也不进分母**。
    真实事件表那一列绝大多数行都是 `-`（华能集团样本 2290/2347），算进去的话
    报告的第 1 名会是一个横杠。fixture 里那三行若被算进去，分母会变成 10、
    第 5 名还会多出一个「-」。

    另外三条边界（缺列 / 空表 / 整列全是占位符）走 plan 而不是 build：
    它们与落盘无关，断的是"必须一个值都不写、且全进错误列表"。

    同一段里顺带钉 G8「处置安全事件总数」—— 它读的是**同一份事件表的另一列**（「处置状态」）。
    两格各认各的列：名次统计缺列时写空串，G8 缺列时不写值 + 报错，所以 fixture 里两列都有。
    G8 的完整边界（各种命中 / 不命中的写法）在【12】单独验。
    """
    checker.section('8】事件定性统计端到端（C135:I137 真的落进报告）')

    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-event.xlsx'),
        'tables': fixtures,
        'eventPath': event_path,
        'beautify': False,
    })))

    stats = built['statistics']
    # 本段只接事件表：其余总表都是空的 -> 计数格写 0、名次格（告警那 14 格）写空串，都算落值；
    # 没传 --business-systems -> D6:D9 与 G6/H6/I6/G10 也写 0（用户口径 2026-10-12）。
    # 报错的只有六种：D3/D4/D5（没传系统名 —— 它们写的是名字不是数），
    # 再加 D11、D16 与 G7、G9 —— 它们都要读事件表上这份 fixture **没有**的列
    # （D11 要「影响资产」、D16 要「安全事件二级分类」、
    # G7 要「GPT研判结论」+ 两个时间列、G9 要「推送状态」+ 预处理的「响应时长」列），
    # 列名对不上（口径 3：缺列仍报错）。
    # G8 读的是同一份表的「处置状态」列（这份 fixture 有），所以它照常落值 ——
    # 一条"同一张表上各列各有各的键"的旁证：同一份数据上 G8 落值、D16/G7/G9 报缺列。
    expected_written = sorted(set(EXPECTED_WRITE_CELLS) - {'D11'} - set(EXPECTED_DISPOSED_WEAKPWD_CELLS)
                              - set(EXPECTED_CONTAINED_CELLS) - set(EXPECTED_RESPONSE_CELLS))
    expected_errors = sorted(EXPECTED_NO_SYSTEM_ERRORS + ['D11']
                             + EXPECTED_DISPOSED_WEAKPWD_CELLS + EXPECTED_CONTAINED_CELLS
                             + EXPECTED_RESPONSE_CELLS)
    checker.check(stats['connected'] is True, 'statistics.connected', stats['connected'], True)
    checker.check(sorted(stats['written']) == expected_written,
                  '落值的地址 = 3 个报告参数格 + 21 格事件定性 + 空表兜住的告警定性 14 格 /'
                  ' D10/D12/D15/D17 / G5 / G8 / D6:D9 与 G6/H6/I6/G10（没传系统名 -> 0）'
                  '（D11 缺「影响资产」列、D16 缺「安全事件二级分类」列、'
                  ' G7 缺「GPT研判结论」与两个时间列、G9 缺「推送状态」与「响应时长」列）',
                  ' '.join(sorted(stats['written'])), ' '.join(expected_written))
    checker.check(sorted(e['addr'] for e in stats['errors']) == expected_errors,
                  'errors = D3/D4/D5（没传系统名）'
                  ' + D11（事件表缺「影响资产」列）+ D16（缺「安全事件二级分类」列）'
                  ' + G7（缺「GPT研判结论」列）+ G9（缺「推送状态」列）',
                  ' '.join(sorted(e['addr'] for e in stats['errors'])), ' '.join(expected_errors))
    checker.check(len(stats['unresolved']) == EXPECTED_UNRESOLVED,
                  'statistics.unresolved', len(stats['unresolved']), EXPECTED_UNRESOLVED)
    checker.check(len(stats['applied']) == len(expected_written),
                  'statistics.applied（实际落笔，Python 侧没丢格）',
                  len(stats['applied']), len(expected_written))

    ws = load_workbook(built['filePath'], data_only=False)[TEMPLATE_SHEET]
    for rank, (label, count) in enumerate(zip(EVENT_LABELS, EVENT_COUNTS)):
        column = chr(ord('C') + rank)
        label_addr = f'{column}{EVENT_LABEL_ROW}'
        count_addr = f'{column}{EVENT_COUNT_ROW}'
        share_addr = f'{column}{EVENT_SHARE_ROW}'

        actual_label = ws[label_addr].value or ''
        checker.check(actual_label == label, f'{label_addr} 定性名称',
                      json.dumps(actual_label, ensure_ascii=False),
                      json.dumps(label, ensure_ascii=False))

        actual_count = ws[count_addr].value
        if count:
            checker.check(actual_count == count, f'{count_addr} 出现行数', repr(actual_count), count)
        else:
            checker.check(actual_count in (None, ''), f'{count_addr} 无此名次 -> 空串',
                          json.dumps(actual_count, ensure_ascii=False), '(空)')

        # 分母是全部**有效**定性的出现总次数（EVENT_TOTAL=7）：`-` / 空串 / 纯空白都不进。
        # 若把 `-` 算进去，C137 会是 3/8 而不是 3/7；把空串与纯空白再算上则是 3/10。
        share = ws[share_addr].value
        if count:
            expected_share = count / EVENT_TOTAL
            ok = isinstance(share, (int, float)) and abs(share - expected_share) < 1e-12
            shown, want = json.dumps(share), json.dumps(expected_share)
        else:
            ok, shown, want = share in (None, ''), json.dumps(share, ensure_ascii=False), '(空)'
        checker.check(ok, f'{share_addr} 占比', shown, want)
        checker.check(ws[share_addr].number_format == '0.00%',
                      f'{share_addr} 百分号格式', ws[share_addr].number_format, '0.00%')

    # G8 在同一段里顺带落盘：它读的是**同一份事件表的另一列**（「处置状态」）。
    # 这一份 fixture 里那一列刻意混了四种命中、四种不命中（待处置 / 处置中 / 带括号 /
    # 空值），命中 5 行 —— 与分母 7、与第 1 名的计数 3 都不同，所以"G8 抄了名次统计的某个数"
    # 会在这里露馅。详见 EVENT_DISPOSED_COUNT 的说明。
    actual = ws['G8'].value
    checker.check(actual == EVENT_DISPOSED_COUNT,
                  'G8 处置安全事件总数（落盘，「处置状态」精确命中的行数）',
                  repr(actual), EVENT_DISPOSED_COUNT)
    edges = workdir / 'event-edges'
    edges.mkdir(parents=True, exist_ok=True)
    # 边界一：表头里没有「GPT定性标签」（平台改了列名）-> 21 格全进错误列表、一个都不写
    # （G8 在这份 fixture 上也缺「处置状态」列，它的缺列路径由【12】单独钉）
    renamed = write_sheet(edges / 'renamed.xlsx',
                          [['事件名称', 'GPT研判结论'], ['e1', '银狐病毒']])
    plan = call_bridge(bridge, 'plan', 'event', _b64(json.dumps({'path': renamed})))
    event_errors = {e['addr']: e['message'] for e in plan['errors'] if e['addr'] in EVENT_ADDRS}
    checker.check(sorted(event_errors) == sorted(EVENT_ADDRS),
                  '列名被改 -> 21 格全进错误列表', ' '.join(sorted(event_errors)))
    checker.check(not set(EVENT_ADDRS) & set(plan['written']),
                  '列名被改 -> 一个值都不写',
                  '是' if not set(EVENT_ADDRS) & set(plan['written']) else '否')
    checker.check(all('找不到' in m for m in event_errors.values()),
                  '错误信息点明是「找不到列」而不是「没有数据」',
                  json.dumps(event_errors.get('C135'), ensure_ascii=False))

    # 边界二：空表（只有表头）-> 21 格全写**空串**、一个错误都不记（0 行是正常数据）
    empty = write_sheet(edges / 'empty-table.xlsx', [[EVENT_LABEL, '事件名称']])
    plan = call_bridge(bridge, 'plan', 'event', _b64(json.dumps({'path': empty})))
    values = {w['addr']: w['value'] for w in plan['writes']}
    event_errors = {e['addr']: e['message'] for e in plan['errors'] if e['addr'] in EVENT_ADDRS}
    checker.check(not event_errors,
                  '空表 -> 21 格一个错误都不记（0 行是正常数据）',
                  ' '.join(sorted(event_errors)) or '（无）')
    checker.check(all(values.get(addr) == '' for addr in EVENT_ADDRS),
                  '空表 -> 21 格全写空串（名次槽位本来就是空的）',
                  '是' if all(values.get(a) == '' for a in EVENT_ADDRS) else json.dumps(
                      {a: values.get(a) for a in EVENT_ADDRS if values.get(a) != ''},
                      ensure_ascii=False))
    checker.check(plan['parsed']['rowCount'] == 0, '空表行数为 0', plan['parsed']['rowCount'], 0)

    # 边界三：整列都是占位符 `-` / 空白 -> **一种定性都没有**，21 格同样全写空串、不报错。
    #         这条是「`-` 不是一种定性」的正面证据：若把它当定性，C135 会写成一个横杠。
    placeholders = write_sheet(edges / 'placeholder.xlsx', [
        [EVENT_LABEL, '事件名称'],
        ['-', 'e1'],
        ['--', 'e2'],
        ['   ', 'e3'],
        ['', 'e4'],
    ])
    plan = call_bridge(bridge, 'plan', 'event', _b64(json.dumps({'path': placeholders})))
    values = {w['addr']: w['value'] for w in plan['writes']}
    event_errors = {e['addr']: e['message'] for e in plan['errors'] if e['addr'] in EVENT_ADDRS}
    checker.check(not event_errors,
                  '整列全是占位符 / 空白 -> 21 格一个错误都不记（没有定性就是没有）',
                  ' '.join(sorted(event_errors)) or '（无）')
    checker.check(all(values.get(addr) == '' for addr in EVENT_ADDRS),
                  '整列全是占位符 -> 21 格全写空串（`-` 不是一种定性）',
                  '是' if all(values.get(a) == '' for a in EVENT_ADDRS) else json.dumps(
                      {a: values.get(a) for a in EVENT_ADDRS if values.get(a) != ''},
                      ensure_ascii=False))


def make_high_exploitable_vuln_table(directory):
    """D10 / D12 / D15 / D17 专用 fixture：就用 CORE_VULN_TABLE 那一份。

    期望值见 VULN_HIGH_EXPLOITABLE_COUNT（行数 3）、VULN_HOT_ASSET_COUNT（去重台数 2）
    与 VULN_SETTLED_COUNT（「处置完成」4 行）——
    它同时是【7】里 D7/D8/D9「漏洞风险」那一段的数据源，所以这一份 fixture 顺带证明了一件事：
    **同一张表、同一列，D10/D12 数全表（3 / 2），D7/D8/D9 数圈定 IP（2 / 2 / 0）**，
    两者不是一回事。
    """
    directory.mkdir(parents=True, exist_ok=True)
    return write_sheet(directory / 'vuln-high-exploitable.xlsx', CORE_VULN_TABLE)


# ---------------------------------------------------------------------------
# 【9】D10 高危可利用漏洞数 / D12 最新漏洞影响资产数 / D15 已修复漏洞数
# ---------------------------------------------------------------------------

def check_high_exploitable_vuln(checker, bridge, workdir, vuln_path):
    """D10 / D12 / D15 读的是**同一张漏洞表**，只有判据不同：

      · D10「高危可利用漏洞数」= 「威胁标签」含「高可利用」的**行数**（不去重）
      · D12「最新漏洞影响资产数」= 「威胁标签」含「热点漏洞」的漏洞影响到的**资产台数**
        （按「风险资产」去重）
      · D15「已修复漏洞数」= 「处置状态」**精确等于**「处置完成」的**行数**
      · D17「受影响的最新漏洞数」= D12（alias，自己不读表）

    正因为读的是同一张表，下面四条边界（表里有数据 / 空表写 0 / 整份没下到（= 空表，同样写 0）
    / 表头缺列（报错不写值））**三格一起走**，一次断三格；再去一条只属于 D12 的去重。

    D10/D12/D15 的期望值**刻意不同**（3 / 2 / 4）：把其中一格误实现成另一格的别名，
    第一条就红。D17 单列一条断言，钉的是「它跟着 D12 走」——值一样、报错也一样。
    """
    checker.section('9】D10 高危可利用漏洞数 / D12 最新漏洞影响资产数 / D15 已修复漏洞数 / '
                    'D17 = D12（同一张漏洞表）')

    def expected():
        return {'D10': VULN_HIGH_EXPLOITABLE_COUNT,
                'D12': VULN_HOT_ASSET_COUNT,
                'D15': VULN_SETTLED_COUNT,
                'D17': VULN_HOT_ASSET_COUNT}

    edges = workdir / 'vuln-edges'
    edges.mkdir(parents=True, exist_ok=True)

    def plan(path):
        return call_bridge(bridge, 'plan', 'vuln', _b64(json.dumps({'path': path})))

    def writes_of(result):
        return {w['addr']: w['value'] for w in result['writes'] if w['addr'] in EXPECTED_VULN_GROUP}

    def errors_of(result):
        return {e['addr']: e['message'] for e in result['errors'] if e['addr'] in EXPECTED_VULN_GROUP}

    def source_errors(errors):
        """只看自己读表的 D10/D12/D15 —— 它们的错该是「找不到列」/「没读到」。"""
        return {addr: msg for addr, msg in errors.items() if addr in EXPECTED_VULN_CELLS}

    def alias_errors(errors):
        """D17 的错只有一种来源：alias 目标没算出值。"""
        return {addr: msg for addr, msg in errors.items() if addr in EXPECTED_ALIAS_CELLS}

    # —— 正题：表里有数据
    result = plan(vuln_path)
    checker.check(writes_of(result) == expected(),
                  'D10 = 含「高可利用」的行数；D12 = 含「热点漏洞」的漏洞影响的资产台数；'
                  'D15 = 精确等于「处置完成」的行数（带括号的与「待处置」都不算）；'
                  'D17 = D12',
                  json.dumps(writes_of(result), ensure_ascii=False),
                  json.dumps(expected(), ensure_ascii=False))
    checker.check(errors_of(result) == {}, 'D10 / D12 / D15 / D17 都没有缺数',
                  json.dumps(errors_of(result), ensure_ascii=False), '（无）')

    # —— 边界一：表在、只有表头 -> 四格都写 0，不是缺数
    empty = write_sheet(edges / 'empty.xlsx',
                        [[VULN_THREAT_TAG, VULN_RISK_ASSET, VULN_DISPOSITION]])
    result = plan(empty)
    checker.check(writes_of(result) == {'D10': 0, 'D12': 0, 'D15': 0, 'D17': 0},
                  '空表（0 行）-> D10 / D12 / D15 / D17 都写 0（是结论，不是缺数）',
                  json.dumps(writes_of(result), ensure_ascii=False),
                  json.dumps({'D10': 0, 'D12': 0, 'D15': 0, 'D17': 0}, ensure_ascii=False))
    checker.check(errors_of(result) == {}, '空表 -> D10 / D12 / D15 / D17 都不报错',
                  json.dumps(errors_of(result), ensure_ascii=False), '（无）')

    # —— 边界二：表头里既没有「威胁标签」也没有「处置状态」（平台改了列名）
    #    -> 四格都不写值 + 都记错误，且**各报各缺的那一列**：
    #    D10/D12 缺「威胁标签」、D15 缺「处置状态」——这条正好证明三格不是共用一个键。
    #    注意第二列叫「漏洞标签」—— 投喂 D10/D12 时说的就是这个名字，但平台导出的真列名是
    #    「威胁标签」（见 stats/metrics/vuln.js 的头注）；这一条正是拿它当反例钉住的。
    renamed = write_sheet(edges / 'renamed.xlsx', [
        [VULN_RISK_ASSET, '漏洞标签'],
        ['10.0.0.1', '高可利用'],
    ])
    result = plan(renamed)
    checker.check(not writes_of(result), '缺列 -> D10 / D12 / D15 / D17 一个值都不写',
                  json.dumps(writes_of(result), ensure_ascii=False), '（无）')
    errors = errors_of(result)
    checker.check(sorted(errors) == ['D10', 'D12', 'D15', 'D17'], '缺列 -> 四格都进错误列表',
                  ' '.join(sorted(errors)), 'D10 D12 D15 D17')
    mine = source_errors(errors)
    checker.check(all('找不到「威胁标签」' in mine.get(a, '') for a in ('D10', 'D12')),
                  'D10 / D12 报的是缺「威胁标签」列（不是「没有数据」）',
                  json.dumps(mine.get('D10'), ensure_ascii=False))
    checker.check('找不到「处置状态」' in mine.get('D15', ''),
                  'D15 报的是缺「处置状态」列 —— 三格各认各的列，不是共用同一个键',
                  json.dumps(mine.get('D15'), ensure_ascii=False))
    alias = alias_errors(errors)
    checker.check(all('alias 目标 D12 没有算出值' in m for m in alias.values()),
                  'D17 的错误信息点明是「alias 目标 D12 没有算出值」而不是「找不到列」'
                  '（它自己不读表，列改不改名与它无关）',
                  json.dumps(alias.get('D17'), ensure_ascii=False))

    # —— 边界三：整份没下到时 ctx 里没有 vulnRows 这个字段 —— 按新口径这与「空表」是
    #    同一件事（下载一定发生，真没下到时 scripts/build_report.py 早拦下了、整份报告不出）。
    #    createContext 把缺席的字段归一成 []，于是四格都写 0、都不报错。
    result = call_bridge(bridge, 'plan', 'core', _b64(json.dumps({'paths': {}})))
    checker.check(writes_of(result) == {'D10': 0, 'D12': 0, 'D15': 0, 'D17': 0},
                  '漏洞表缺席（= 空表）-> D10 / D12 / D15 / D17 都写 0',
                  json.dumps(writes_of(result), ensure_ascii=False),
                  json.dumps({'D10': 0, 'D12': 0, 'D15': 0, 'D17': 0}, ensure_ascii=False))
    checker.check(errors_of(result) == {},
                  '漏洞表缺席 -> 四格都不报错（0 是结论，不是缺数）',
                  json.dumps(errors_of(result), ensure_ascii=False), '（无）')

    # —— 边界四（只属于 D12）：**按「风险资产」去重**，不是数行数。
    #    这一条非有不可：CORE_VULN_TABLE 里含「热点漏洞」的两行 IP 恰好不同，
    #    去重与数行数在那里都出 2，那份表**分不出**两种写法。这份 fixture 专门把它们分开：
    #      · 三行指同一台（第 3 行带 `(资产组名:xx)` 后缀，归一是同一台）
    #      · 一台再各一行，共 5 行「热点漏洞」-> 去重后只剩 2 台（数行数会出 5）
    #      · 末行「风险资产」为空 —— 那行指不到任何一台资产，不能算一台（否则虚增 1）
    #      · 其中一行只含「高可利用」，用来确认两个关键词互不串台：D12 只认「热点漏洞」
    #    D15 在这份 fixture 里是 0（全是「待处置」）—— 顺带证明它不跟着「威胁标签」走。
    dedupe = write_sheet(edges / 'hot-dedupe.xlsx', [
        [VULN_RISK_ASSET, VULN_THREAT_TAG, VULN_DISPOSITION],
        ['10.0.0.1', '热点漏洞', '待处置'],
        ['10.0.0.1', '热点漏洞、勒索利用', '待处置'],
        ['10.0.0.1(资产组名:管理IP范围)', '热点漏洞', '待处置'],
        ['10.0.0.2', '热点漏洞', '待处置'],
        ['10.0.0.2', '高可利用', '待处置'],
        ['', '热点漏洞', '待处置'],
    ])
    result = plan(dedupe)
    checker.check(writes_of(result) == {'D10': 1, 'D12': 2, 'D15': 0, 'D17': 2},
                  'D12 按「风险资产」去重（5 行热点漏洞、归一后只有 2 台；空 IP 不算一台），'
                  '而 D10 仍是行数；D15 与标签无关（全是「待处置」-> 0）；D17 跟着 D12 走',
                  json.dumps(writes_of(result), ensure_ascii=False),
                  json.dumps({'D10': 1, 'D12': 2, 'D15': 0, 'D17': 2}, ensure_ascii=False))


# ---------------------------------------------------------------------------
# 【12】G8 处置安全事件总数：事件表「处置状态」精确匹配三个状态
# ---------------------------------------------------------------------------
#
# 表头四列全是**真实列名**（「GPT定性标签」「影响资产」「安全事件二级分类」「处置状态」，
# 与 stats/metrics/event.js 里那几个常量同一来源：平台导出的表头逐字）。
# 四列都写上，是为了让这一段里**只有 G8 一个量在被考** —— 少写哪一列，缺列报错就会
# 混进来，那时"G8 数对了"这件事反而被别的格子的错误盖住。
#
# 12 行把 G8 的判据铺满，命中的与被排除的刻意摆在同一列里对照：
#   · 三个状态各有一条真命中（已遏制 / 处置完成 / 已忽略）—— 少一个就分不出漏了哪个词
#   · **整格精确相等**：`处置完成（已修复）`、`已遏制（已缓解）` 是带括号的反例，
#     写成"包含"或"以…开头"这里会多出 2；近义词 `已处置` 同样不算；
#     `待处置` / `处置中` 连"处置"两个字都不沾，前缀匹配也漏不掉它们
#   · 比较前**去首尾空白**：第 4 行的 ` 处置完成 ` 要算
#   · 空值与占位符 `-` 都不算；第 12 行的**定性为空但处置状态命中** —— 要算
#     （G8 只看处置状态这一列，不看定性；两列在真实表里本来就是各管各的）
# 命中 5 行。这个数与这份表里任何"行数"都不同（12 行 / 有效定性 7 次），
# 把 G8 误实现成"数所有行""数有定性的行"都会在这里露红。
DISPOSITION_EVENT_TABLE = [
    [EVENT_LABEL, '影响资产', '安全事件二级分类', DISPOSITION_EVENT_COLUMN],
    ['银狐病毒', '10.0.0.1', '账号安全事件', '已遏制'],              # +1
    ['银狐病毒', '10.0.0.1', '账号安全事件', '处置完成'],            # +2
    ['银狐病毒', '10.0.0.2', '下载恶意文件', '已忽略'],              # +3
    ['未知威胁', '10.0.0.2', '下载恶意文件', ' 处置完成 '],          # +4（首尾空白要算）
    ['未知威胁', '10.0.0.3', '下载恶意文件', '处置中'],
    ['未知威胁', '10.0.0.3', '下载恶意文件', '待处置'],
    ['挖矿木马', '10.0.0.4', '下载恶意文件', '处置完成（已修复）'],
    ['挖矿木马', '10.0.0.4', '下载恶意文件', '已遏制（已缓解）'],
    ['病毒', '10.0.0.5', '下载恶意文件', '已处置'],
    ['病毒', '10.0.0.5', '下载恶意文件', ''],
    ['病毒', '10.0.0.6', '下载恶意文件', '-'],
    ['', '10.0.0.6', '下载恶意文件', '已忽略'],                      # +5（定性为空也算）
]

# G8 在这份 fixture 上的值（见上）。
DISPOSITION_EVENT_COUNT = 5


def make_disposition_event_table(directory):
    """G8 专用 fixture，见 DISPOSITION_EVENT_TABLE 的说明。"""
    directory.mkdir(parents=True, exist_ok=True)
    return write_sheet(directory / 'event-disposition.xlsx', DISPOSITION_EVENT_TABLE)


def check_disposed_events(checker, bridge, workdir, event_path):
    """G8「处置安全事件总数」读事件表的「处置状态」一列，与那 21 格（「GPT定性标签」）**同一张表、
    不同列** —— 所以这一段要同时钉住两件事：G8 数得对，以及它没把两列搞混。

    边界三条：
      · 表头缺「处置状态」-> 只 G8 不写值 + 报「找不到「处置状态」列」，
        那 21 格**照常落值**（它们认的是另一列）—— 这条正是"两列各有各的键"的证据
      · 空表（0 行）-> G8 写 0，不报错（0 是结论，不是缺数）
      · 整列都不命中（全是「待处置」）-> G8 写 0，不报错

    与【7】那一份 core fixture 上的 G8（= CORE_EVENT_DISPOSED_COUNT）互为旁证：
    两份表、两套行数，同一格的两个数不一样 —「G8 是个写死的常数」在这里会露红。
    """
    checker.section('12】G8 处置安全事件总数（事件表「处置状态」精确匹配三个状态）')

    edges = workdir / 'disposition-edges'
    edges.mkdir(parents=True, exist_ok=True)

    def plan(path):
        return call_bridge(bridge, 'plan', 'event', _b64(json.dumps({'path': path})))

    def writes_of(result, cells):
        return {w['addr']: w['value'] for w in result['writes'] if w['addr'] in cells}

    def errors_of(result, cells):
        return {e['addr']: e['message'] for e in result['errors'] if e['addr'] in cells}

    # —— 正题：12 行里命中 5 行（判据见 DISPOSITION_EVENT_TABLE 的说明）
    result = plan(event_path)
    value = writes_of(result, EXPECTED_EVENT_DISPOSITION_CELLS)
    checker.check(value == {'G8': DISPOSITION_EVENT_COUNT},
                  'G8 = 「已遏制 / 处置完成 / 已忽略」整格精确相等的行数'
                  '（带括号的、近义词「已处置」、待处置 / 处置中都不算；首尾空白要算）',
                  json.dumps(value, ensure_ascii=False),
                  json.dumps({'G8': DISPOSITION_EVENT_COUNT}, ensure_ascii=False))
    # 同一份表上那 21 格也得照常算出来：证明 G8 的数不是从定性那一列抄来的
    ranks = writes_of(result, EXPECTED_EVENT_CELLS)
    checker.check(ranks.get('C135') == '银狐病毒' and ranks.get('C136') == 3,
                  '同一份表上事件定性 21 格照常算（G8 与它们各读各的列）',
                  json.dumps({'C135': ranks.get('C135'), 'C136': ranks.get('C136')},
                             ensure_ascii=False),
                  json.dumps({'C135': '银狐病毒', 'C136': 3}, ensure_ascii=False))
    checker.check(not errors_of(result, EXPECTED_EVENT_SOURCE_CELLS),
                  'G8 与那 21 格都没有缺数',
                  json.dumps(errors_of(result, EXPECTED_EVENT_SOURCE_CELLS), ensure_ascii=False),
                  '（无）')

    # —— 边界一：表头里没有「处置状态」（平台改了列名）-> 只 G8 不写值 + 报缺这一列；
    #    那 21 格认的是「GPT定性标签」，照常落值 —— 两列各有各的键。
    renamed = write_sheet(edges / 'renamed.xlsx', [
        [EVENT_LABEL, '影响资产', '安全事件二级分类', '状态'],
        ['银狐病毒', '10.0.0.1', '账号安全事件', '已遏制'],
    ])
    result = plan(renamed)
    checker.check(not writes_of(result, EXPECTED_EVENT_DISPOSITION_CELLS),
                  '缺「处置状态」列 -> G8 一个值都不写',
                  json.dumps(writes_of(result, EXPECTED_EVENT_DISPOSITION_CELLS), ensure_ascii=False),
                  '（无）')
    errors = errors_of(result, EXPECTED_EVENT_DISPOSITION_CELLS)
    checker.check(sorted(errors) == ['G8'], '缺「处置状态」列 -> 只有 G8 进错误列表',
                  ' '.join(sorted(errors)), 'G8')
    checker.check(all('找不到「处置状态」' in m for m in errors.values()),
                  '错误信息点明是缺「处置状态」列（不是「没有数据」、也不是缺「GPT定性标签」）',
                  json.dumps(errors.get('G8'), ensure_ascii=False))
    checker.check(not errors_of(result, EXPECTED_EVENT_CELLS),
                  '缺「处置状态」列 -> 那 21 格照常落值（它们不认这一列）',
                  json.dumps(errors_of(result, EXPECTED_EVENT_CELLS), ensure_ascii=False), '（无）')

    # —— 边界二：空表（只有表头）-> G8 写 0，不报错
    empty = write_sheet(edges / 'empty-table.xlsx', [
        [EVENT_LABEL, '影响资产', '安全事件二级分类', DISPOSITION_EVENT_COLUMN],
    ])
    result = plan(empty)
    checker.check(writes_of(result, EXPECTED_EVENT_DISPOSITION_CELLS) == {'G8': 0},
                  '空表（0 行）-> G8 写 0（是结论，不是缺数）',
                  json.dumps(writes_of(result, EXPECTED_EVENT_DISPOSITION_CELLS), ensure_ascii=False),
                  json.dumps({'G8': 0}, ensure_ascii=False))
    checker.check(not errors_of(result, EXPECTED_EVENT_SOURCE_CELLS),
                  '空表 -> G8 与那 21 格都不报错',
                  json.dumps(errors_of(result, EXPECTED_EVENT_SOURCE_CELLS), ensure_ascii=False),
                  '（无）')

    # —— 边界三：整列都不命中（全是「待处置」）-> 写 0、不报错。
    #    「表里有行却一个都不命中」与「表是空的」是两件事，两者都得是 0 ——
    #    但只有这一条能证明 G8 没把"有行"当成"有命中"。
    none_matched = write_sheet(edges / 'none-matched.xlsx', [
        [EVENT_LABEL, '影响资产', '安全事件二级分类', DISPOSITION_EVENT_COLUMN],
        ['银狐病毒', '10.0.0.1', '账号安全事件', '待处置'],
        ['未知威胁', '10.0.0.2', '下载恶意文件', '处置中'],
    ])
    result = plan(none_matched)
    checker.check(writes_of(result, EXPECTED_EVENT_DISPOSITION_CELLS) == {'G8': 0},
                  '表里有行但一条都不命中 -> G8 写 0（不是不写值、也不是数成 2）',
                  json.dumps(writes_of(result, EXPECTED_EVENT_DISPOSITION_CELLS), ensure_ascii=False),
                  json.dumps({'G8': 0}, ensure_ascii=False))
    checker.check(not errors_of(result, EXPECTED_EVENT_SOURCE_CELLS),
                  '一条都不命中 -> G8 不报错（那是结论，不是缺数）',
                  json.dumps(errors_of(result, EXPECTED_EVENT_SOURCE_CELLS), ensure_ascii=False),
                  '（无）')


# ---------------------------------------------------------------------------
# 【13】D16 已处置弱口令数量（弱密码表 + 事件表，两段相加）
# ---------------------------------------------------------------------------
#
# 这一格跨**两份表**，所以 fixture 也是两份，两段各自留正反例：
#   · 第一段看弱密码表的「处置状态」：整格精确相等才认 —— 两种括号写法
#     （全角 `处置完成（误报）` / 半角 `处置完成(误报)`，两种真实平台都写过）都不算
#   · 第二段看事件表的**两个条件同时满足**：二级分类含「弱口令」（含即可，`Telnet弱口令`
#     /`Web弱口令` 这种复合词要算；「弱密码爆破」含的是「弱密码」，本格不认）
#     **且**「处置状态」精确等于「处置完成」
#
# 三个数刻意彼此不同：段① 5、段② 3、G8 在同一份事件表上 7。相等的话
# 「D16 其实是把 G8 抄过来了」「只有一份表时它把另一段当 0 之外的数加了」在报告上看不出来。

D16_WEAKPWD_TABLE = [
    ['风险资产', '弱点类型', WEAKPWD_DISPOSITION_COLUMN],
    ['10.0.0.1', 'ssh弱口令', '处置完成'],                  # 段① +1
    ['10.0.0.2', 'rdp弱口令', ' 处置完成 '],                # +2（首尾空白要算）
    ['10.0.0.9', 'ssh弱口令', '处置完成'],                  # +3
    ['10.0.0.10', 'ssh弱口令', '处置完成'],                 # +4
    ['10.0.0.11', 'ssh弱口令', '处置完成'],                 # +5
    ['10.0.0.3', 'ssh弱口令', '处置完成（误报）'],           # 全角括号 -> 不算
    ['10.0.0.4', 'ssh弱口令', '处置完成(误报)'],             # 半角括号 -> 不算
    ['10.0.0.5', 'ssh弱口令', '待处置'],
    ['10.0.0.6', 'ssh弱口令', '已遏制'],                    # 别的状态 -> 不算（本格只认「处置完成」）
    ['10.0.0.7', 'ssh弱口令', ''],
    ['10.0.0.8', 'ssh弱口令', '-'],
]

# D16 第一段在这份 fixture 上的值。上面的 IP 一台都不在资产表里（这段根本不读 IP）——
# 所以同一段里 D11 的弱密码段是 0：两格数出来的数不同，正是「D16 不看 IP」的证据。
D16_WEAKPWD_COUNT = 5

D16_EVENT_TABLE = [
    [EVENT_LABEL, '影响资产', '安全事件二级分类', DISPOSITION_EVENT_COLUMN],
    ['银狐病毒', '10.0.0.1', 'Telnet弱口令', '处置完成'],          # 段② +1
    ['银狐病毒', '10.0.0.1', 'Web弱口令', '待处置'],               # 分类命中、状态不命中
    ['银狐病毒', '10.0.0.2', '弱口令', '处置完成'],                # +2
    ['未知威胁', '10.0.0.2', 'SSH账号暴力破解', '处置完成'],        # 分类不含「弱口令」-> 不算
    ['未知威胁', '10.0.0.3', 'Telnet弱口令', '处置完成（误报）'],    # 状态带括号 -> 不算
    ['未知威胁', '10.0.0.3', '弱口令', ' 处置完成 '],              # +3（首尾空白要算）
    ['挖矿木马', '10.0.0.4', '弱口令'],                           # 状态缺 -> 不算
    ['挖矿木马', '10.0.0.4', '下载恶意文件', '处置完成'],           # 分类不含 -> 不算
    ['病毒', '10.0.0.5', '弱密码爆破', '处置完成'],                # 含「弱密码」不是「弱口令」-> 不算
    ['病毒', '10.0.0.6', '账号安全事件', '已遏制'],                # 分类不含 -> 不算
]

D16_EVENT_COUNT = 3

# G8 在这份事件表上的值（「处置状态」落在 {已遏制, 处置完成, 已忽略} 的行：7 行）——
# 与 D16 的段②（3）刻意不等，用来钉「两格读同一列、判据不同」。
D16_EVENT_DISPOSED_TOTAL = 7

D16_TOTAL = D16_WEAKPWD_COUNT + D16_EVENT_COUNT


def make_d16_tables(directory):
    """D16 专用 fixture（两份），见 D16_WEAKPWD_TABLE / D16_EVENT_TABLE 的说明。"""
    directory.mkdir(parents=True, exist_ok=True)
    return (write_sheet(directory / 'weakpwd-d16.xlsx', D16_WEAKPWD_TABLE),
            write_sheet(directory / 'event-d16.xlsx', D16_EVENT_TABLE))


def check_disposed_weakpwd(checker, bridge, workdir, weakpwd_path, event_path):
    """D16「已处置弱口令数量」跨两份表，所以这一段要同时钉住四件事：

      · 两段各自的判据对（精确相等 vs 子串包含、两个条件是与不是或）
      · 两段**真的是相加**，且只给一份表时另一段当 0（不是漏加、不是把缺的那份当缺数报错）
      · 缺列时不写**半个值**：弱密码表缺「处置状态」-> 整格不写（不是只落事件那段）
      · 同一份表上别的格不受牵连：弱密码表缺「处置状态」时 D11 照常落值；
        事件表缺「安全事件二级分类」时 G8 照常落值 —— 三格各认各的列

    与【7】那一份 core fixture 上的 D16（= CORE_DISPOSED_WEAKPWD_TOTAL）互为旁证：
    两份不同的表、两套行数，同一格的两个数不一样 ——「D16 是个写死的常数」在这里会露红。
    """
    checker.section('13】D16 已处置弱口令数量（弱密码表 + 事件表，两段相加）')

    edges = workdir / 'd16-edges'
    edges.mkdir(parents=True, exist_ok=True)

    def plan(weakpwd=None, event=None):
        request = {}
        if weakpwd:
            request['weakPwdPath'] = str(weakpwd)
        if event:
            request['eventPath'] = str(event)
        return call_bridge(bridge, 'plan', 'disposed', _b64(json.dumps(request)))

    def writes_of(result, cells):
        return {w['addr']: w['value'] for w in result['writes'] if w['addr'] in cells}

    def errors_of(result, cells):
        return {e['addr']: e['message'] for e in result['errors'] if e['addr'] in cells}

    d16 = EXPECTED_DISPOSED_WEAKPWD_CELLS

    # —— 正题：两段 4 + 3 = 7（判据见上面两份 fixture 的说明）
    result = plan(weakpwd_path, event_path)
    value = writes_of(result, d16)
    checker.check(value == {'D16': D16_TOTAL},
                  'D16 = 弱密码表「处置完成」行数 + 事件表「分类含『弱口令』且处置完成」行数'
                  '（两种括号写法、近义词「已处置」/「已遏制」、含「弱密码」的分类、'
                  '待处置、首尾空白的两种落法都要按上面的注释来数）',
                  json.dumps(value, ensure_ascii=False),
                  json.dumps({'D16': D16_TOTAL}, ensure_ascii=False))
    checker.check(not errors_of(result, d16), 'D16 不报错（两份表都有该有的列）',
                  json.dumps(errors_of(result, d16), ensure_ascii=False), '（无）')

    # 同一份事件表上 G8 也照常算：两格读同一列、判据不同，数就不该相等
    g8 = writes_of(result, EXPECTED_EVENT_DISPOSITION_CELLS)
    checker.check(g8 == {'G8': D16_EVENT_DISPOSED_TOTAL},
                  '同一份事件表上 G8 照常算（它与 D16 读同一列「处置状态」，判据不同）',
                  json.dumps(g8, ensure_ascii=False),
                  json.dumps({'G8': D16_EVENT_DISPOSED_TOTAL}, ensure_ascii=False))

    # —— 分段证据：只给一份表时，另一段是 0（不是"整格不写"、更不是报错）
    result = plan(weakpwd=weakpwd_path)
    checker.check(writes_of(result, d16) == {'D16': D16_WEAKPWD_COUNT},
                  '只给弱密码表 -> D16 = 第一段（事件那段当 0，不是报错、也不是不写值）',
                  json.dumps(writes_of(result, d16), ensure_ascii=False),
                  json.dumps({'D16': D16_WEAKPWD_COUNT}, ensure_ascii=False))
    checker.check(not errors_of(result, d16), '只给弱密码表 -> 不报错（缺的那份表 = 空表 = 0）',
                  json.dumps(errors_of(result, d16), ensure_ascii=False), '（无）')

    result = plan(event=event_path)
    checker.check(writes_of(result, d16) == {'D16': D16_EVENT_COUNT},
                  '只给事件表 -> D16 = 第二段',
                  json.dumps(writes_of(result, d16), ensure_ascii=False),
                  json.dumps({'D16': D16_EVENT_COUNT}, ensure_ascii=False))
    checker.check(not errors_of(result, d16), '只给事件表 -> 不报错',
                  json.dumps(errors_of(result, d16), ensure_ascii=False), '（无）')

    # —— 边界一：两份表都空（0 行）-> 写 0、不报错（0 是结论，不是缺数）
    empty_wp = write_sheet(edges / 'empty-weakpwd.xlsx',
                           [['风险资产', '弱点类型', WEAKPWD_DISPOSITION_COLUMN]])
    empty_ev = write_sheet(edges / 'empty-event.xlsx',
                           [[EVENT_LABEL, '影响资产', '安全事件二级分类', DISPOSITION_EVENT_COLUMN]])
    result = plan(empty_wp, empty_ev)
    checker.check(writes_of(result, d16) == {'D16': 0},
                  '两份表都是空表（0 行）-> D16 写 0（是结论，不是缺数）',
                  json.dumps(writes_of(result, d16), ensure_ascii=False),
                  json.dumps({'D16': 0}, ensure_ascii=False))
    checker.check(not errors_of(result, d16), '空表 -> D16 不报错',
                  json.dumps(errors_of(result, d16), ensure_ascii=False), '（无）')

    # —— 边界二：弱密码表缺「处置状态」列（平台改了列名）
    #    -> 整格不写（**不是**只落事件那一段）、报错点名缺哪一列；
    #       同一份表上 D11 照常落值 —— 它认的是「风险资产」，不看这一列。
    renamed_wp = write_sheet(edges / 'renamed-weakpwd.xlsx', [
        ['风险资产', '弱点类型', '状态'],
        ['10.0.0.1', 'ssh弱口令', '处置完成'],
    ])
    result = plan(renamed_wp, event_path)
    checker.check(not writes_of(result, d16),
                  '弱密码表缺「处置状态」列 -> D16 一个值都不写（不落"半格"）',
                  json.dumps(writes_of(result, d16), ensure_ascii=False), '（无）')
    errors = errors_of(result, d16)
    checker.check(sorted(errors) == ['D16'], '弱密码表缺列 -> 只有 D16 进错误列表',
                  ' '.join(sorted(errors)), 'D16')
    checker.check(all('找不到「处置状态」' in m and '弱密码表' in m for m in errors.values()),
                  '错误信息点明是**弱密码表**缺「处置状态」列（不是事件表那一份）',
                  json.dumps(errors.get('D16'), ensure_ascii=False))
    checker.check(writes_of(result, EXPECTED_WEAKPWD_CELLS) == {'D11': 0},
                  '同一份表上 D11 照常落值（它认的是「风险资产」，不看「处置状态」）',
                  json.dumps(writes_of(result, EXPECTED_WEAKPWD_CELLS), ensure_ascii=False),
                  json.dumps({'D11': 0}, ensure_ascii=False))

    # —— 边界三：事件表缺「安全事件二级分类」列
    #    -> D16 不写值 + 报错点名缺这一列；同一份表上 G8 照常落值（它只看「处置状态」）。
    renamed_ev = write_sheet(edges / 'renamed-event.xlsx', [
        [EVENT_LABEL, '影响资产', '事件名称', DISPOSITION_EVENT_COLUMN],
        ['银狐病毒', '10.0.0.1', 'e1', '处置完成'],
    ])
    result = plan(weakpwd_path, renamed_ev)
    checker.check(not writes_of(result, d16),
                  '事件表缺「安全事件二级分类」列 -> D16 一个值都不写',
                  json.dumps(writes_of(result, d16), ensure_ascii=False), '（无）')
    errors = errors_of(result, d16)
    checker.check(sorted(errors) == ['D16'], '事件表缺列 -> 只有 D16 进错误列表',
                  ' '.join(sorted(errors)), 'D16')
    checker.check(all('找不到「安全事件二级分类」' in m and '事件表' in m for m in errors.values()),
                  '错误信息点明是事件表缺「安全事件二级分类」列',
                  json.dumps(errors.get('D16'), ensure_ascii=False))
    checker.check(writes_of(result, EXPECTED_EVENT_DISPOSITION_CELLS) == {'G8': 1},
                  '同一份事件表上 G8 照常落值（它只看「处置状态」这一列）',
                  json.dumps(writes_of(result, EXPECTED_EVENT_DISPOSITION_CELLS), ensure_ascii=False),
                  json.dumps({'G8': 1}, ensure_ascii=False))

    # —— 边界四：事件表有「处置状态」但缺「安全事件二级分类」时，也不能把「处置完成」
    #    直接当成命中（那正是 G8 的口径）—— 上一条已断言 D16 不写值；
    #    这里再钉一次"两格同表不同数"：同一份完整 fixture 上 G8(7) != D16 的段②(3)。
    checker.check(D16_EVENT_DISPOSED_TOTAL != D16_EVENT_COUNT,
                  'G8 与 D16 第二段在同一份事件表上数出不同的数（判据不同，不是同一个函数的改名）',
                  f'G8={D16_EVENT_DISPOSED_TOTAL}, D16 第二段={D16_EVENT_COUNT}',
                  f'G8={D16_EVENT_DISPOSED_TOTAL}, D16 第二段={D16_EVENT_COUNT}')


# ---------------------------------------------------------------------------
# 【14】G7 威胁平均遏制时间（事件表命中行的遏制时长非空均值）
# ---------------------------------------------------------------------------
#
# 这一格读**事件表**上的两列：「GPT研判结论」（与 G5 同一句判据，那张表在告警表上）
# 与「遏制时长」。要平均的「遏制时长」**不是平台导出的列** —— 它是
# scripts/report_preprocess.py 按「事件遏制时间 − 专家研判时间」算出来、由
# preprocess_event_file 在**下载之后、解析之前**追加到下载件上的
# （用户口径 2026-10-12：取值层必须在预处理之后）。
#
# 所以本段必须按**生产顺序**造表：写 fixture -> 先跑一次 preprocess（原地改写它）->
# 再解析 -> 再算 G7。顺序反过来的话，G7 报的是「找不到『遏制时长』列」——
# 那验的就不是生产会发生的事。
#
# 从前这一格是「两份实现交叉钉住」（event.js 自己再算一遍、与预处理对撞）。那个做法随本次
# 口径一并删掉了：同一个口径现在全仓只有 report_preprocess.py 一处实现。本段保留的
# 「对撞」变成了**同一条链的两端对齐** —— 落盘后报告 sheet 上那一列在命中行上的值，
# 必须与 G7 进分母的那几个数逐个相同（证明取值层读的确实是预处理写的那一列，
# 而不是顺手从别处又拼了一份）。
#
# 十一行把每条边界铺满（行号 = fixture 下标 + 1）：
#   · 命中且两个时间都算得出 -> 预处理写出时长、进分母（文本 / datetime / 秒缺失三种形态各一行）
#   · 命中但遏制是半角 `-` / 研判是全角 `－` -> 预处理给那格留空，这一行退出分母、别的行照算
#   · 命中但研判是 `N/A`（认不出来的写法）-> 同样退出分母（与「空值」同后果，成因不同）
#   · 命中但遏制早于研判 -> 负差值，预处理判为**不合法、那一格留空**（用户口径 2026-10-12），
#     这一行退出分母（与「算不出时长」同样的后果，成因不同、计数也分开）
#   · 判据只认整格精确相等：「真实攻击成功」「真实攻击未成功（疑似）」两行都不算
#     （前缀 / 子串陷阱，与 G5 那条同源），首尾空白要算
#
# 命中 5 行（r2/r7/r9/r10/r11）、时长合计 36.75 分钟 -> 均值 **7.35**。这个数刻意不是整数、
# 也不是本仓任何一个计数：把三行空/认不出的行当 0 算进分母会变成 4.59375；
# 把负值那一行也算进分母（无论当 -30 还是当 0）都不相等 —— 当 -30 时正好是 1.125，
# 也就是本次口径改动前的旧期望值，谁把负值放回分母，这里立刻露红。
G7_VERDICT_HIT = '真实攻击未成功'      # 与 stats/metrics/alarm.js 的 GPT_VERDICT_HIT 同一句话
G7_VERDICT_COLUMN = 'GPT研判结论'

G7_EVENT_TABLE = [
    ['影响资产', '事件创建时间', '组件检出时间', '事件闭环时间', '事件遏制时间', '专家研判时间',
     G7_VERDICT_COLUMN],
    ['10.0.0.1', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 10:15:00', G7_VERDICT_HIT],            # r2  -> +15
    ['10.0.0.2', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
     '-', '2026-07-22 10:00:00', G7_VERDICT_HIT],                              # r3  -> 遏制是空值
    ['10.0.0.3', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
     '2026-07-22 10:10:00', '－', G7_VERDICT_HIT],                             # r4  -> 研判是空值
    ['10.0.0.4', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
     '2026-07-22 10:10:00', 'N/A', G7_VERDICT_HIT],                            # r5  -> 认不出来
    ['10.0.0.5', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
     '2026-07-22 09:30:00', '2026-07-22 10:00:00', G7_VERDICT_HIT],            # r6  -> -30（不合法，留空）
    ['10.0.0.6', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
     datetime.datetime(2026, 7, 22, 10, 20, 0), datetime.datetime(2026, 7, 22, 10, 15, 0),
     G7_VERDICT_HIT],                                                          # r7  -> +5（datetime）
    ['10.0.0.7', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
     '2026-07-23 10:00:00', '2026-07-22 10:00:00', '真实攻击成功'],             # r8  -> 不算（+1440）
    ['10.0.0.8', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
     '2026-07-22 10:07:30', '2026-07-22 10:00:00', f' {G7_VERDICT_HIT} '],      # r9  -> +7.5（首尾空白）
    ['10.0.0.9', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
     '2026-07-22 10:09', '2026-07-22 10:00:00', G7_VERDICT_HIT],               # r10 -> +9（秒可缺）
    ['10.0.0.10', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
     '2026-07-22 10:30:15', '2026-07-22 10:30:00', G7_VERDICT_HIT],            # r11 -> +0.25
    ['10.0.0.11', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
     '2026-07-22 20:00:00', '2026-07-22 10:00:00', f'{G7_VERDICT_HIT}（疑似）'],  # r12 -> 不算（+600）
]

# 进分母的五行的时长（r2 / r7 / r9 / r10 / r11）—— 逐值比，不只比均值：
# 均值相等的两批数完全可以不是同一批（这里五个值互不相同就是为了堵这件事）。
G7_INCLUDED_MINUTES = [15.0, 5.0, 7.5, 9.0, 0.25]
G7_EXPECTED_MEAN = 7.35


def make_g7_event_table(directory):
    """G7 专用 fixture（一份表），见 G7_EVENT_TABLE 的说明。

    这份表是**唯一一份**同时带了「GPT研判结论」与五个时间列的 fixture：先按生产的顺序
    过一遍预处理（把「遏制时长」追加出来），再喂进 ctx —— 取值层读到的就是那一版。
    """
    directory.mkdir(parents=True, exist_ok=True)
    return write_sheet(directory / 'event-g7.xlsx', G7_EVENT_TABLE)


def check_contained_minutes(checker, bridge, workdir, fixtures, event_path):
    """G7「威胁平均遏制时间」：命中行的遏制时长**非空均值**，单位分钟。

    生产顺序是「下载 -> 预处理（原地改写下载件）-> 解析 -> 取值」，本段照它造表：

      0. 先对 fixture 跑一次 `preprocess` 子命令 —— 它按「事件遏制时间 − 专家研判时间」
         把「遏制时长」写进那份文件。这是全仓**唯一**一处时长实现（report_preprocess.py）；
      1. **值层**：`plan event` 读的是**改写之后**的那份文件，G7 = 7.35
         （五行进分母、六行退出：三行算不出时长、一行负差值被预处理判为不合法、
         两行判据不命中）；
      2. **落盘**：这份值真的进了报告的「数据统计」sheet；
      3. **同链对齐**：搬表搬的也是那份改写后的文件，所以报告「事件表」sheet 上带着预处理
         写的那一列 —— 拿**那一列**在同样的命中行上算一遍均值，必须与 G7 逐值一致。
         这不是"两份实现对撞"（同一个口径只有一处实现），而是验取值层读的确实是预处理
         写的那份，没在旁边又拼一份。

    边界四条（每条 fixture 都**先预处理再 plan** —— 拿一份没预处理的事件表喂 ctx，
    G7 一定报「找不到『遏制时长』列」，那四条边界验的就全成了同一件事）：

      · 缺「事件遏制时间」列 -> 预处理标 `no_column`、不追加时长列；G7 因此不写值 +
        报错点名「遏制时长」列（那一列的缺席就是在说"两个时间源列凑不齐"，
        旧版 25 列导出就是现场）
      · 缺「GPT研判结论」列 -> 同样不写值 + 报错点名这一列（它先查，与 G5 同一个错误现场）
      · 有行但一行都不命中 / 命中的行都算不出时长 -> 写**空串**（不是 0），不报错
      · 空表（只有表头）-> 写空串、不报错
        —— 后两条是「没有可平均的样本」，与「0 分钟」在报告上必须是两个样子
    """
    checker.section('14】G7 威胁平均遏制时间（先预处理、再解析、再取值，同一列贯穿到落盘）')

    edges = workdir / 'g7-edges'
    edges.mkdir(parents=True, exist_ok=True)

    def plan(path):
        return call_bridge(bridge, 'plan', 'event', _b64(json.dumps({'path': path})))

    def g7_of(result):
        return {w['addr']: w['value'] for w in result['writes']
                if w['addr'] in EXPECTED_CONTAINED_CELLS}

    def g7_errors_of(result):
        return {e['addr']: e['message'] for e in result['errors']
                if e['addr'] in EXPECTED_CONTAINED_CELLS}

    def preprocessed(name, table):
        """照生产顺序造一份边缘 fixture：写表 -> 预处理（**原地改写**）-> 返回 (路径, 汇总)。

        路径要交回给 `plan` —— 解析必须发生在预处理之后，否则验的不是生产那条链。
        """
        path = write_sheet(edges / f'{name}.xlsx', table)
        return path, run_preprocess(bridge, fixtures['asset']['filePath'], path)

    # —— 第 0 步：预处理（生产里跑在解析之前）。幂等闸在这份 fixture 上是第一次跑，
    #    所以必须是真追加，不能是 already_present —— 否则下面的断言全是拿空列在比。
    early = run_preprocess(bridge, fixtures['asset']['filePath'], event_path)
    duration = early['duration']
    checker.check(duration['status'] == 'ok',
                  '预处理第 4 步在这份 fixture 上跑成（两个时间源列齐、四列真追加）',
                  json.dumps(duration, ensure_ascii=False))
    duration_cols = dict(zip((name for name, _, _ in DURATION_COLUMNS),
                             duration['addedColumns']))
    checker.check('遏制时长' in duration_cols,
                  '预处理追加的列里含「遏制时长」（列名与列序取自 report_preprocess.DURATION_COLUMNS）',
                  ' '.join(duration_cols), '遏制时长 ...')
    checker.check(early['event']['addedColumn'] == 'H',
                  '第 2 步的「内网外网资产」落在 H（五个时间列占 B-F、研判结论占 G）',
                  early['event']['addedColumn'], 'H')

    # —— 正题：解析的是**预处理之后**的那份文件
    result = plan(event_path)
    checker.check(not g7_errors_of(result), 'G7 不报错（「GPT研判结论」与「遏制时长」两列都在）',
                  json.dumps(g7_errors_of(result), ensure_ascii=False), '（无）')
    value = g7_of(result).get('G7')
    checker.check(isinstance(value, float) and abs(value - G7_EXPECTED_MEAN) < 1e-9,
                  f'G7 = 命中行的遏制时长均值（{len(G7_INCLUDED_MINUTES)} 行；空值 / 认不出的行 / '
                  '负差值那一格留空的行都只退出分母、别的行照算）',
                  json.dumps(value), json.dumps(G7_EXPECTED_MEAN))

    # —— 落盘 + 同链对齐（内存里对不算数）
    tables = dict(fixtures)
    tables['event'] = {'filePath': event_path}
    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-g7.xlsx'),
        'tables': tables,
        'eventPath': event_path,
        'preprocess': early,
        'beautify': False,
    })))

    ws = load_workbook(built['filePath'], data_only=False)[TEMPLATE_SHEET]
    landed = ws['G7'].value
    checker.check(isinstance(landed, float) and abs(landed - G7_EXPECTED_MEAN) < 1e-9,
                  'G7 落盘（「数据统计」sheet）', repr(landed), G7_EXPECTED_MEAN)

    event_ws = load_workbook(built['filePath'], data_only=False)[EVENT_SHEET]
    header_row = duration['headerRow']

    # 「GPT研判结论」不在预处理那五个源列里，所以按表头文字在报告 sheet 上现找它的列 ——
    # 不写死列号：事件表的列集是数据相关的（C4），写死的那一行明天就可能指到别的列上。
    verdict_col = None
    for col in range(1, event_ws.max_column + 1):
        text = event_ws.cell(row=header_row, column=col).value
        if str(text if text is not None else '').strip() == G7_VERDICT_COLUMN:
            verdict_col = col
    checker.check(verdict_col is not None,
                  '报告「事件表」sheet 的表头行上有「GPT研判结论」列',
                  f'表头行 {header_row}', f'含「{G7_VERDICT_COLUMN}」')

    duration_col = column_index_from_string(duration_cols['遏制时长'])
    cross_values = []
    for row in range(header_row + 1, event_ws.max_row + 1):
        raw = event_ws.cell(row=row, column=verdict_col).value if verdict_col else None
        if str(raw if raw is not None else '').strip() != G7_VERDICT_HIT:
            continue
        minutes = event_ws.cell(row=row, column=duration_col).value
        # 空值那几格是 None / ''（预处理的「留空」口径）—— 与 G7 一样不进分母
        if isinstance(minutes, (int, float)) and not isinstance(minutes, bool):
            cross_values.append(float(minutes))

    checker.check(sorted(cross_values) == sorted(G7_INCLUDED_MINUTES),
                  '预处理写进报告「事件表」sheet 的「遏制时长」列，在命中行上的值 = G7 认的'
                  f'那 {len(G7_INCLUDED_MINUTES)} 个数（逐值比：均值相等也可能是两批不同的数）',
                  json.dumps(sorted(cross_values)), json.dumps(sorted(G7_INCLUDED_MINUTES)))
    cross_mean = sum(cross_values) / len(cross_values) if cross_values else ''
    checker.check(isinstance(cross_mean, float) and abs(cross_mean - G7_EXPECTED_MEAN) < 1e-9,
                  '同一列、同一条链：报告 sheet 上那一列算出的均值 = G7 落的那个值'
                  '（取值层读的确实是预处理写的那一份）',
                  json.dumps(cross_mean), json.dumps(G7_EXPECTED_MEAN))

    # —— 边界一：缺「事件遏制时间」「专家研判时间」两列（= 旧版导出的现场）
    #    另外三个时间列照给：这样能同时钉住「只缺那一对时也不追加」——
    #    要是预处理把「少一对」当成「整表没时间列」，这里的 missing 就会多出三项。
    no_contained, early = preprocessed('no-contained', [
        ['影响资产', '事件创建时间', '组件检出时间', '事件闭环时间', G7_VERDICT_COLUMN],
        ['10.0.0.1', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
         G7_VERDICT_HIT],
    ])
    checker.check(early['duration']['status'] == 'no_column',
                  '缺时间源列 -> 预处理那一步不追加时长列（不抛错，只记 status）',
                  early['duration']['status'], 'no_column')
    checker.check(early['duration']['missing'] == ['事件遏制时间', '专家研判时间'],
                  '只报缺的那一对（另外三个时间列在表里，不该跟着被报成缺列）',
                  json.dumps(early['duration']['missing'], ensure_ascii=False),
                  json.dumps(['事件遏制时间', '专家研判时间'], ensure_ascii=False))
    checker.check(early['duration']['addedColumns'] == [],
                  '缺那一对时四列一列都不加',
                  json.dumps(early['duration']['addedColumns']), '[]')
    result = plan(no_contained)
    checker.check(not g7_of(result), '缺时间源列 -> G7 一个值都不写',
                  json.dumps(g7_of(result), ensure_ascii=False), '（无）')
    errors = g7_errors_of(result)
    checker.check(sorted(errors) == ['G7'], '缺时间源列 -> 只有 G7 进错误列表',
                  ' '.join(sorted(errors)), 'G7')
    checker.check(all('找不到「遏制时长」列' in m and '事件表' in m for m in errors.values()),
                  '错误信息点明是**事件表**缺「遏制时长」列 —— 报的是缺那一列，'
                  '意思是两个时间源列凑不齐（预处理没算出时长）；'
                  '不是「没有数据」，也不是旧文案里的「事件遏制时间」',
                  json.dumps(errors.get('G7'), ensure_ascii=False))

    # —— 边界二：缺「GPT研判结论」列（平台改了列名）
    no_verdict, _ = preprocessed('no-verdict', [
        ['影响资产', '事件遏制时间', '专家研判时间'],
        ['10.0.0.1', '2026-07-22 10:30:00', '2026-07-22 10:15:00'],
    ])
    result = plan(no_verdict)
    errors = g7_errors_of(result)
    checker.check(not g7_of(result) and sorted(errors) == ['G7'],
                  '缺「GPT研判结论」列 -> G7 不写值 + 进错误列表',
                  json.dumps(g7_of(result), ensure_ascii=False), '（无）')
    checker.check(all('找不到「GPT研判结论」列' in m for m in errors.values()),
                  '错误信息点明是缺「GPT研判结论」列（两列都缺时先报这一条 —— 选行是第一步）',
                  json.dumps(errors.get('G7'), ensure_ascii=False))

    # —— 边界三：有行、但没有一行命中 -> 空串（不是 0）、不报错
    #    五个时间源列照给（能算出时长、时长列真追加出来了），只是研判结论不命中 ——
    #    这样验的才是"命中判据"，而不是"时长列没算出来"。
    no_hit, early = preprocessed('no-hit', [
        ['影响资产', '事件创建时间', '组件检出时间', '事件闭环时间', '事件遏制时间', '专家研判时间',
         G7_VERDICT_COLUMN],
        ['10.0.0.1', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
         '2026-07-22 10:30:00', '2026-07-22 10:15:00', '真实攻击成功'],
    ])
    checker.check(early['duration']['status'] == 'ok',
                  '这一份的时间源列齐 -> 时长列真追加了（下面那条空串不是"缺列"造成的）',
                  early['duration']['status'], 'ok')
    result = plan(no_hit)
    checker.check(g7_of(result) == {'G7': ''} and not g7_errors_of(result),
                  '一行都不命中 -> 写空串（不是 0：0 分钟是一个真实可能的均值）、不报错',
                  json.dumps(g7_of(result), ensure_ascii=False), json.dumps({'G7': ''},
                                                                            ensure_ascii=False))

    # —— 边界四：命中但时长那一格是空值 / 占位符 -> 空串、不报错
    blank_times, early = preprocessed('blank-times', [
        ['影响资产', '事件创建时间', '组件检出时间', '事件闭环时间', '事件遏制时间', '专家研判时间',
         G7_VERDICT_COLUMN],
        ['10.0.0.1', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
         '-', '2026-07-22 10:15:00', G7_VERDICT_HIT],
        ['10.0.0.2', '2026-07-22 10:00:00', '2026-07-22 09:00:00', '2026-07-22 11:00:00',
         '－', '2026-07-22 10:15:00', G7_VERDICT_HIT],
    ])
    checker.check(early['duration']['status'] == 'ok'
                  and early['duration']['blankSkipped']['遏制时长'] == 2,
                  '两行的「事件遏制时间」是 `-` / 全角 `－` -> 时长那一格留空（不记 0、不报错）',
                  json.dumps(early['duration'].get('blankSkipped'), ensure_ascii=False),
                  json.dumps({'遏制时长': 2}))
    result = plan(blank_times)
    checker.check(g7_of(result) == {'G7': ''} and not g7_errors_of(result),
                  '命中的行都算不出时长 -> 写空串、不报错（缺数是另一回事，见上面两条）',
                  json.dumps(g7_of(result), ensure_ascii=False), json.dumps({'G7': ''},
                                                                            ensure_ascii=False))

    # —— 边界五：空表（只有表头）-> 空串、不报错（0 行是正常数据）
    empty, _ = preprocessed('empty-table', [
        ['影响资产', '事件创建时间', '组件检出时间', '事件闭环时间', '事件遏制时间', '专家研判时间',
         G7_VERDICT_COLUMN],
    ])
    result = plan(empty)
    checker.check(g7_of(result) == {'G7': ''} and not g7_errors_of(result),
                  '空表（0 行）-> 写空串、不报错',
                  json.dumps(g7_of(result), ensure_ascii=False), json.dumps({'G7': ''},
                                                                            ensure_ascii=False))

    checker.note('五行时长', json.dumps(G7_INCLUDED_MINUTES) + f' -> 均值 {G7_EXPECTED_MEAN}'
                 '（三行算不出时长、一行负差值不合法、两行判据不命中，都退出分母）')
    checker.note('时长那一列', '由预处理按「事件遏制时间 − 专家研判时间」写进下载件，'
                 '取值层只是它的读者（全仓唯一实现：scripts/report_preprocess.py）')


# ---------------------------------------------------------------------------
# 【15】G10 核心系统事件数量（全部核心系统的 IP 并集 × 事件表「影响资产」精确命中）
# ---------------------------------------------------------------------------
#
# 这一格跨两份表 + 一份 CLI 参数，所以 fixture 是「资产表 + 事件表 + --business-systems」：
#   · 资产表沿用 CORE_ASSET_TABLE（与【7】【11】同一批系统、同一批 IP —— 「同一台机器
#     属于两个系统」这条边界在三段验收里是同一个事实）；
#   · 事件表见 G10_EVENT_TABLE（表头是**真实列名**：平台导出的「影响资产」
#     「安全事件二级分类」「处置状态」）。
#
# 判据只有两句（用户口径）：「影响资产」落在**全部传入系统**的 IP **并集**里，加一。
# 表里的行就是围着这两句排的：
#   · 并集而不是逐系统：10.0.0.5 只属于第 3 个系统，仍要算；少传第 3 个系统时它那两行才不算
#   · 精确查找（归一后做集合成员判断）：`10.0.0.11` **不算**（多一个字符就是另一个 IP）；
#     `10.0.0.5(资产组名:管理IP范围)` 要算（括号后缀由 normalizeIp 剥掉）
#   · 不看二级分类 / 处置状态 / 定性：分类为空的行算、`SSH账号暴力破解`（含「账号」但
#     不含「账号安全」）算、处置状态是占位符 `-` 的行算
#   · 一家不属于任何核心业务系统的机器（10.0.0.4）上的行不算；不在资产表里的 IP
#     （10.0.0.9）上的行不算；「影响资产」为空的行不算
# 3 个系统 -> 6 行；只传前 2 个 -> 4 行；只传第 3 个 -> 2 行。
#
# ⚠️ 同一份表上，**带二级分类筛**的那种数法（D7:D9 的事件那一段、D11 的第二段）
# 只能数出 **0** 行（这份表的分类一个关键词都不含）—— 6 与 0 的差就是本格与那两处的分界，
# 把 G10 误实现成 "accountRiskEventCount(on union)" 在这里必然露红。
G10_EVENT_TABLE = [
    ['影响资产', '安全事件二级分类', DISPOSITION_EVENT_COLUMN],
    ['10.0.0.1', '下载恶意文件', '待处置'],                        # +1 分类不含关键词
    ['10.0.0.2', 'SSH账号暴力破解', '处置完成'],                   # +2 含「账号」不含「账号安全」
    ['10.0.0.2', '挖矿木马', '处置中'],                            # +3 同一台机器的第二行照样算
    ['10.0.0.3', '', '处置完成'],                                  # +4 分类为空也算
    ['10.0.0.5(资产组名:管理IP范围)', '病毒', '-'],                 # +5 括号后缀要归一；占位符状态也算
    ['10.0.0.5', '网页篡改', '已忽略'],                            # +6 同一台机器的第二行
    ['10.0.0.4', '账号安全事件', '处置完成'],                       # 不算：核心资产，但不属于任何系统
    ['10.0.0.11', '钓鱼邮件', '处置完成'],                          # 不算：精确查找（10.0.0.1 的前缀不算）
    ['', '恶意扫描', '处置完成'],                                   # 不算：影响资产为空
    ['10.0.0.9', 'Web攻击', '处置完成'],                            # 不算：IP 不在资产表里
]

# 三个系统的 IP 并集 {10.0.0.1, .2, .3, .5} 上命中 6 行（见上）。
G10_UNION_EVENT_COUNT = 6
# 只传前 2 个系统（OA / 财务）-> 并集少掉 10.0.0.5 -> 只剩 4 行。
G10_UNION_TWO_SYSTEMS_COUNT = 4
# 只传第 3 个系统（运维）-> 并集只有 10.0.0.5 -> 2 行（e5 的括号后缀那条 + e6）。
G10_UNION_ONE_SYSTEM_COUNT = 2


def make_g10_tables(directory):
    """G10 专用 fixture：资产表（沿用 CORE_ASSET_TABLE）+ 事件表（G10_EVENT_TABLE）。"""
    directory.mkdir(parents=True, exist_ok=True)
    return {
        'asset': write_sheet(directory / 'g10-asset.xlsx', CORE_ASSET_TABLE),
        'event': write_sheet(directory / 'g10-event.xlsx', G10_EVENT_TABLE),
    }


def check_core_system_events(checker, bridge, workdir, tables, fixtures):
    """G10「核心系统事件数量」：资产表圈 IP、事件表数行，两步各自的口径都要钉住。

    边界五条：
      · 事件表缺「影响资产」列 -> 只 G10 不写值 + 报缺这一列；同一份表上 G8 照常落值
        （它认的是「处置状态」）—— 一条"同一张表上各列各有各的键"的旁证
      · 事件表空表（0 行）-> 写 0、不报错
      · 资产表不给（= 空表）/ 这些系统名下一台资产都没有 -> IP 并集是空集 -> 写 0、不报错
      · 资产表有行却缺「所属业务」列 -> 不写值 + 报错（点明缺的是哪一列）
      · 一个系统都没传 -> 写 0、不报错（用户口径 2026-10-12：与 D6:D9 / G6/H6/I6 同一条；
        这一条特意带上两份总表，证明这个 0 是"没有系统"造成的、不是"缺表"造成的）

    与【7】那一份 core fixture 上的 G10（= CORE_EVENT_UNION_COUNT）互为旁证：
    两份数据、两个数，「G10 是个写死的常数」在这里会露红。
    """
    checker.section('15】G10 核心系统事件数量（IP 并集 × 「影响资产」精确命中）')

    edges = workdir / 'core-system-events'
    edges.mkdir(parents=True, exist_ok=True)

    def plan(asset, event, business_systems=CORE_SYSTEMS):
        paths = {}
        if asset:
            paths['asset'] = asset
        if event:
            paths['event'] = event
        return call_bridge(bridge, 'plan', 'core', _b64(json.dumps({
            'paths': paths,
            'businessSystems': business_systems,
        })))

    def g10_of(result):
        return {w['addr']: w['value'] for w in result['writes']
                if w['addr'] in EXPECTED_CORE_SYSTEM_EVENT_CELLS}

    def g10_errors_of(result):
        return {e['addr']: e['message'] for e in result['errors']
                if e['addr'] in EXPECTED_CORE_SYSTEM_EVENT_CELLS}

    # —— 正题：三个系统 -> 6 行（命中 / 不命中的行都在同一列里对照，见 G10_EVENT_TABLE）
    result = plan(tables['asset'], tables['event'])
    checker.check(g10_of(result) == {'G10': G10_UNION_EVENT_COUNT},
                  f'G10 = 「影响资产」落在三个系统 IP 并集里的行数（命中 {G10_UNION_EVENT_COUNT} 行：'
                  '不看分类 / 处置状态 / 定性，按行计数不去重；'
                  '不在并集里的 IP、前缀更长的 IP、空的「影响资产」都不算）',
                  json.dumps(g10_of(result), ensure_ascii=False),
                  json.dumps({'G10': G10_UNION_EVENT_COUNT}, ensure_ascii=False))
    checker.check(not g10_errors_of(result), 'G10 不缺数',
                  json.dumps(g10_errors_of(result), ensure_ascii=False), '（无）')
    checker.note('与「按分类筛」的分界',
                 '同一份表上 D7:D9 的事件那一段 / D11 用的那种数法（二级分类含'
                 '「弱口令 / 弱密码 / 账号安全」）在这一列上只能数出 0 行 —— '
                 f'本格是 {G10_UNION_EVENT_COUNT}：本格不看分类，那一句口径是本格独有的')

    # —— 并集随传入的系统收缩：少传第 3 个系统，只属于它的那两行就不算了
    two = plan(tables['asset'], tables['event'], CORE_SYSTEMS[:2])
    checker.check(g10_of(two) == {'G10': G10_UNION_TWO_SYSTEMS_COUNT},
                  f'只传前 2 个系统 -> 并集少了 {CORE_SYSTEMS[2]} 那台机器 -> '
                  f'{G10_UNION_TWO_SYSTEMS_COUNT} 行（并集真的是"传进来的那些系统"的并集）',
                  json.dumps(g10_of(two), ensure_ascii=False),
                  json.dumps({'G10': G10_UNION_TWO_SYSTEMS_COUNT}, ensure_ascii=False))
    one = plan(tables['asset'], tables['event'], CORE_SYSTEMS[2:3])
    checker.check(g10_of(one) == {'G10': G10_UNION_ONE_SYSTEM_COUNT},
                  f'只传第 3 个系统（{CORE_SYSTEMS[2]}）-> 只数它名下那 2 行',
                  json.dumps(g10_of(one), ensure_ascii=False),
                  json.dumps({'G10': G10_UNION_ONE_SYSTEM_COUNT}, ensure_ascii=False))

    # —— 落盘：内存里对不算数（与【6】【7】同一套路）
    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-g10.xlsx'),
        'tables': fixtures,
        'statsPaths': {'asset': tables['asset'], 'event': tables['event']},
        'businessSystems': CORE_SYSTEMS,
        'beautify': False,
    })))
    ws = load_workbook(built['filePath'], data_only=False)[TEMPLATE_SHEET]
    actual = ws['G10'].value
    checker.check(actual == G10_UNION_EVENT_COUNT,
                  'G10 落盘（「数据统计」sheet 上那一格 = 计划里的那个数）',
                  repr(actual), G10_UNION_EVENT_COUNT)

    # —— 边界一：事件表缺「影响资产」列（平台改了列名）-> 只 G10 不写值 + 报缺这一列；
    #    G8 认的是同一张表的另一列，照常落值 —— 两列各有各的键。
    renamed = write_sheet(edges / 'renamed.xlsx', [
        ['受影响资产', '安全事件二级分类', DISPOSITION_EVENT_COLUMN],
        ['10.0.0.1', '下载恶意文件', '处置完成'],
    ])
    result = plan(tables['asset'], renamed)
    checker.check(not g10_of(result), '缺「影响资产」列 -> G10 一个值都不写',
                  json.dumps(g10_of(result), ensure_ascii=False), '（无）')
    errors = g10_errors_of(result)
    checker.check(sorted(errors) == ['G10'], '缺「影响资产」列 -> 只有 G10 进错误列表',
                  ' '.join(sorted(errors)), 'G10')
    checker.check(all('找不到「影响资产」' in m for m in errors.values()),
                  '错误信息点明是缺「影响资产」列（不是「没有数据」）',
                  json.dumps(errors.get('G10'), ensure_ascii=False))
    checker.check('G8' in [w['addr'] for w in result['writes']],
                  '缺「影响资产」列 -> 同一份表上 G8 照常落值（它认「处置状态」，不认这一列）',
                  '是' if 'G8' in [w['addr'] for w in result['writes']] else '否')

    # —— 边界二：事件表空表（0 行）-> 写 0、不报错（0 是结论，不是缺数）
    empty_event = write_sheet(edges / 'empty-event.xlsx', [
        ['影响资产', '安全事件二级分类', DISPOSITION_EVENT_COLUMN],
    ])
    result = plan(tables['asset'], empty_event)
    checker.check(g10_of(result) == {'G10': 0} and not g10_errors_of(result),
                  '事件表空表（0 行）-> 写 0、不报错',
                  json.dumps(g10_of(result), ensure_ascii=False),
                  json.dumps({'G10': 0}, ensure_ascii=False))

    # —— 边界三：资产表不给（= 空表）-> 并集是空集 -> 写 0、不报错。
    #    与「事件表里有行却一条都不命中」同一条落法：IP 集合空就没有可数的行。
    result = plan(None, tables['event'])
    checker.check(g10_of(result) == {'G10': 0} and not g10_errors_of(result),
                  '资产表为空（IP 并集是空集）-> 写 0、不报错',
                  json.dumps(g10_of(result), ensure_ascii=False),
                  json.dumps({'G10': 0}, ensure_ascii=False))

    # —— 边界四：资产表有行、却缺「所属业务」列（平台改了列名）-> 不写值 + 报错。
    #    这一条与"资产表为空 -> 0"是分界：列名对不上不是"这些机器没有业务归属"。
    no_business = write_sheet(edges / 'no-business.xlsx', [
        ['IP地址', '互联网暴露', '资产名称'],
        ['10.0.0.1', '暴露', 'a'],
    ])
    result = plan(no_business, tables['event'])
    checker.check(not g10_of(result), '资产表缺「所属业务」列 -> G10 一个值都不写',
                  json.dumps(g10_of(result), ensure_ascii=False), '（无）')
    errors = g10_errors_of(result)
    checker.check(sorted(errors) == ['G10'], '资产表缺「所属业务」列 -> 只有 G10 进错误列表',
                  ' '.join(sorted(errors)), 'G10')
    checker.check(all('找不到「所属业务」' in m and '资产表' in m for m in errors.values()),
                  '错误信息点明是**资产表**缺「所属业务」列（不是"没有资产"）',
                  json.dumps(errors.get('G10'), ensure_ascii=False))

    # —— 边界五：一个系统都没传 -> 写 0、不报错（用户口径 2026-10-12）。
    #    两份总表都在（IP 集合本来算得出来），所以这个 0 是"没有系统"造成的，
    #    不是"缺表"造成的 —— 与上面「资产表为空 -> 0」那条**同一个落法、不同的理由**。
    #    同一次跑里 D6:D9 与 G6/H6/I6 也一起写 0（它们与 G10 同一条口径），
    #    只有 D3/D4/D5 进 errors —— 那三格写的是系统名本身，见【7】。
    result = plan(tables['asset'], tables['event'], [])
    checker.check(g10_of(result) == {'G10': 0} and not g10_errors_of(result),
                  '没传 --business-systems -> G10 写 0、不报错（同 D6:D9 / G6/H6/I6）',
                  json.dumps(g10_of(result), ensure_ascii=False),
                  json.dumps({'G10': 0}, ensure_ascii=False))
    zeroed = {w['addr']: w['value'] for w in result['writes']
              if w['addr'] in EXPECTED_NO_SYSTEM_ZERO_CELLS}
    checker.check(zeroed == {addr: 0 for addr in EXPECTED_NO_SYSTEM_ZERO_CELLS},
                  '同一次跑里「一个系统都没传」的那 8 格都写 0（D6:D9 / G6/H6/I6 / G10）',
                  json.dumps(zeroed, ensure_ascii=False),
                  json.dumps({addr: 0 for addr in EXPECTED_NO_SYSTEM_ZERO_CELLS},
                             ensure_ascii=False))
    # 本段的 plan 只接了资产表与事件表，别的域（告警那几格、C135:I137 那些）会因为
    # 没接表而各报各的缺列 —— 那不是本段要证明的事，所以这里只看**核心系统这一域**的 11 格。
    domain = EXPECTED_CORE_SYSTEM_CELLS + EXPECTED_CORE_SYSTEM_EVENT_CELLS \
        + [a for a in EXPECTED_NO_SYSTEM_ZERO_CELLS if a in ('G6', 'H6', 'I6')]
    domain_errors = sorted(e['addr'] for e in result['errors'] if e['addr'] in domain)
    checker.check(domain_errors == EXPECTED_NO_SYSTEM_ERRORS,
                  '同一次跑里核心系统这一域只有 D3/D4/D5 进 errors'
                  '（那三格写的是系统名本身，没有名字就写不出来）',
                  ' '.join(domain_errors) or '（无）', ' '.join(sorted(EXPECTED_NO_SYSTEM_ERRORS)))


# ---------------------------------------------------------------------------
# 【16】G9 事件平均响应时长（G8 那批行 × 「推送状态」=「已推送」× 响应时长非空均值）
# ---------------------------------------------------------------------------
#
# 这一格读**同一份事件表**的两列（「处置状态」+「推送状态」）外加一列预处理追加的
# 「响应时长」—— 三列各有各的纪律，所以 fixture 必须三列都给，且必须**先跑预处理**
# （与【14】同一条：那份下载件没预处理过的话，表头里压根没有「响应时长」这一列）。
#
# 判据两句（用户口径）：
#   1. 在 G8 选出的那批行之上（「处置状态」整格精确等于 已遏制 / 处置完成 / 已忽略）
#   2. 「推送状态」整格精确等于「已推送」
# 然后取这些行的「响应时长」（= 专家研判时间 − 组件检出时间，分钟、2 位小数）的非空均值。
#
# 行是围着"两道筛各自都要真的生效"排的（行号 = fixture 下标 + 1）：
#   · r2/r3/r4/r13 两道筛都命中 -> 进分母（文本 / datetime 两种时间格都认）
#   · r4 推送状态是 ` 已推送 `（首尾空白）-> 要算；r10 是 `已推送（补推）`-> 不算
#   · r5 两道筛都命中、但研判早于检出 -> 负差值，预处理判为**不合法、那一格留空**
#     （用户口径 2026-10-12）-> 退出分母（与「时长算不出来」后果相同、成因不同）
#   · r6/r7 推送状态命中、但处置状态是 待处置 / 处置中 -> **不算**（本格是"已处置事件里
#     已推送的那部分"，不是全表已推送 —— 这两行就是与"只看推送状态"的分界）
#   · r8/r9 处置状态命中、但推送状态是 未推送 / 空 -> 不算（第二道筛真在起作用）
#   · r11 处置状态带括号 -> 不算（G8 那条选行判据的精确匹配）
#   · r12 两道筛都命中、但「组件检出时间」是 `-` -> 预处理给时长留空 -> 退出分母、别的行照算
#
# 命中 4 行、时长合计 195.5 分钟 -> 均值 **48.875**。这个数与同表上 G8 的行数（9）
# 刻意不等：把 G9 误实现成"数 G8 那批行"或"数所有已推送的行"都会在这里露红。
# 把 r5 那一行的负值放回分母（当 -60 算）会得到 27.1 —— 那正是本次口径改动前的旧期望值，
# 谁把负值当合法值，这里立刻露红。
G9_DISPOSITION_COLUMN = '处置状态'
G9_PUSH_COLUMN = '推送状态'
G9_PUSHED = '已推送'
G9_RESPONSE_COLUMN = '响应时长'

# 五个时间源列必须**都在**：预处理凑不齐这五列就一个时长列都不追加
# （见 report_preprocess.py 的 append_duration_columns）—— 那时验的就不是本格了。
_G9_TIME_HEADERS = ['事件创建时间', '组件检出时间', '事件闭环时间', '事件遏制时间', '专家研判时间']

G9_EVENT_TABLE = [
    ['影响资产'] + _G9_TIME_HEADERS + [G9_DISPOSITION_COLUMN, G9_PUSH_COLUMN],
    # 影响资产, 事件创建, 组件检出, 事件闭环, 事件遏制, 专家研判, 处置状态, 推送状态
    ['10.0.0.1', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 10:15:00', '已遏制', G9_PUSHED],          # r2  -> +75
    ['10.0.0.2', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 09:33:00', '处置完成', G9_PUSHED],        # r3  -> +33
    ['10.0.0.3', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 09:07:30', '已忽略', f' {G9_PUSHED} '],    # r4  -> +7.5（空白）
    ['10.0.0.4', '2026-07-22 08:00:00', '2026-07-22 10:00:00', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 09:00:00', '处置完成', G9_PUSHED],        # r5  -> -60（不合法，留空）
    ['10.0.0.5', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 10:00:00', '待处置', G9_PUSHED],          # r6  -> 不算
    ['10.0.0.6', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 10:00:00', '处置中', G9_PUSHED],          # r7  -> 不算
    ['10.0.0.7', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 11:00:00', '已遏制', '未推送'],            # r8  -> 不算
    ['10.0.0.8', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 11:00:00', '处置完成', ''],               # r9  -> 不算
    ['10.0.0.9', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 11:00:00', '已遏制', f'{G9_PUSHED}（补推）'],  # r10 -> 不算
    ['10.0.0.10', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 11:00:00', '已遏制（已缓解）', G9_PUSHED],  # r11 -> 不算
    ['10.0.0.11', '2026-07-22 08:00:00', '-', '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', '2026-07-22 11:00:00', '已忽略', G9_PUSHED],          # r12 -> 时长留空
    ['10.0.0.12', '2026-07-22 08:00:00',
     datetime.datetime(2026, 7, 22, 9, 0, 0), '2026-07-22 12:00:00',
     '2026-07-22 10:30:00', datetime.datetime(2026, 7, 22, 10, 20, 0),
     '已忽略', G9_PUSHED],                                                        # r13 -> +80（datetime）
]

# 进分母的四行的响应时长（r2 / r3 / r4 / r13）—— 逐值比，不只比均值：
# 均值相等的两批数完全可以不是同一批（这里四个值互不相同就是为了堵这件事）。
G9_INCLUDED_MINUTES = [75.0, 33.0, 7.5, 80.0]
G9_EXPECTED_MEAN = 48.875

# 同一份表上 G8 的值（「处置状态」命中的行：r2/r3/r4/r5/r8/r9/r10/r12/r13）——
# 与 G9 的命中行数（5）刻意不等，钉的是"G9 不是 G8"。
G9_TABLE_DISPOSED_COUNT = 9


def make_g9_event_table(directory):
    """G9 专用 fixture（一份表），见 G9_EVENT_TABLE 的说明。

    与 G7 那份同款：把五个时间源列都带上，先按生产的顺序过一遍预处理
    （把「响应时长」追加出来），再喂进 ctx —— 取值层读到的就是那一版。
    """
    directory.mkdir(parents=True, exist_ok=True)
    return write_sheet(directory / 'event-g9.xlsx', G9_EVENT_TABLE)


def check_response_minutes(checker, bridge, workdir, fixtures, event_path):
    """G9「事件平均响应时长」：G8 那批行里「推送状态」=「已推送」的，取响应时长非空均值。

    生产顺序同样是「下载 -> 预处理（原地改写下载件）-> 解析 -> 取值」，本段照它造表：

      0. 先对 fixture 跑一次 `preprocess` —— 它按「专家研判时间 − 组件检出时间」
         把「响应时长」写进那份文件（与 G7 的「遏制时长」同一次预处理的产物）；
      1. **值层**：`plan event` 读的是**改写之后**的那份文件，G9 = 48.875
         （四行进分母、八行退出：两行处置状态不命中、三行推送状态不命中
          （未推送 / 空 / 带后缀）、一行处置状态带括号、一行时长算不出、
          一行负差值被预处理判为不合法）；
      2. **落盘**：这份值真的进了报告的「数据统计」sheet；
      3. **同链对齐**：报告「事件表」sheet 上那一列在命中行上的值，必须与 G9 进分母的
         那四个数逐个相同 —— 验取值层读的确实是预处理写的那一份。

    边界五条（每条 fixture 都**先预处理再 plan**）：

      · 缺「推送状态」列 -> 不写值 + 报错点名这一列（本格独有的那道筛）
      · 缺「处置状态」列 -> 不写值 + 报错点名这一列（**先查它** —— 选行是第一步，
        与 G8 同一个错误现场）
      · 缺「响应时长」列（两个时间源列凑不齐、预处理那一步没算出来）-> 不写值 +
        报错点名这一列
      · 有行但一行都不命中 / 命中的行时长全空 -> 写 **0**（与 G7 写空串**不是**同一条）
      · 空表（只有表头）-> 写 0、不报错
    """
    checker.section('16】G9 事件平均响应时长（G8 那批行 × 「推送状态」=「已推送」，先预处理再取值）')

    edges = workdir / 'g9-edges'
    edges.mkdir(parents=True, exist_ok=True)

    def plan(path):
        return call_bridge(bridge, 'plan', 'event', _b64(json.dumps({'path': path})))

    def g9_of(result):
        return {w['addr']: w['value'] for w in result['writes']
                if w['addr'] in EXPECTED_RESPONSE_CELLS}

    def g9_errors_of(result):
        return {e['addr']: e['message'] for e in result['errors']
                if e['addr'] in EXPECTED_RESPONSE_CELLS}

    def g8_of(result):
        return {w['addr']: w['value'] for w in result['writes']
                if w['addr'] in EXPECTED_EVENT_DISPOSITION_CELLS}

    def preprocessed(name, table):
        """照生产顺序造一份边缘 fixture：写表 -> 预处理（**原地改写**）-> 返回 (路径, 汇总)。"""
        path = write_sheet(edges / f'{name}.xlsx', table)
        return path, run_preprocess(bridge, fixtures['asset']['filePath'], path)

    # —— 第 0 步：预处理（生产里跑在解析之前）。这一份的五个时间源列齐，必须是真追加。
    early = run_preprocess(bridge, fixtures['asset']['filePath'], event_path)
    duration = early['duration']
    checker.check(duration['status'] == 'ok',
                  '预处理把四个时长列真追加进这份 fixture（五个时间源列都在）',
                  json.dumps(duration, ensure_ascii=False))
    duration_cols = dict(zip((name for name, _, _ in DURATION_COLUMNS),
                             duration['addedColumns']))
    checker.check('响应时长' in duration_cols,
                  '预处理追加的列里含「响应时长」（列名与列序取自 report_preprocess.DURATION_COLUMNS）',
                  ' '.join(duration_cols), '响应时长 ...')

    # —— 正题：解析的是**预处理之后**的那份文件
    result = plan(event_path)
    checker.check(not g9_errors_of(result),
                  'G9 不报错（「处置状态」「推送状态」「响应时长」三列都在）',
                  json.dumps(g9_errors_of(result), ensure_ascii=False), '（无）')
    value = g9_of(result).get('G9')
    checker.check(isinstance(value, float) and abs(value - G9_EXPECTED_MEAN) < 1e-9,
                  f'G9 = G8 那批行里「已推送」的 {len(G9_INCLUDED_MINUTES)} 行的响应时长均值'
                  '（推送状态不是「已推送」的行、处置状态不命中的行、时长算不出的行都退出分母）',
                  json.dumps(value), json.dumps(G9_EXPECTED_MEAN))
    # 同一份表上 G8 的数与 G9 的命中行数不同 —— 钉住「G9 不是 G8」
    checker.check(g8_of(result) == {'G8': G9_TABLE_DISPOSED_COUNT},
                  '同一份表上 G8 照常算，且它的数（处置状态命中的行数）与 G9 的命中行数不同',
                  json.dumps(g8_of(result), ensure_ascii=False),
                  json.dumps({'G8': G9_TABLE_DISPOSED_COUNT}, ensure_ascii=False))

    # —— 落盘 + 同链对齐（内存里对不算数）
    tables = dict(fixtures)
    tables['event'] = {'filePath': event_path}
    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-g9.xlsx'),
        'tables': tables,
        'eventPath': event_path,
        'preprocess': early,
        'beautify': False,
    })))

    ws = load_workbook(built['filePath'], data_only=False)[TEMPLATE_SHEET]
    landed = ws['G9'].value
    checker.check(isinstance(landed, float) and abs(landed - G9_EXPECTED_MEAN) < 1e-9,
                  'G9 落盘（「数据统计」sheet）', repr(landed), G9_EXPECTED_MEAN)

    event_ws = load_workbook(built['filePath'], data_only=False)[EVENT_SHEET]
    header_row = duration['headerRow']

    # 「处置状态」「推送状态」不在预处理那五个源列里，所以按表头文字在报告 sheet 上现找 ——
    # 不写死列号：事件表的列集是数据相关的（C4）。
    def find_column(name):
        for col in range(1, event_ws.max_column + 1):
            text = event_ws.cell(row=header_row, column=col).value
            if str(text if text is not None else '').strip() == name:
                return col
        return None

    disposition_col = find_column(G9_DISPOSITION_COLUMN)
    push_col = find_column(G9_PUSH_COLUMN)
    checker.check(disposition_col is not None and push_col is not None,
                  '报告「事件表」sheet 的表头行上有「处置状态」与「推送状态」两列',
                  f'表头行 {header_row}',
                  f'含「{G9_DISPOSITION_COLUMN}」「{G9_PUSH_COLUMN}」')

    response_col = column_index_from_string(duration_cols['响应时长'])
    disposed_statuses = ('已遏制', '处置完成', '已忽略')
    cross_values = []
    for row in range(header_row + 1, event_ws.max_row + 1):
        status = str(event_ws.cell(row=row, column=disposition_col).value or '').strip()
        push = str(event_ws.cell(row=row, column=push_col).value or '').strip()
        if status not in disposed_statuses or push != G9_PUSHED:
            continue
        minutes = event_ws.cell(row=row, column=response_col).value
        # 空值那几格是 None / ''（预处理的「留空」口径）—— 与 G9 一样不进分母
        if isinstance(minutes, (int, float)) and not isinstance(minutes, bool):
            cross_values.append(float(minutes))

    checker.check(sorted(cross_values) == sorted(G9_INCLUDED_MINUTES),
                  '预处理写进报告「事件表」sheet 的「响应时长」列，在命中行上的值 = G9 认的'
                  '那五个数（逐值比：均值相等也可能是两批不同的数）',
                  json.dumps(sorted(cross_values)), json.dumps(sorted(G9_INCLUDED_MINUTES)))
    cross_mean = sum(cross_values) / len(cross_values) if cross_values else ''
    checker.check(isinstance(cross_mean, float) and abs(cross_mean - G9_EXPECTED_MEAN) < 1e-9,
                  '同一列、同一条链：报告 sheet 上那一列算出的均值 = G9 落的那个值'
                  '（取值层读的确实是预处理写的那一份）',
                  json.dumps(cross_mean), json.dumps(G9_EXPECTED_MEAN))

    # —— 边界一：缺「推送状态」列（平台改了列名）-> 不写值 + 报错点名这一列。
    #    其余三列都在（处置状态、响应时长的源列都齐），所以这个错只可能来自这一列。
    no_push, _ = preprocessed('no-push', [
        ['影响资产'] + _G9_TIME_HEADERS + [G9_DISPOSITION_COLUMN],
        ['10.0.0.1', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
         '2026-07-22 10:30:00', '2026-07-22 10:15:00', '已遏制'],
    ])
    result = plan(no_push)
    errors = g9_errors_of(result)
    checker.check(not g9_of(result) and sorted(errors) == ['G9'],
                  '缺「推送状态」列 -> G9 不写值 + 进错误列表',
                  json.dumps(g9_of(result), ensure_ascii=False), '（无）')
    checker.check(all('找不到「推送状态」列' in m for m in errors.values()),
                  '错误信息点明是缺「推送状态」列（不是「没有数据」）',
                  json.dumps(errors.get('G9'), ensure_ascii=False))

    # —— 边界二：缺「处置状态」列 -> 不写值 + 报错点名**这一列**（先查它：选行是第一步）。
    #    这一份的推送状态在，所以报的不是它 —— 顺序由这两条一起钉住。
    no_disposition, _ = preprocessed('no-disposition', [
        ['影响资产'] + _G9_TIME_HEADERS + [G9_PUSH_COLUMN],
        ['10.0.0.1', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
         '2026-07-22 10:30:00', '2026-07-22 10:15:00', G9_PUSHED],
    ])
    result = plan(no_disposition)
    errors = g9_errors_of(result)
    checker.check(not g9_of(result) and sorted(errors) == ['G9'],
                  '缺「处置状态」列 -> G9 不写值 + 进错误列表',
                  json.dumps(g9_of(result), ensure_ascii=False), '（无）')
    checker.check(all('找不到「处置状态」列' in m for m in errors.values()),
                  '错误信息点明是缺「处置状态」列（两列都缺时先报这一条 —— 选行是第一步）',
                  json.dumps(errors.get('G9'), ensure_ascii=False))

    # —— 边界三：缺「响应时长」列 —— 两个时间源列（组件检出时间 / 专家研判时间）凑不齐、
    #    预处理那一步没算出时长。这一份的前两列都在（能报出是缺时长列，不是缺状态列）。
    no_response, early_no = preprocessed('no-response', [
        ['影响资产', '事件创建时间', '事件闭环时间', '事件遏制时间',
         G9_DISPOSITION_COLUMN, G9_PUSH_COLUMN],
        ['10.0.0.1', '2026-07-22 08:00:00', '2026-07-22 12:00:00', '2026-07-22 10:30:00',
         '已遏制', G9_PUSHED],
    ])
    checker.check(early_no['duration']['status'] == 'no_column',
                  '缺「组件检出时间」「专家研判时间」-> 预处理那一步不追加时长列（不抛错）',
                  early_no['duration']['status'], 'no_column')
    result = plan(no_response)
    errors = g9_errors_of(result)
    checker.check(not g9_of(result) and sorted(errors) == ['G9'],
                  '缺预处理的「响应时长」列 -> G9 不写值 + 进错误列表',
                  json.dumps(g9_of(result), ensure_ascii=False), '（无）')
    checker.check(all('找不到「响应时长」列' in m and '事件表' in m for m in errors.values()),
                  '错误信息点明是**事件表**缺「响应时长」列 —— 意思是两个时间源列凑不齐'
                  '（预处理没算出时长），不是「没有数据」',
                  json.dumps(errors.get('G9'), ensure_ascii=False))

    # —— 边界四：有行、但没有一行命中 -> 写 **0**（不是空串！与 G7 那条刻意相反）、不报错。
    #    三列都给全（能算出时长、时长列真追加出来了），只是推送状态一个都不命中 ——
    #    这样验的才是"两道筛"，而不是"时长列没算出来"。
    no_hit, early_hit = preprocessed('no-hit', [
        ['影响资产'] + _G9_TIME_HEADERS + [G9_DISPOSITION_COLUMN, G9_PUSH_COLUMN],
        ['10.0.0.1', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
         '2026-07-22 10:30:00', '2026-07-22 10:15:00', '已遏制', '未推送'],
        ['10.0.0.2', '2026-07-22 08:00:00', '2026-07-22 09:00:00', '2026-07-22 12:00:00',
         '2026-07-22 10:30:00', '2026-07-22 10:15:00', '待处置', G9_PUSHED],
    ])
    checker.check(early_hit['duration']['status'] == 'ok',
                  '这一份的时间源列齐 -> 时长列真追加了（下面那个 0 不是"缺列"造成的）',
                  early_hit['duration']['status'], 'ok')
    result = plan(no_hit)
    checker.check(g9_of(result) == {'G9': 0} and not g9_errors_of(result),
                  '一行都不命中（推送状态全不是「已推送」/ 处置状态不命中）-> 写 **0**、不报错'
                  '（用户口径"没有就写0"；⚠️ 与 G7 写空串不是同一条）',
                  json.dumps(g9_of(result), ensure_ascii=False),
                  json.dumps({'G9': 0}, ensure_ascii=False))

    # —— 边界五：命中但时长那一格是空值 / 占位符 -> 同样写 0、不报错
    blank_times, early_blank = preprocessed('blank-times', [
        ['影响资产'] + _G9_TIME_HEADERS + [G9_DISPOSITION_COLUMN, G9_PUSH_COLUMN],
        ['10.0.0.1', '2026-07-22 08:00:00', '-', '2026-07-22 12:00:00',
         '2026-07-22 10:30:00', '2026-07-22 10:15:00', '已遏制', G9_PUSHED],
        ['10.0.0.2', '2026-07-22 08:00:00', '－', '2026-07-22 12:00:00',
         '2026-07-22 10:30:00', '2026-07-22 10:15:00', '处置完成', G9_PUSHED],
    ])
    checker.check(early_blank['duration']['status'] == 'ok'
                  and early_blank['duration']['blankSkipped']['响应时长'] == 2,
                  '两行的「组件检出时间」是 `-` / 全角 `－` -> 响应时长那一格留空（不记 0、不报错）',
                  json.dumps(early_blank['duration'].get('blankSkipped'), ensure_ascii=False),
                  json.dumps({'响应时长': 2}))
    result = plan(blank_times)
    checker.check(g9_of(result) == {'G9': 0} and not g9_errors_of(result),
                  '命中的行响应时长全为空 -> 写 0、不报错（缺数是另一回事，见上面三条）',
                  json.dumps(g9_of(result), ensure_ascii=False),
                  json.dumps({'G9': 0}, ensure_ascii=False))

    # —— 边界六：空表（只有表头）-> 写 0、不报错（0 行是正常数据）
    empty, _ = preprocessed('empty-table', [
        ['影响资产'] + _G9_TIME_HEADERS + [G9_DISPOSITION_COLUMN, G9_PUSH_COLUMN],
    ])
    result = plan(empty)
    checker.check(g9_of(result) == {'G9': 0} and not g9_errors_of(result),
                  '空表（0 行）-> 写 0、不报错',
                  json.dumps(g9_of(result), ensure_ascii=False),
                  json.dumps({'G9': 0}, ensure_ascii=False))

    checker.note('四行时长', json.dumps(G9_INCLUDED_MINUTES) + f' -> 均值 {G9_EXPECTED_MEAN}'
                 '（八行退出：两行处置状态不命中、三行推送状态不命中（未推送 / 空 / 带后缀）、'
                 '一行处置状态带括号、一行时长算不出、一行负差值不合法）')
    checker.note('两道筛', '处置状态那一批复用 G8 的 disposedEventRows（H4：一条判据不写两遍），'
                 '本格只多一道「推送状态」=「已推送」')


# ---------------------------------------------------------------------------
# 【17】G16 业务系统数量（资产表「所属业务」列里出现过多少种不同的内容）
# ---------------------------------------------------------------------------
#
# 这一格只读资产表**一列**，判据一句话：把「所属业务」列的值逐个读出来、去重成一个集合、
# 数集合里有几个。表里的行就是围着这一句话排的：
#   · 整格算一个条目、**不按逗号拆**：`OA系统, 财务系统`（加工脚本按逗号拆过再拼回来的
#     形态，见 scripts/process_asset_table.py）是**一个**条目 —— 拆开数会少一种
#   · 整格口径下 `财务系统, OA系统` 与上一条**不是**同一个条目（字面顺序变了就是另一种内容）
#   · 去首尾空白 + 转小写：`  oa系统  ` 与 `OA系统` 算一个
#   · 完全相同的内容出现两次只算一个（两条「运维系统」）
#   · 空的跳过：空串、纯空白都不算一种业务系统
#   · 平台的**横杠占位符**也跳过（用户口径 2026-10-12「- 不算」）：`-` 在 mssw 导出里是
#     列级的「无 / 不适用」标记，不是一种取值 —— 判据与那 35 格名次格同一处
#     （stats/metrics/ranking.js 的 isBlankValue，半角 / 全角 / 长破折号都认）
# ⚠️ 这一格与 `--business-systems` 无关（问的是"资产表里登记了几种业务"，
#    不是"传进来的那几个系统"）—— 段里专门拿「不传」与「只传一个」对撞一次。
# ⚠️ 也不叠加报告期过滤：资产表导出的是当前台账，本仓不另加时间条件。
G16_ASSET_TABLE = [
    ['IP地址', '所属业务', '重要级别'],
    ['10.0.0.1', 'OA系统, 财务系统', '核心'],    # 整格一个条目（拆开会变出两种）
    ['10.0.0.2', '财务系统, OA系统', '普通'],    # 顺序不同的同一对 -> 整格口径下是另一种内容
    ['10.0.0.3', 'OA系统', '核心'],              # 与前两条都不同
    ['10.0.0.4', '  oa系统  ', '核心'],          # 去首尾空白 + 转小写 -> 与上一条同一个
    ['10.0.0.5', '运维系统', '核心'],
    ['10.0.0.6', '运维系统', '普通'],            # 完全相同 -> 不再多算一个
    ['10.0.0.7', '', '核心'],                    # 空 -> 跳过
    ['10.0.0.8', '   ', '核心'],                 # 纯空白 -> 跳过
    ['10.0.0.9', '-', '核心'],                   # 占位符 -> 跳过（用户口径 2026-10-12）
    ['10.0.0.10', '－', '核心'],                 # 全角横杠是同一个占位符 -> 也跳过
    ['10.0.0.11', '—', '普通'],                  # 长破折号同理
]

# 上面那 11 行归一后是 4 种：`oa系统, 财务系统` / `财务系统, oa系统` / `oa系统` / `运维系统`。
# 几个"实现走偏时会得到什么"：按逗号拆开 -> 3；忘了转小写 -> 5；忘了去重 -> 7；
# 把 `-` / `－` / `—` 三个占位符当内容 -> 7。所以这一个数就能把它们分开。
G16_EXPECTED_COUNT = 4

# 把「所属业务」整列置空 / 只留空白 / 只留占位符的一份（有行、有这一列，只是没内容）：
# 用户口径下那是 0（"一台资产都没登记过业务归属"是结论，不是缺数）。
G16_BLANK_ASSET_TABLE = [
    ['IP地址', '所属业务', '重要级别'],
    ['10.0.0.1', '', '核心'],
    ['10.0.0.2', '   ', '普通'],
    ['10.0.0.3', '', '核心'],
    ['10.0.0.4', '-', '核心'],                 # 整列只剩占位符 -> 与"整列为空"同一个落法
    ['10.0.0.5', ' －', '普通'],               # 带首尾空白的全角横杠同样是占位符
]


def make_g16_tables(directory):
    """G16 专用 fixture：一份资产表（表头是**真实列名**：平台导出的「所属业务」）。"""
    directory.mkdir(parents=True, exist_ok=True)
    return {'asset': write_sheet(directory / 'g16-asset.xlsx', G16_ASSET_TABLE)}


def check_business_system_count(checker, bridge, workdir, tables, fixtures):
    """G16「业务系统数量」：一列、一句判据，四条边界。

    边界四条：
      · 资产表为空（0 行）-> 写 0、不报错
      · 有行但「所属业务」整列为空 / 全是空白 / 只剩占位符 -> 写 0、不报错
        （与"表为空"同一落法、不同理由）
      · 有行却缺「所属业务」列 -> 不写值 + 报错（点明缺的是哪一列）
      · 缺「IP地址」列 -> 本格照常落值（它不读 IP）；同一份表上 D7/D8/D9 不写值
        —— 一张资产表上的两把钥匙互不牵连（与【10】里那条镜像成对）

    另有一段专门证明它与 `--business-systems` 无关：不传 / 只传一个系统，数都不变。
    """
    checker.section('17】G16 业务系统数量（资产表「所属业务」列里不同内容的条目数）')

    edges = workdir / 'business-system-count'
    edges.mkdir(parents=True, exist_ok=True)

    def plan(asset, business_systems=CORE_SYSTEMS):
        paths = {}
        if asset:
            paths['asset'] = asset
        return call_bridge(bridge, 'plan', 'core', _b64(json.dumps({
            'paths': paths,
            'businessSystems': business_systems,
        })))

    def g16_of(result):
        return {w['addr']: w['value'] for w in result['writes']
                if w['addr'] in EXPECTED_BUSINESS_SYSTEM_CELLS}

    def g16_errors_of(result):
        return {e['addr']: e['message'] for e in result['errors']
                if e['addr'] in EXPECTED_BUSINESS_SYSTEM_CELLS}

    # —— 正题：11 行 -> 4 种不同内容（整格算一个条目、去重、去空白转小写、空的与占位符跳过）
    result = plan(tables['asset'])
    checker.check(g16_of(result) == {'G16': G16_EXPECTED_COUNT},
                  f'G16 = 「所属业务」列里不同内容的条目数（{G16_EXPECTED_COUNT} 种：'
                  '整格算一个条目不按逗号拆、完全相同只算一个、去首尾空白 + 转小写后相同的算一个、'
                  '空 / 纯空白 / 横杠占位符都跳过）',
                  json.dumps(g16_of(result), ensure_ascii=False),
                  json.dumps({'G16': G16_EXPECTED_COUNT}, ensure_ascii=False))
    checker.check(not g16_errors_of(result), 'G16 不缺数',
                  json.dumps(g16_errors_of(result), ensure_ascii=False), '（无）')
    checker.note('整格 vs 按逗号拆',
                 f'这一份 fixture 上整格口径得 {G16_EXPECTED_COUNT} 种；'
                 '把 `OA系统, 财务系统` 按逗号拆开只剩 3 种 —— '
                 '「精确查找、不拆」这条口径与拆分实现的分界就在这里')
    checker.note('占位符不算',
                 '这一列上排了 `-` / `－` / `—` 三个横杠占位符（含带首尾空白的），'
                 '一个都没进集合 —— 判据与那 35 格名次格同一处'
                 '（stats/metrics/ranking.js 的 isBlankValue）')

    # —— 与 --business-systems 无关：不传 / 只传一个系统，本格的数都不动。
    #    同一次跑里 D6:D9 / G6/H6/I6 / G10 会因为没传系统而写 0，那正是"它们要看系统名"的对照。
    none_systems = plan(tables['asset'], [])
    checker.check(g16_of(none_systems) == {'G16': G16_EXPECTED_COUNT},
                  f'不传 --business-systems -> G16 不变（还是 {G16_EXPECTED_COUNT}）'
                  '：本格问的是"资产表里登记了几种业务"，不是"传进来的那几个系统"',
                  json.dumps(g16_of(none_systems), ensure_ascii=False),
                  json.dumps({'G16': G16_EXPECTED_COUNT}, ensure_ascii=False))
    one_system = plan(tables['asset'], CORE_SYSTEMS[:1])
    checker.check(g16_of(one_system) == {'G16': G16_EXPECTED_COUNT},
                  '只传 1 个系统 -> G16 同样不变（它不做子串匹配、也不按系统名过滤）',
                  json.dumps(g16_of(one_system), ensure_ascii=False),
                  json.dumps({'G16': G16_EXPECTED_COUNT}, ensure_ascii=False))
    checker.check(not g16_errors_of(none_systems) and not g16_errors_of(one_system),
                  '这两种传法下 G16 都不进 errors（它压根不看系统名）',
                  json.dumps(dict(g16_errors_of(none_systems), **g16_errors_of(one_system)),
                             ensure_ascii=False), '（无）')

    # —— 落盘：内存里对不算数（与【6】【7】同一套路）
    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-g16.xlsx'),
        'tables': fixtures,
        'statsPaths': {'asset': tables['asset']},
        'businessSystems': CORE_SYSTEMS,
        'beautify': False,
    })))
    ws = load_workbook(built['filePath'], data_only=False)[TEMPLATE_SHEET]
    actual = ws['G16'].value
    checker.check(actual == G16_EXPECTED_COUNT,
                  'G16 落盘（「数据统计」sheet 上那一格 = 计划里的那个数；'
                  '模板那一格原本是空的，落 0 也会是一次真变化）',
                  repr(actual), G16_EXPECTED_COUNT)

    # —— 边界一：资产表为空（0 行）-> 写 0、不报错（0 是结论，不是缺数）
    result = plan(None)
    checker.check(g16_of(result) == {'G16': 0} and not g16_errors_of(result),
                  '资产表为空（0 行）-> 写 0、不报错',
                  json.dumps(g16_of(result), ensure_ascii=False),
                  json.dumps({'G16': 0}, ensure_ascii=False))

    # —— 边界二：有行、但「所属业务」整列为空 / 全是空白 -> 同样是 0（有这一列，只是没内容）。
    #    这一条与"表为空"落法相同、理由不同，两条都要在。
    blank = write_sheet(edges / 'blank-business.xlsx', G16_BLANK_ASSET_TABLE)
    result = plan(blank)
    checker.check(g16_of(result) == {'G16': 0} and not g16_errors_of(result),
                  '「所属业务」整列为空 / 全是空白 / 只剩横杠占位符 -> 写 0、不报错'
                  '（那正是"一台资产都没登记过业务归属"）',
                  json.dumps(g16_of(result), ensure_ascii=False),
                  json.dumps({'G16': 0}, ensure_ascii=False))

    # —— 边界三：有行、却缺「所属业务」列（平台改了列名）-> 不写值 + 报错。
    #    这一条与上面"整列为空 -> 0"是分界：列名对不上不是"没有业务归属"。
    no_business = write_sheet(edges / 'no-business.xlsx', [
        ['IP地址', '互联网暴露', '资产名称'],
        ['10.0.0.1', '暴露', 'a'],
    ])
    result = plan(no_business)
    checker.check(not g16_of(result), '资产表缺「所属业务」列 -> G16 一个值都不写',
                  json.dumps(g16_of(result), ensure_ascii=False), '（无）')
    errors = g16_errors_of(result)
    checker.check(sorted(errors) == ['G16'], '资产表缺「所属业务」列 -> 只有 G16 进错误列表',
                  ' '.join(sorted(errors)), 'G16')
    checker.check(all('找不到「所属业务」' in m and '资产表' in m for m in errors.values()),
                  '错误信息点明是**资产表**缺「所属业务」列（不是"没有业务归属"）',
                  json.dumps(errors.get('G16'), ensure_ascii=False))

    # —— 边界四：资产表缺「IP地址」列 -> G16 照常落值（本格一个字都不读 IP）；
    #    同一份表上要 IP 的 D7/D8/D9（与 G6/H6/I6）不写值 —— 两把钥匙互不牵连。
    #    与【10】里那条「少了「所属业务」列 -> D6:D9 缺数、D11 照算」正好互为镜像。
    no_ip = write_sheet(edges / 'no-ip.xlsx', [
        ['互联网暴露', '所属业务', '重要级别'],
        ['暴露', 'OA系统, 财务系统', '核心'],
        ['暴露', 'OA系统', '普通'],
    ])
    result = plan(no_ip)
    checker.check(g16_of(result) == {'G16': 2},
                  '资产表缺「IP地址」列 -> G16 照常落值（2 种）—— 本格不读 IP',
                  json.dumps(g16_of(result), ensure_ascii=False),
                  json.dumps({'G16': 2}, ensure_ascii=False))
    need_ip = [w['addr'] for w in result['writes']
               if w['addr'] in ['D6', 'D7', 'D8', 'D9'] + EXPECTED_CORE_SYSTEM_EVENT_CELLS
               + ['G6', 'H6', 'I6']]
    checker.check(not need_ip,
                  '同一份表上 D6:D9 / G6/H6/I6 / G10 一个值都不写（它们要「IP地址」）'
                  '—— 一张资产表上的两把钥匙互不牵连',
                  ' '.join(need_ip) or '（无）', '（无）')
    names = {w['addr']: w['value'] for w in result['writes']
             if w['addr'] in EXPECTED_CORE_SYSTEM_NAME_CELLS}
    checker.check(names == dict(zip(EXPECTED_CORE_SYSTEM_NAME_CELLS, CORE_SYSTEMS)),
                  '对照：D3/D4/D5 照常写系统名（它们不读资产表、只认 CLI 槽位）'
                  '—— 缺 IP 列卡住的只是那几格算数',
                  json.dumps(names, ensure_ascii=False),
                  json.dumps(dict(zip(EXPECTED_CORE_SYSTEM_NAME_CELLS, CORE_SYSTEMS)),
                             ensure_ascii=False))


# ---------------------------------------------------------------------------
# 【18】G17 服务器资产数量 / G18 PC资产数量（资产表「资产类型(一级)」整格精确等于某值的行数）
# ---------------------------------------------------------------------------
#
# 两格读**同一列**、同一句话，只差一个待匹配的类型值（G17「服务器」、G18「终端」），
# 所以口径共用 stats/metrics/asset.js 的 assetCountByPrimaryType（H4）、验收共用这一段。
# 表里的行就是围着「精确相等」这一句话排的：
#   · 真命中：整格就是「服务器」/「终端」-> 各 +1（按**行数**计，同一 IP 出现两行就是 2）
#   · 首尾空白不算差异：` 服务器 ` 去空白后相等 -> 算（与 D15/G8 那几格同一把尺子）
#   · **包含不等于相等**：`服务器区` 不算 G17、`终端区` 不算 G18
#     —— 这条最容易顺手写成 includes / startsWith
#   · 别的类型值：`网络设备` 两格都不算（两格的关键词互斥）
#   · 「资产类型(二级)」那一列**一个字都不读**：一级写「网络设备」、二级写「服务器」的那一行
#     两格都不进（读二级会把它算进 G17）
#   · 空值 / 平台的横杠占位符 `-` 不算
# ⚠️ 与 `--business-systems` 无关（圈的是资产类型，不是业务系统）—— 段里拿「不传」对撞一次。
# ⚠️ 也不叠加报告期过滤：资产表导出的是当前台账，本仓不另加时间条件。
# ⚠️ 只读「资产类型(一级)」这一列：资产表缺「IP地址」列时本组照常落值（另几把钥匙不写值）
#    —— 与【17】末尾那条同一形状，只是换了一把钥匙。
G17_G18_ASSET_TABLE = [
    ['IP地址', '所属业务', '重要级别', '资产类型(一级)', '资产类型(二级)'],
    ['10.0.0.1', 'OA系统', '核心', '服务器', '未知'],        # G17 +1
    ['10.0.0.2', '财务系统', '普通', '服务器', '未知'],      # G17 +1
    ['10.0.0.3', 'OA系统', '核心', '终端', '未知'],          # G18 +1
    ['10.0.0.4', '', '普通', '终端', '未知'],                # G18 +1（业务归属为空与本格无关）
    ['10.0.0.5', 'OA系统', '普通', '网络设备', '服务器'],     # 一级是网络设备 -> 两格都不算（二级不看）
    ['10.0.0.6', 'OA系统', '普通', '', '服务器'],            # 一级为空 -> 两格都不算
    ['10.0.0.7', 'OA系统', '普通', '服务器区', '未知'],       # 包含但不等 -> 不算 G17
    ['10.0.0.8', 'OA系统', '普通', ' 服务器 ', '未知'],       # 首尾空白 -> 算 G17
    ['10.0.0.9', 'OA系统', '普通', '终端区', '未知'],         # 包含但不等 -> 不算 G18
    ['10.0.0.10', 'OA系统', '普通', '-', '未知'],            # 占位符 -> 两格都不算
]

# 上面 10 行的期望：G17 = 3（第 1/2/8 行）、G18 = 2（第 3/4 行）。
# 几个"实现走偏时会得到什么"：写成包含 -> G17=4 / G18=3（`服务器区`、`终端区` 混进来）；
# 读「资产类型(二级)」-> G17 多算第 5 行；不去首尾空白 -> G17=2。
G17_EXPECTED_COUNT = 3
G18_EXPECTED_COUNT = 2

# 这一列整列为空 / 只剩占位符的一份（有行、有这一列，只是没内容）：
# 用户口径下那是 0（"台账里没有这类资产"是结论，不是缺数）。
G17_G18_BLANK_ASSET_TABLE = [
    ['IP地址', '所属业务', '重要级别', '资产类型(一级)'],
    ['10.0.0.1', 'OA系统', '核心', ''],
    ['10.0.0.2', '财务系统', '普通', '   '],       # 纯空白
    ['10.0.0.3', 'OA系统', '核心', '-'],          # 占位符
]


def make_g17_g18_tables(directory):
    """G17/G18 专用 fixture：一份资产表（表头是**真实列名**：「资产类型(一级)」半角括号）。"""
    directory.mkdir(parents=True, exist_ok=True)
    return {'asset': write_sheet(directory / 'g17-asset.xlsx', G17_G18_ASSET_TABLE)}


def check_asset_type_count(checker, bridge, workdir, tables, fixtures):
    """G17「服务器资产数量」/ G18「PC资产数量」：同一列、各认一个值，四条边界。

    边界四条：
      · 资产表为空（0 行）-> 两格都写 0、不报错
      · 有行但这一列整列为空 / 全是空白 / 只剩占位符 -> 同样是 0（与"表为空"同一落法）
      · 有行却缺「资产类型(一级)」列 -> 两格都不写值 + 报错（点明缺的是哪一列）
      · 缺「IP地址」列 -> 两格照常落值（它们不读 IP）；同一份表上 D6:D9 / G6/H6/I6 / G10 不写值

    另有一段专门证明它与 `--business-systems` 无关：不传 / 只传一个系统，两个数都不变。
    """
    checker.section('18】G17 服务器资产数量 / G18 PC资产数量（资产表「资产类型(一级)」精确相等）')

    edges = workdir / 'asset-type-count'
    edges.mkdir(parents=True, exist_ok=True)

    def plan(asset, business_systems=CORE_SYSTEMS):
        paths = {}
        if asset:
            paths['asset'] = asset
        return call_bridge(bridge, 'plan', 'core', _b64(json.dumps({
            'paths': paths,
            'businessSystems': business_systems,
        })))

    def counts_of(result):
        return {w['addr']: w['value'] for w in result['writes']
                if w['addr'] in EXPECTED_ASSET_TYPE_CELLS}

    def errors_of(result):
        return {e['addr']: e['message'] for e in result['errors']
                if e['addr'] in EXPECTED_ASSET_TYPE_CELLS}

    expected_counts = {'G17': G17_EXPECTED_COUNT, 'G18': G18_EXPECTED_COUNT}

    # —— 正题：10 行 -> 服务器 3 台、终端 2 台（精确相等、去首尾空白、包含不算、二级不看）
    result = plan(tables['asset'])
    checker.check(counts_of(result) == expected_counts,
                  f"G17 = {G17_EXPECTED_COUNT}（整格精确等于「服务器」的行数）、"
                  f"G18 = {G18_EXPECTED_COUNT}（精确等于「终端」）"
                  '—— 首尾空白去掉后相等算命中，`服务器区` / `终端区` 这种包含写法**不算**，'
                  '「网络设备」两格都不算，二级那一列一个字都不读',
                  json.dumps(counts_of(result), ensure_ascii=False),
                  json.dumps(expected_counts, ensure_ascii=False))
    checker.check(not errors_of(result), '两格都不缺数',
                  json.dumps(errors_of(result), ensure_ascii=False), '（无）')
    checker.note('精确 vs 包含',
                 '这一列上排了 `服务器区`（G17）与 `终端区`（G18）两个"含关键词但不是这个值"的格子，'
                 '一个都没算进去；把判据写成 includes / startsWith 的话 G17 会变成 4、G18 变成 3')
    checker.note('一级 vs 二级',
                 '第 5 行一级是「网络设备」、二级写着「服务器」—— 两格都没算它：'
                 '本组只读「资产类型(一级)」这一列')

    # —— 与 --business-systems 无关：不传 / 只传一个系统，两个数都不动。
    #    同一次跑里 D6:D9 / G6/H6/I6 / G10 会因为没传系统而写 0，那正是"它们要看系统名"的对照。
    none_systems = plan(tables['asset'], [])
    checker.check(counts_of(none_systems) == expected_counts,
                  '不传 --business-systems -> 两格都不变：本组圈的是资产类型，不是业务系统',
                  json.dumps(counts_of(none_systems), ensure_ascii=False),
                  json.dumps(expected_counts, ensure_ascii=False))
    one_system = plan(tables['asset'], CORE_SYSTEMS[:1])
    checker.check(counts_of(one_system) == expected_counts,
                  '只传 1 个系统 -> 同样不变（本组不做子串匹配、也不按系统名过滤）',
                  json.dumps(counts_of(one_system), ensure_ascii=False),
                  json.dumps(expected_counts, ensure_ascii=False))
    checker.check(not errors_of(none_systems) and not errors_of(one_system),
                  '这两种传法下两格都不进 errors（它们压根不看系统名）',
                  json.dumps(dict(errors_of(none_systems), **errors_of(one_system)),
                             ensure_ascii=False), '（无）')

    # —— 落盘：内存里对不算数（与【6】【7】【17】同一套路）
    built = call_bridge(bridge, 'build', _b64(json.dumps({
        'outputPath': str(workdir / 'out-g17.xlsx'),
        'tables': fixtures,
        'statsPaths': {'asset': tables['asset']},
        'businessSystems': CORE_SYSTEMS,
        'beautify': False,
    })))
    ws = load_workbook(built['filePath'], data_only=False)[TEMPLATE_SHEET]
    for addr, expected in expected_counts.items():
        actual = ws[addr].value
        checker.check(actual == expected,
                      f'{addr} 落盘（「数据统计」sheet 上那一格 = 计划里的那个数；'
                      '模板那一格原本是空的，落 0 也会是一次真变化）',
                      repr(actual), expected)

    # —— 边界一：资产表为空（0 行）-> 两格都写 0、不报错（0 是结论，不是缺数）
    result = plan(None)
    checker.check(counts_of(result) == {'G17': 0, 'G18': 0} and not errors_of(result),
                  '资产表为空（0 行）-> 两格都写 0、不报错',
                  json.dumps(counts_of(result), ensure_ascii=False),
                  json.dumps({'G17': 0, 'G18': 0}, ensure_ascii=False))

    # —— 边界二：有行、但这一列整列为空 / 全是空白 / 只剩占位符 -> 同样是 0。
    #    这一条与"表为空"落法相同、理由不同，两条都要在。
    blank = write_sheet(edges / 'blank-type.xlsx', G17_G18_BLANK_ASSET_TABLE)
    result = plan(blank)
    checker.check(counts_of(result) == {'G17': 0, 'G18': 0} and not errors_of(result),
                  '「资产类型(一级)」整列为空 / 全是空白 / 只剩横杠占位符 -> 两格都写 0、不报错'
                  '（那正是"台账里没有这类资产"）',
                  json.dumps(counts_of(result), ensure_ascii=False),
                  json.dumps({'G17': 0, 'G18': 0}, ensure_ascii=False))

    # —— 边界三：有行、却缺「资产类型(一级)」列（平台改了列名）-> 不写值 + 报错。
    #    这一条与上面"整列为空 -> 0"是分界：列名对不上不是"没有这类资产"。
    #    用半角 / 全角括号的差别都把这一列遮掉，验的是**整格列名**逐字相等。
    no_type = write_sheet(edges / 'no-type.xlsx', [
        ['IP地址', '所属业务', '重要级别', '资产类型（一级）'],   # 全角括号 = 另一个列名
        ['10.0.0.1', 'OA系统', '核心', '服务器'],
    ])
    result = plan(no_type)
    checker.check(not counts_of(result),
                  '资产表缺「资产类型(一级)」列（这一份写的是全角括号）-> 两格一个值都不写',
                  json.dumps(counts_of(result), ensure_ascii=False), '（无）')
    errors = errors_of(result)
    checker.check(sorted(errors) == ['G17', 'G18'],
                  '资产表缺「资产类型(一级)」列 -> 只有这两格进错误列表',
                  ' '.join(sorted(errors)), 'G17 G18')
    checker.check(all('找不到「资产类型(一级)」' in m and '资产表' in m for m in errors.values()),
                  '错误信息点明是**资产表**缺「资产类型(一级)」列（不是"没有这类资产"）',
                  json.dumps(errors.get('G17'), ensure_ascii=False))

    # —— 边界四：资产表缺「IP地址」列 -> 两格照常落值（本组一个字都不读 IP）；
    #    同一份表上要 IP 的 D6:D9（与 G6/H6/I6、G10）不写值 —— 与【17】末尾那条互为镜像。
    no_ip = write_sheet(edges / 'no-ip.xlsx', [
        ['互联网暴露', '所属业务', '重要级别', '资产类型(一级)'],
        ['暴露', 'OA系统', '核心', '服务器'],
        ['未暴露', 'OA系统', '普通', '服务器'],
        ['未暴露', 'OA系统', '普通', '终端'],
    ])
    result = plan(no_ip)
    checker.check(counts_of(result) == {'G17': 2, 'G18': 1},
                  '资产表缺「IP地址」列 -> 两格照常落值（服务器 2 / 终端 1）—— 本组不读 IP',
                  json.dumps(counts_of(result), ensure_ascii=False),
                  json.dumps({'G17': 2, 'G18': 1}, ensure_ascii=False))
    need_ip = [w['addr'] for w in result['writes']
               if w['addr'] in ['D6', 'D7', 'D8', 'D9'] + EXPECTED_CORE_SYSTEM_EVENT_CELLS
               + ['G6', 'H6', 'I6']]
    checker.check(not need_ip,
                  '同一份表上 D6:D9 / G6/H6/I6 / G10 一个值都不写（它们要「IP地址」）'
                  '—— 一张资产表上的两把钥匙互不牵连',
                  ' '.join(need_ip) or '（无）', '（无）')


# ---------------------------------------------------------------------------
# 入口
# ---------------------------------------------------------------------------

def main():
    # JS 侧传进来的参数过了 encodePath（B64: 前缀），中文路径要靠它还原
    decode_argv()
    options = json.loads(sys.argv[1]) if len(sys.argv) > 1 else {}
    repo = Path(options.get('repo') or Path(__file__).resolve().parent.parent)
    bridge = Path(options.get('bridge') or (repo / 'scripts' / 'verify_write_layer.js'))
    template = repo / 'data.xlsx'

    if not template.exists():
        raise SystemExit(f'模板不存在: {template}')

    workdir = Path(tempfile.mkdtemp(prefix='v2-verify-'))
    checker = Checker()

    try:
        print('=' * 72)
        print('  写入层验收 —— 「数据统计」取值层 / 表格预处理 / 交付路径')
        print('=' * 72)
        print(f'  模板 {template}')
        print(f'  临时目录 {workdir}')

        check_plan_registry(checker, bridge)
        check_modes(checker, bridge, template)

        fixtures = make_fixtures(workdir / 'fixtures')
        ctx_state = {}

        def build(label, name, beautify):
            result = call_bridge(bridge, 'build', _b64(json.dumps({
                'outputPath': str(workdir / name),
                'tables': fixtures,
                'beautify': beautify,
            })))
            ctx_state[label] = result
            return result

        plain = build('plain', 'out.xlsx', beautify=False)
        check_end_to_end(checker, 'plain', template, plain['filePath'], plain, beautify=False)
        # 【3.5】用的是它**自己那一份** fixture（资产表 + 只有「影响资产/事件名称」两列的事件表）：
        # 预处理会在那儿走"凑不齐时间列"那条路，与上面那次 build 读的表不是同一份。
        check_preprocess(checker, bridge, workdir, fixtures)

        pretty = build('pretty', 'out-beautified.xlsx', beautify=True)
        check_end_to_end(checker, 'pretty', template, pretty['filePath'], pretty, beautify=True)

        # 告警定性统计（C133:I134）：读取层契约 + 接了总表之后的落盘结果。
        # 上面那两段 build **不带**总表，验的是"没表时 14 格写空串"；这两段验的是
        # "有表时真的落值"。两半都得有 —— 各自都对、接起来不匹配，正是这次"没落盘"的病根。
        check_alarm_reader(checker, workdir)
        check_alarm_end_to_end(checker, bridge, workdir, fixtures, make_alarm_table(workdir / 'fixtures'))

        # 告警表搬进报告时逐格原样（带括号的「主机IP」不许被顺手洗掉）：与上面几段 build
        # 分开跑，这条才是那张真的带括号后缀的告警表落进报告的现场。
        check_alarm_ip_passthrough(checker, bridge, workdir, fixtures)

        # 事件表三个时长列：同一阶段的第 4 步，同样与【3.5】那次 build 分开跑 ——
        # 那份事件表只有「影响资产/事件名称」两列，走的是"凑不齐时间列就不算"那条路
        # （【3.5】里已经钉了它），这一段才是真算数的现场。
        check_duration_columns(checker, bridge, workdir, fixtures)

        # 核心业务系统（D3/D4/D5 + D6 合计 + D7/D8/D9）：接上四份总表与 --business-systems
        # 之后才落值。上面那两段 build **不带**这两样，验的是"没传系统槽位时 7 格记 errors"。
        check_core_system(checker, bridge, workdir, fixtures, template)

        # 事件定性统计（C135:I137）：与【6】同一套排行算法，换数据源与列名。
        # 同样两半 —— 上面两段 build 不带事件总表（那份是空表，21 格写空串），这段验"有表时真落值"。
        check_event_end_to_end(checker, bridge, workdir, fixtures,
                               make_event_table(workdir / 'fixtures'))

        # 漏洞表那两格（D10 行数 / D12 去重台数）：都只读漏洞表，与 --business-systems 无关。
        # 用【7】那份漏洞 fixture —— 同一张表三种口径（全表行数 3 / 全表去重台数 2 /
        # 圈定 IP 2、2、0）分得开。
        check_high_exploitable_vuln(checker, bridge, workdir,
                                    make_high_exploitable_vuln_table(workdir / 'fixtures'))

        # 威胁告警数量（G5 整表数 + G6/H6/I6 按核心业务系统圈定）：与 D3/D4/D5 同一批
        # 系统名、同一张资产表，所以 fixture 也是那一份资产表 —— 「同一台机器属于两个系统」
        # 这条边界两段共用同一个事实。
        threat_tables = make_threat_alarm_tables(workdir / 'fixtures')
        check_threat_alarms(checker, bridge, workdir, fixtures,
                            threat_tables['alarm'], threat_tables['asset'])

        # G8 处置安全事件总数（事件表「处置状态」）：与【8】同一份事件表、另一列。
        # 【7】那一份 core fixture 上已经顺带钉过一次它的值（CORE_EVENT_DISPOSED_COUNT），
        # 这一段换一份专门铺满判据的表，钉住"精确匹配"这条线本身。
        check_disposed_events(checker, bridge, workdir,
                              make_disposition_event_table(workdir / 'fixtures'))

        # D16 已处置弱口令数量（弱密码表「处置状态」+ 事件表「二级分类含弱口令且处置完成」）：
        # 跨两份表，所以 fixture 也是两份。【7】那一份 core fixture 上已经顺带钉过它的值
        # （CORE_DISPOSED_WEAKPWD_TOTAL），这一段铺满两段的正反例与缺列边界。
        d16_weakpwd, d16_event = make_d16_tables(workdir / 'fixtures')
        check_disposed_weakpwd(checker, bridge, workdir, d16_weakpwd, d16_event)

        # G7 威胁平均遏制时间（事件表「GPT研判结论」命中行 × 遏制时长的非空均值）：
        # 「遏制时长」不是平台导出的列，是预处理按「事件遏制时间 − 专家研判时间」算出来、
        # 在**下载之后、解析之前**追加到下载件上的，所以这一段必须按生产的顺序造表 ——
        # 写 fixture -> 先跑一次 preprocess（原地改写它）-> 再 `plan event` -> 再 build。
        # 段末的「对撞」因此变成了同一条链两端的对齐：报告 sheet 上那一列在命中行上的值，
        # 必须与 G7 进分母的那几个数逐个相同。
        check_contained_minutes(checker, bridge, workdir, fixtures,
                                make_g7_event_table(workdir / 'fixtures'))

        # G10 核心系统事件数量（全部核心系统的 IP 并集 × 事件表「影响资产」精确命中）：
        # 跨资产表 / 事件表 / --business-systems 三处。【7】那份 core fixture 上已经顺带钉过
        # 它的值（CORE_EVENT_UNION_COUNT），这一段铺满"命中什么 / 不命中什么"的正反例
        # 与三条缺数边界（缺列 / 空表 / 没传系统）。
        check_core_system_events(checker, bridge, workdir,
                                 make_g10_tables(workdir / 'fixtures'), fixtures)

        # G9 事件平均响应时长（G8 那批已处置行 × 「推送状态」=「已推送」× 响应时长非空均值）：
        # 与【14】同一条生产顺序 —— 时长列是预处理追加的，所以必须写 fixture -> 先 preprocess
        # -> 再 `plan event` -> 再 build。两道筛（处置状态复用 G8 的行、推送状态是本格独有）
        # 的分界、以及"没样本写 0"（与 G7 写空串刻意不同）都在这段里钉。
        check_response_minutes(checker, bridge, workdir, fixtures,
                               make_g9_event_table(workdir / 'fixtures'))

        # G16 业务系统数量（资产表「所属业务」列里不同内容的条目数）：只读资产表一列，
        # 与 --business-systems 无关。这一段铺满"整格算一个条目 / 去重 / 去空白转小写 /
        # 空的与横杠占位符跳过"的正反例，以及三条缺数边界（表为空 / 整列为空 / 缺「所属业务」列），
        # 外加一条与 D7:D9 的分界（缺「IP地址」列时本格照算、那几格不算）。
        check_business_system_count(checker, bridge, workdir,
                                    make_g16_tables(workdir / 'fixtures'), fixtures)

        # G17 服务器资产数量 / G18 PC资产数量（资产表「资产类型(一级)」里整格精确等于
        # 「服务器」/「终端」的行数）：两格读同一列、共用一个 metrics 函数，所以一段验完。
        # 铺的是"精确相等 vs 包含"（`服务器区` / `终端区` 不算）、"一级 vs 二级"（二级不看）、
        # 去首尾空白、别的类型值两格都不算，以及三条缺数边界（表为空 / 整列为空 / 缺这一列），
        # 外加一条与 D7:D9 的分界（缺「IP地址」列时这两格照算、那几格不算）。
        check_asset_type_count(checker, bridge, workdir,
                              make_g17_g18_tables(workdir / 'fixtures'), fixtures)

        print('\n' + '=' * 72)
        if checker.failures:
            print(f'  ✗ 验收未通过：{len(checker.failures)} 条')
            for name in checker.failures:
                print(f'      - {name}')
            # 退出码**必须是 2 不能是 1**：python_cmd.js 把「退出码 1 且 stderr 为空」
            # 当成"解释器不存在"（Windows 上 python3 的应用执行别名就那么退），
            # 用 1 的话入口会误以为 python 不可用，转头去试 python3 然后报 ENOENT。
            return 2
        print('  ✓ 全部通过')
        return 0
    finally:
        shutil.rmtree(workdir, ignore_errors=True)


def _b64(text):
    """跑 bridge 时把它要的参数编码成 B64:<base64>，与 path_helper.js 的 encodePath 对齐。"""
    import base64
    return 'B64:' + base64.b64encode(text.encode('utf-8')).decode('ascii')


if __name__ == '__main__':
    raise SystemExit(main())
